INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C1','math',5,2,'u1',2,'이상과 이하 — 그 수와 같거나 큰 수(이상)·같거나 작은 수(이하)는 경곗값을 포함하므로 수직선에 ●으로 나타내고, 생활 속 안내문(12세 이상 관람 가·2 L 이상)을 읽어 들어가는 수를 가리기',ARRAY['6수01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C2','math',5,2,'u1',3,'초과와 미만 — 그 수보다 큰 수(초과)·작은 수(미만)는 경곗값을 포함하지 않으므로 ○으로 나타내고, 이상·이하와 경곗값 하나 차이로 갈림을 알기',ARRAY['6수01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C3','math',5,2,'u1',4,'수의 범위 활용 — 두 조건을 겹쳐 「5 이상 10 미만」처럼 사이의 범위를 나타내고, 생활 속 표(체감 온도·요금·용량·평가 기준)가 한쪽 끝만 넣어 겹치지 않게 짜여 있음을 알고 읽기',ARRAY['6수01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C4','math',5,2,'u1',5,'올림 — 구하려는 자리의 아래 수를 올려서 나타내는 방법으로, 모자라면 안 되는 상황(묶음으로 사기)에서 쓰며 아래 수가 모두 0이면 올리지 않음을 알기(자연수·소수)',ARRAY['6수01-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C5','math',5,2,'u1',6,'버림 — 구하려는 자리의 아래 수를 어떤 수인지에 관계없이 버려서 나타내는 방법으로, 묶음으로 포장하거나 바꿀 때처럼 남는 것을 쓸 수 없는 상황에서 쓰기(자연수·소수)',ARRAY['6수01-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C6','math',5,2,'u1',7,'반올림 — 구하려는 자리 바로 아래 한 자리의 숫자가 0~4면 버리고 5~9면 올려 원래 수에 가장 가깝게 어림하는 방법임을 알고, 반올림한 값이 되는 원래 수의 범위를 거꾸로 찾기',ARRAY['6수01-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C7','math',5,2,'u1',8,'상황에 맞는 어림 방법 — 모자라면 안 되는 일은 올림, 남는 것을 쓸 수 없는 일은 버림, 실제와 차이를 작게 하려면 반올림임을 알고 수가 아니라 상황이 방법을 정함을 설명하기',ARRAY['6수01-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u1-C8','math',5,2,'u1',9,'문제 해결 — 판매 단위에 맞게 구입할 양은 올림하고, 비용은 단위 가격을 반올림해 어림셈한 뒤 실제 비용과 견주어, 한 문제 안에서도 구하는 것에 따라 어림 방법이 갈림을 알기',ARRAY['6수01-03']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X01','math',5,'u1',ARRAY['M5-2-u1-C1','M5-2-u1-C3']::text[],'이상·이하에서 경곗값을 빼 버린다(12세 이상에 12세가 들어가지 않는다고 본다)','이상·이하는 「같거나」 — 경곗값도 들어가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X02','math',5,'u1',ARRAY['M5-2-u1-C2','M5-2-u1-C3']::text[],'초과·미만에 경곗값을 넣어 버린다(10 kg 초과에 10 kg을 넣는다)','초과·미만은 경곗값이 빠져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X03','math',5,'u1',ARRAY['M5-2-u1-C1','M5-2-u1-C2','M5-2-u1-C3']::text[],'크다와 작다의 방향을 바꾼다(이상↔이하, 초과↔미만)','이상·초과는 큰 쪽, 이하·미만은 작은 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X04','math',5,'u1',ARRAY['M5-2-u1-C1','M5-2-u1-C2','M5-2-u1-C3']::text[],'수직선의 ●과 ○을 바꿔 읽는다(●을 「포함하지 않음」으로)','● 속이 참 = 포함, ○ 속이 빔 = 빠짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X05','math',5,'u1',ARRAY['M5-2-u1-C3']::text[],'두 조건이 겹친 범위에서 한쪽 조건만 보거나 양 끝의 포함을 똑같이 본다','왼쪽 끝·오른쪽 끝을 따로 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X07','math',5,'u1',ARRAY['M5-2-u1-C4']::text[],'아래 수가 모두 0인데도 올림한다(2500을 올림하여 백의 자리까지 2600으로)','올릴 것이 없으면 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X08','math',5,'u1',ARRAY['M5-2-u1-C4','M5-2-u1-C5','M5-2-u1-C6','M5-2-u1-C7','M5-2-u1-C8']::text[],'올림·버림·반올림을 서로 바꿔 쓴다(올림하라는데 반올림처럼 아래 숫자를 보고 버린다)','올림은 늘 올리고, 버림은 늘 버려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X09','math',5,'u1',ARRAY['M5-2-u1-C4','M5-2-u1-C5','M5-2-u1-C6','M5-2-u1-C7','M5-2-u1-C8']::text[],'구하려는 자리를 잘못 잡는다(십의 자리까지를 십의 자리 숫자를 버리는 것으로)','「○○의 자리까지」 — 그 자리는 남겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X10','math',5,'u1',ARRAY['M5-2-u1-C6','M5-2-u1-C7']::text[],'반올림할 때 바로 아래 한 자리가 아니라 맨 끝 자리부터 차례로 올린다(2449 → 2450 → 2500)','바로 아래 한 자리만 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X11','math',5,'u1',ARRAY['M5-2-u1-C6','M5-2-u1-C7']::text[],'반올림에서 바로 아래 숫자가 5일 때 버린다','0~4는 버리고 5~9는 올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X13','math',5,'u1',ARRAY['M5-2-u1-C7','M5-2-u1-C8']::text[],'상황에 맞지 않는 어림 방법을 고른다(모자라면 안 되는데 버림, 남는 것을 못 쓰는데 올림)','모자라면 안 되나요? 남으면 못 쓰나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X14','math',5,'u1',ARRAY['M5-2-u1-C4','M5-2-u1-C5','M5-2-u1-C7','M5-2-u1-C8']::text[],'묶음의 수와 실제 개수를 혼동한다(55묶음과 550개, 5봉지와 500 g)','묻는 것이 묶음 수인지 개수인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X15','math',5,'u1',ARRAY['M5-2-u1-C4','M5-2-u1-C5','M5-2-u1-C6']::text[],'어림한 값이 되는 원래 수의 범위를 거꾸로 찾지 못한다','어림하기 전 수를 하나씩 넣어 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X16','math',5,'u1',ARRAY['M5-2-u1-C1','M5-2-u1-C2','M5-2-u1-C3','M5-2-u1-C4','M5-2-u1-C5','M5-2-u1-C6','M5-2-u1-C7','M5-2-u1-C8']::text[],'방법은 맞았는데 한 걸음의 셈이나 세기를 잘못한다','한 걸음씩 다시 셈해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X17','math',5,'u1',ARRAY['M5-2-u1-C1','M5-2-u1-C2','M5-2-u1-C3','M5-2-u1-C4','M5-2-u1-C5','M5-2-u1-C6','M5-2-u1-C7','M5-2-u1-C8']::text[],'묻는 말을 거꾸로 읽는다 — 아닌↔맞는, 잘못↔바르게, 가장 큰↔가장 작은, 모두 고르기','물음의 「아닌·잘못·가장·모두」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X18','math',5,'u1',ARRAY['M5-2-u1-C4','M5-2-u1-C5','M5-2-u1-C6','M5-2-u1-C7']::text[],'어림하기 전과 뒤의 수를 한두 개만 보고 어림 방법을 정한다 — 버림과 반올림처럼 결과가 같은 경우를 가리지 않는다(익힘 21 국립 공원 넓이 · 형성 평가 민우의 걸음 수 · 지도서 162)','어림한 수를 모두 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u1-X19','math',5,'u1',ARRAY['M5-2-u1-C1','M5-2-u1-C2','M5-2-u1-C3']::text[],'수의 범위에 드는 수를 자연수만 떠올린다 — 2.1, 2.5 같은 소수·분수를 빼고 「몇 개뿐」이라고 한다(지도서 129~130·133~134 「셀 수 없이 많습니다」)','소수·분수도 들어가요 — 셀 수 없이 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#1','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'mc','auto','영화 「수리 마을 친구들」은 12세 이상 관람 가예요. 12세인 친구들은 이 영화를 볼 수 있나요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X17']::text[],true,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"영화 「수리 마을 친구들」은 12세 이상 관람 가예요. 12세인 친구들은 이 영화를 볼 수 있나요?","options":[{"t":"볼 수 있다 — 12세 이상에는 12세가 들어가서","correct":true},{"t":"볼 수 없다 — 12세보다 많아야 해서","mis":"M5-2-u1-X01"},{"t":"볼 수 없다 — 12세 이하만 볼 수 있어서","mis":"M5-2-u1-X03"},{"t":"보호자와 함께여야만 볼 수 있다","mis":"M5-2-u1-X17"}],"explanation":["12세 이상은 12세와 같거나 많은 나이예요.","「같거나」라서 딱 12세도 들어가요.","그래서 12세인 친구들은 볼 수 있어요."],"variant_rule":{"alt":[{"stem":"선거일 기준으로 18세 이상의 국민은 투표를 할 수 있어요. 18세인 연주의 언니는 투표를 할 수 있나요?","options":[{"t":"할 수 있다 — 18세 이상에는 18세가 들어가서","correct":true},{"t":"할 수 없다 — 18세보다 많아야 해서","mis":"M5-2-u1-X01"},{"t":"할 수 없다 — 18세 이하만 할 수 있어서","mis":"M5-2-u1-X03"},{"t":"보호자와 함께여야만 할 수 있다","mis":"M5-2-u1-X17"}],"explanation":["18세 이상은 18세와 같거나 많은 나이예요.","「같거나」라서 딱 18세도 들어가요.","그래서 18세인 언니는 투표를 할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#2','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'mc','auto','사과주스의 들이가 1.2 L, 2 L, 1.9 L, 2.8 L, 2.1 L, 3 L예요. 들이가 2 L 이상인 사과주스를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"사과주스의 들이가 1.2 L, 2 L, 1.9 L, 2.8 L, 2.1 L, 3 L예요. 들이가 2 L 이상인 사과주스를 모두 고른 것은 어느 것인가요?","options":[{"t":"2 L, 2.8 L, 2.1 L, 3 L","correct":true},{"t":"2.8 L, 2.1 L, 3 L","mis":"M5-2-u1-X01"},{"t":"1.2 L, 2 L, 1.9 L","mis":"M5-2-u1-X03"},{"t":"2 L, 2.8 L, 2.1 L","mis":"M5-2-u1-X16"}],"explanation":["2 이상인 수는 2와 같거나 큰 수예요.","경곗값을 살펴보면 2는 들어가요.","그래서 2 L, 2.8 L, 2.1 L, 3 L예요."],"variant_rule":{"alt":[{"stem":"세탁 세제의 들이가 2.7 L, 4 L, 3 L, 2.5 L, 3.7 L, 3.2 L예요. 들이가 3 L 이하인 세탁 세제를 모두 고른 것은 어느 것인가요?","options":[{"t":"2.7 L, 3 L, 2.5 L","correct":true},{"t":"2.7 L, 2.5 L","mis":"M5-2-u1-X01"},{"t":"4 L, 3 L, 3.7 L, 3.2 L","mis":"M5-2-u1-X03"},{"t":"2.7 L, 3 L","mis":"M5-2-u1-X16"}],"explanation":["3 이하인 수는 3과 같거나 작은 수예요.","경곗값을 살펴보면 3은 들어가요.","그래서 2.7 L, 3 L, 2.5 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#3','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'mc','auto','2와 같거나 큰 수를 무엇이라고 하나요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03']::text[],true,'{"seq":3,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"2와 같거나 큰 수를 무엇이라고 하나요?","options":[{"t":"2 이상인 수","correct":true},{"t":"2 초과인 수","mis":"M5-2-u1-X01"},{"t":"2 이하인 수","mis":"M5-2-u1-X03"},{"t":"2 미만인 수","mis":"M5-2-u1-X03"}],"explanation":["「같거나 큰 수」는 이상이에요.","2 이상인 수에는 2가 들어가요.","수직선에는 2에 ●을 그리고 오른쪽으로 선을 그어요."],"variant_rule":{"alt":[{"stem":"3과 같거나 작은 수를 무엇이라고 하나요?","options":[{"t":"3 이하인 수","correct":true},{"t":"3 미만인 수","mis":"M5-2-u1-X01"},{"t":"3 이상인 수","mis":"M5-2-u1-X03"},{"t":"3 초과인 수","mis":"M5-2-u1-X03"}],"explanation":["「같거나 작은 수」는 이하예요.","3 이하인 수에는 3이 들어가요.","수직선에는 3에 ●을 그리고 왼쪽으로 선을 그어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#4','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',1,'mc','auto','수직선에 13에 ●이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],true,'{"seq":4,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"수직선에 13에 ●이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"13 이상인 수","correct":true},{"t":"13 초과인 수","mis":"M5-2-u1-X04"},{"t":"13 이하인 수","mis":"M5-2-u1-X03"},{"t":"13 미만인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","13은 ●이라 들어가요.","그래서 13 이상인 수예요."],"variant_rule":{"alt":[{"stem":"수직선에 27에 ●이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"27 이하인 수","correct":true},{"t":"27 미만인 수","mis":"M5-2-u1-X04"},{"t":"27 이상인 수","mis":"M5-2-u1-X03"},{"t":"27 초과인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","27은 ●이라 들어가요.","그래서 27 이하인 수예요."]},{"stem":"수직선에 32에 ●이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"32 이하인 수","correct":true},{"t":"32 미만인 수","mis":"M5-2-u1-X04"},{"t":"32 이상인 수","mis":"M5-2-u1-X03"},{"t":"32 초과인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","32는 ●이라 들어가요.","그래서 32 이하인 수예요."]},{"stem":"수직선에 29에 ●이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"29 이하인 수","correct":true},{"t":"29 미만인 수","mis":"M5-2-u1-X04"},{"t":"29 이상인 수","mis":"M5-2-u1-X03"},{"t":"29 초과인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","29는 ●이라 들어가요.","그래서 29 이하인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#5','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'sa','auto','선거일 기준으로 18세 이상의 국민은 투표를 할 수 있어요. 연주네 가족 중에서 투표를 할 수 있는 사람은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u1-C1","difficulty":2,"kind":"sa","stem":"선거일 기준으로 18세 이상의 국민은 투표를 할 수 있어요. 연주네 가족 중에서 투표를 할 수 있는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["18세 이상은 18세와 같거나 많은 나이예요.","아버지 46세·어머니 45세는 18세보다 많고, 언니는 딱 18세라 들어가요.","12세인 연주만 빠지니 3명이에요."],"asset":{"type":"passage","lines":["연주네 가족의 나이","아버지 46세 · 어머니 45세 · 언니 18세 · 연주 12세"]},"variant_rule":{"alt":[{"stem":"제자리멀리뛰기 기록이 122 cm 이하인 학생은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["122 cm 이하는 122 cm와 같거나 짧은 기록이에요.","상현 105.6 cm·보겸 99.4 cm는 짧고, 재인은 딱 122 cm라 들어가요.","지호·세진은 빠지니 3명이에요."],"asset":{"type":"passage","lines":["지호네 모둠 학생들의 제자리멀리뛰기 기록","지호 141 cm · 상현 105.6 cm · 보겸 99.4 cm","재인 122 cm · 세진 175 cm"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#6','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'mc','auto','14.2, 24, 29.7, 33.8, 27, 40, 30, 20.5 중에서 30 이상인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":6,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"14.2, 24, 29.7, 33.8, 27, 40, 30, 20.5 중에서 30 이상인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"33.8, 40, 30","correct":true},{"t":"33.8, 40","mis":"M5-2-u1-X01"},{"t":"14.2, 24, 29.7, 27, 30, 20.5","mis":"M5-2-u1-X03"},{"t":"33.8, 40, 30, 14.2","mis":"M5-2-u1-X16"}],"explanation":["30 이상인 수는 30과 같거나 큰 수예요.","경곗값을 살펴보면 30은 들어가요.","그래서 33.8, 40, 30이에요."],"variant_rule":{"alt":[{"stem":"14.2, 24, 29.7, 33.8, 27, 40, 30, 20.5 중에서 24 이하인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"14.2, 24, 20.5","correct":true},{"t":"14.2, 20.5","mis":"M5-2-u1-X01"},{"t":"24, 29.7, 33.8, 27, 40, 30","mis":"M5-2-u1-X03"},{"t":"14.2, 24","mis":"M5-2-u1-X16"}],"explanation":["24 이하인 수는 24와 같거나 작은 수예요.","경곗값을 살펴보면 24는 들어가요.","그래서 14.2, 24, 20.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#7','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'mc','auto','기록이 9초 이하인 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"기록이 9초 이하인 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"지아, 미나","correct":true},{"t":"지아","mis":"M5-2-u1-X01"},{"t":"주원, 소희, 준후, 은솔","mis":"M5-2-u1-X03"},{"t":"준후, 지아, 미나","mis":"M5-2-u1-X16"}],"explanation":["9초 이하는 9초와 같거나 짧은 기록이에요.","지아 8.7초는 9초보다 짧고, 미나는 딱 9초라 들어가요.","준후 9.5초는 9초보다 길어서 빠져요 — 지아, 미나예요."],"asset":{"type":"passage","lines":["50 m 달리기 기록","주원 11.2초 · 소희 13초 · 준후 9.5초","지아 8.7초 · 은솔 12.4초 · 미나 9초"]},"variant_rule":{"alt":[{"stem":"기록이 167 cm 이상인 학생을 모두 고른 것은 어느 것인가요?","options":[{"t":"세진","correct":true},{"t":"지호, 상현, 보겸, 재인","mis":"M5-2-u1-X03"},{"t":"지호, 세진","mis":"M5-2-u1-X16"},{"t":"재인, 세진","mis":"M5-2-u1-X16"}],"explanation":["167 cm 이상은 167 cm와 같거나 긴 기록이에요.","세진 175 cm만 167 cm보다 길어요.","지호 141 cm는 167 cm보다 짧아서 빠져요 — 세진이에요."],"asset":{"type":"passage","lines":["지호네 모둠 학생들의 제자리멀리뛰기 기록","지호 141 cm · 상현 105.6 cm · 보겸 99.4 cm","재인 122 cm · 세진 175 cm"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#8','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'ox','auto','3 이하인 수에는 3이 들어가지 않아요.',ARRAY['M5-2-u1-X01']::text[],true,'{"seq":8,"concept":"M5-2-u1-C1","difficulty":2,"kind":"ox","stem":"3 이하인 수에는 3이 들어가지 않아요.","answer":"X","reason_options":[{"t":"이하는 「같거나 작은 수」라서 3도 들어가서","correct":true},{"t":"이하는 3보다 작은 수만 뜻해서","mis":"M5-2-u1-X01"}],"mis":"M5-2-u1-X01","explanation":["이하의 뜻에는 「같거나」가 들어 있어요.","그래서 3 이하인 수에는 3이 들어가요.","수직선에도 3에 ●을 그려요."],"variant_rule":{"alt":[{"stem":"2 이상인 수에는 2가 들어가요.","answer":"O","reason_options":[{"t":"이상은 「같거나 큰 수」라서 2도 들어가서","correct":true},{"t":"이상은 2보다 큰 수만 뜻해서","mis":"M5-2-u1-X01"}],"explanation":["이상의 뜻에는 「같거나」가 들어 있어요.","그래서 2 이상인 수에는 2가 들어가요.","수직선에도 2에 ●을 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#9','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',2,'mc','auto','㉠ 2.7 ㉡ 4.1 ㉢ ⟨3 3/4⟩ ㉣ 4 중에서 4보다 작은 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":9,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"㉠ 2.7 ㉡ 4.1 ㉢ ⟨3 3/4⟩ ㉣ 4 중에서 4보다 작은 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉠, ㉢, ㉣","mis":"M5-2-u1-X02"},{"t":"㉡, ㉣","mis":"M5-2-u1-X03"},{"t":"㉠","mis":"M5-2-u1-X16"}],"explanation":["4보다 작은 수에는 4 자신이 들어가지 않아요.","2.7과 ⟨3 3/4⟩은 4보다 작고, 4.1은 4보다 커요.","그래서 ㉠, ㉢이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_basic#10','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_basic','lesson_basic','M5-2-u1-C1',3,'mc','auto','획득한 금메달 수가 15개 이상인 나라를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":10,"concept":"M5-2-u1-C1","difficulty":3,"kind":"mc","stem":"획득한 금메달 수가 15개 이상인 나라를 모두 고른 것은 어느 것인가요?","options":[{"t":"네덜란드, 일본","correct":true},{"t":"일본","mis":"M5-2-u1-X01"},{"t":"대한민국, 독일, 스웨덴, 캐나다","mis":"M5-2-u1-X03"},{"t":"대한민국, 네덜란드, 일본","mis":"M5-2-u1-X16"}],"explanation":["15개 이상은 15개와 같거나 많은 수예요.","네덜란드는 딱 15개라 들어가고 일본 20개도 들어가요.","대한민국 13개는 15개보다 적어 빠져요 — 네덜란드, 일본이에요."],"asset":{"type":"passage","lines":["나라별 획득한 금메달 수","대한민국 13개 · 독일 12개 · 네덜란드 15개","스웨덴 4개 · 일본 20개 · 캐나다 9개"]},"variant_rule":{"alt":[{"stem":"획득한 금메달 수가 10개 이하인 나라를 모두 고른 것은 어느 것인가요?","options":[{"t":"스웨덴, 캐나다","correct":true},{"t":"스웨덴","mis":"M5-2-u1-X16"},{"t":"대한민국, 독일, 네덜란드, 일본","mis":"M5-2-u1-X03"},{"t":"스웨덴, 독일, 캐나다","mis":"M5-2-u1-X16"}],"explanation":["10개 이하는 10개와 같거나 적은 수예요.","스웨덴 4개, 캐나다 9개가 10개보다 적어요.","독일 12개는 10개보다 많아 빠져요 — 스웨덴, 캐나다예요."],"asset":{"type":"passage","lines":["나라별 획득한 금메달 수","대한민국 13개 · 독일 12개 · 네덜란드 15개","스웨덴 4개 · 일본 20개 · 캐나다 9개"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#1','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',2,'sa','auto','34보다 크고 40보다 작은 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":2,"kind":"sa","stem":"34보다 크고 40보다 작은 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["34보다 큰 수에는 34가, 40보다 작은 수에는 40이 들어가지 않아요.","35, 36, 37, 38, 39를 세어요.","모두 5개예요."],"variant_rule":{"alt":[{"stem":"38보다 크고 42보다 작은 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["38보다 큰 수에는 38이, 42보다 작은 수에는 42가 들어가지 않아요.","39, 40, 41을 세어요.","모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#2','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',2,'mc','auto','33, 21, 19.8, 25, 25.4, 8.52, ⟨29 1/2⟩ 중에서 25 이상인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"33, 21, 19.8, 25, 25.4, 8.52, ⟨29 1/2⟩ 중에서 25 이상인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"33, 25, 25.4, ⟨29 1/2⟩","correct":true},{"t":"33, 25.4, ⟨29 1/2⟩","mis":"M5-2-u1-X01"},{"t":"21, 19.8, 25, 8.52","mis":"M5-2-u1-X03"},{"t":"33, 25, 25.4","mis":"M5-2-u1-X16"}],"explanation":["25 이상인 수는 25와 같거나 큰 수예요.","경곗값을 살펴보면 25는 들어가요.","그래서 33, 25, 25.4, ⟨29 1/2⟩이에요."],"variant_rule":{"alt":[{"stem":"45, 35, 30, 25, 50 중에서 35 이상인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"45, 35, 50","correct":true},{"t":"45, 50","mis":"M5-2-u1-X01"},{"t":"35, 30, 25","mis":"M5-2-u1-X03"},{"t":"45, 35","mis":"M5-2-u1-X16"}],"explanation":["35 이상인 수는 35와 같거나 큰 수예요.","경곗값을 살펴보면 35는 들어가요.","그래서 45, 35, 50이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#3','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'mc','auto','2 이상인 수는 모두 몇 개인가요?',ARRAY['M5-2-u1-X19','M5-2-u1-X01']::text[],true,'{"seq":3,"concept":"M5-2-u1-C1","difficulty":3,"kind":"mc","stem":"2 이상인 수는 모두 몇 개인가요?","options":[{"t":"셀 수 없이 많다","correct":true},{"t":"4개 — 2, 3, 4, 5","mis":"M5-2-u1-X19"},{"t":"3개 — 3, 4, 5","mis":"M5-2-u1-X01"},{"t":"2.1, 2.5, ⟨3 1/2⟩ 세 개","mis":"M5-2-u1-X19"}],"explanation":["2 이상인 수에는 2, 3, 4, 5 같은 자연수뿐 아니라 2.1, 2.5, ⟨3 1/2⟩도 들어가요.","2와 같거나 큰 수는 끝없이 이어져요.","그래서 셀 수 없이 많아요 — 수직선의 선으로 한 번에 나타내요."],"variant_rule":{"alt":[{"stem":"3 이하인 수는 모두 몇 개인가요?","options":[{"t":"셀 수 없이 많다","correct":true},{"t":"3개 — 1, 2, 3","mis":"M5-2-u1-X19"},{"t":"2개 — 1, 2","mis":"M5-2-u1-X01"},{"t":"1.5, 2.1, ⟨2 1/2⟩ 세 개","mis":"M5-2-u1-X19"}],"explanation":["3 이하인 수에는 1, 2, 3 같은 자연수뿐 아니라 1.5, 2.1, ⟨2 1/2⟩도 들어가요.","3과 같거나 작은 수는 끝없이 많아요.","그래서 셀 수 없이 많아요 — 수직선의 선으로 한 번에 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#4','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'error','auto','「2 이상인 수」를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X17']::text[],true,'{"seq":4,"concept":"M5-2-u1-C1","difficulty":3,"kind":"error","stem":"「2 이상인 수」를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「2 이상인 수는 2보다 큰 수예요.」","correct":true,"mis_target":"M5-2-u1-X01"},{"t":"「2.1도 2 이상인 수예요.」","mis":"M5-2-u1-X17"},{"t":"「2 이상인 수는 수직선에 2를 ●으로 나타내요.」","mis":"M5-2-u1-X17"}],"explanation":["2 이상인 수는 2와 같거나 큰 수예요.","「2보다 큰 수」라고 하면 2가 빠져 버려요.","2.1도 들어가고, 2를 포함하니 ●으로 나타내요."],"variant_rule":{"alt":[{"stem":"「3 이하인 수」를 두고 친구들이 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「3 이하인 수는 3보다 작은 수예요.」","correct":true,"mis_target":"M5-2-u1-X01"},{"t":"「⟨2 1/2⟩도 3 이하인 수예요.」","mis":"M5-2-u1-X17"},{"t":"「3 이하인 수는 수직선에 3을 ●으로 나타내요.」","mis":"M5-2-u1-X17"}],"explanation":["3 이하인 수는 3과 같거나 작은 수예요.","「3보다 작은 수」라고 하면 3이 빠져 버려요.","⟨2 1/2⟩도 들어가고, 3을 포함하니 ●으로 나타내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#5','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'mc','auto','기록이 167 cm 이상인 학생과 122 cm 이하인 학생을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X16','M5-2-u1-X03']::text[],false,'{"seq":5,"concept":"M5-2-u1-C1","difficulty":3,"kind":"mc","stem":"기록이 167 cm 이상인 학생과 122 cm 이하인 학생을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"세진 / 상현, 보겸, 재인","correct":true},{"t":"세진 / 상현, 보겸","mis":"M5-2-u1-X01"},{"t":"지호, 세진 / 상현, 보겸, 재인","mis":"M5-2-u1-X16"},{"t":"지호, 상현, 보겸, 재인 / 세진","mis":"M5-2-u1-X03"}],"explanation":["167 cm 이상은 167 cm와 같거나 긴 기록, 122 cm 이하는 122 cm와 같거나 짧은 기록이에요.","세진 175 cm만 167 cm보다 길고, 지호 141 cm는 짧아요.","재인은 딱 122 cm라 122 cm 이하에 들어가요 — 세진 / 상현, 보겸, 재인."],"asset":{"type":"passage","lines":["지호네 모둠 학생들의 제자리멀리뛰기 기록","지호 141 cm · 상현 105.6 cm · 보겸 99.4 cm","재인 122 cm · 세진 175 cm"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#6','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'mc','auto','84, 55, 49, 60, 63, 72, 52, 77 중에서 77 이상인 수와 52 이하인 수를 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":6,"concept":"M5-2-u1-C1","difficulty":3,"kind":"mc","stem":"84, 55, 49, 60, 63, 72, 52, 77 중에서 77 이상인 수와 52 이하인 수를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"84, 77 / 49, 52","correct":true},{"t":"84 / 49","mis":"M5-2-u1-X01"},{"t":"55, 49, 60, 63, 72, 52 / 84, 55, 60, 63, 72, 77","mis":"M5-2-u1-X03"},{"t":"84, 77 / 49, 52, 55","mis":"M5-2-u1-X16"}],"explanation":["77 이상은 77과 같거나 큰 수, 52 이하는 52와 같거나 작은 수예요.","77과 52는 경곗값이라 각각 들어가요.","그래서 84, 77 / 49, 52예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#7','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',3,'ox','auto','「수리 마을 친구들」은 12세 이상 관람 가예요. 12세 미만인 친구는 보호자를 동반해야 해요.',ARRAY['M5-2-u1-X02']::text[],false,'{"seq":7,"concept":"M5-2-u1-C1","difficulty":3,"kind":"ox","stem":"「수리 마을 친구들」은 12세 이상 관람 가예요. 12세 미만인 친구는 보호자를 동반해야 해요.","answer":"O","reason_options":[{"t":"12세 미만은 12세보다 어린 나이라 「12세 이상」에 들지 않아서","correct":true},{"t":"12세 미만에도 12세가 들어가서","mis":"M5-2-u1-X02"}],"mis":"M5-2-u1-X02","explanation":["12세 이상에는 12세가 들어가요.","12세 미만은 12세보다 어린 나이 — 12세는 들어가지 않아요.","그래서 12세보다 어린 친구는 보호자와 함께 봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#8','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',4,'essay','teacher','「2 이상인 수」를 수직선에 나타내는 방법을 쓰고, 2에 ●을 그리는 까닭을 이상의 뜻으로 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C1","difficulty":4,"kind":"essay","stem":"「2 이상인 수」를 수직선에 나타내는 방법을 쓰고, 2에 ●을 그리는 까닭을 이상의 뜻으로 설명하세요.","answer_guide":{"answer":"예: 2에 ●을 그리고 오른쪽으로 선을 긋는다. 이상은 「같거나 큰 수」라서 2와 2를 포함하므로 ●으로 나타낸다.","scoring_points":["2에 ●을 그림을 썼는가","오른쪽으로 선을 그음을 썼는가","「같거나 큰 수」라서 2를 포함한다는 까닭을 썼는가"]},"explanation":["2 이상인 수는 2와 같거나 큰 수예요.","2를 포함하니 ●, 큰 쪽이니 오른쪽으로 선을 그어요.","이하였다면 ●을 그리고 왼쪽으로 그어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#9','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',4,'essay','teacher','영화관 안내에 「12세 이상 관람 가」가 있고, 친구들은 「12세 미만은 보호자를 동반해야 한대!」라고 말했어요. 딱 12세인 친구는 어느 쪽에 드는지 쓰고, 그 까닭을 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C1","difficulty":4,"kind":"essay","stem":"영화관 안내에 「12세 이상 관람 가」가 있고, 친구들은 「12세 미만은 보호자를 동반해야 한대!」라고 말했어요. 딱 12세인 친구는 어느 쪽에 드는지 쓰고, 그 까닭을 설명하세요.","answer_guide":{"answer":"예: 딱 12세는 「12세 이상」에 들어 보호자 없이 볼 수 있다. 12세 이상은 12세와 같거나 많은 나이라 12세를 포함하고, 12세 미만은 12세보다 어린 나이라 12세를 포함하지 않기 때문이다.","scoring_points":["12세가 「12세 이상」에 든다고 썼는가","이상은 경곗값 12세를 포함함을 밝혔는가","미만은 경곗값 12세를 포함하지 않음을 밝혔는가"]},"explanation":["12세 이상에는 12세가 들어가요.","12세 미만에는 12세가 들어가지 않아요.","그래서 딱 12세는 보호자 없이 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L02_challenge#10','math',5,2,'u1','L02','tb_g5_2_math_u1_L02_challenge','lesson_challenge','M5-2-u1-C1',4,'mc','auto','34보다 크고 40보다 작은 자연수를 「이상」과 「이하」를 써서 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X05']::text[],false,'{"seq":10,"concept":"M5-2-u1-C1","difficulty":4,"kind":"mc","stem":"34보다 크고 40보다 작은 자연수를 「이상」과 「이하」를 써서 나타낸 것은 어느 것인가요?","options":[{"t":"35 이상 39 이하인 자연수","correct":true},{"t":"34 이상 40 이하인 자연수","mis":"M5-2-u1-X02"},{"t":"35 이상 40 이하인 자연수","mis":"M5-2-u1-X05"},{"t":"34 이상 39 이하인 자연수","mis":"M5-2-u1-X05"}],"explanation":["34보다 크고 40보다 작은 자연수는 35, 36, 37, 38, 39예요.","가장 작은 수 35와 가장 큰 수 39를 넣어야 하니 「이상」「이하」의 경곗값은 35와 39예요.","그래서 35 이상 39 이하인 자연수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#1','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'mc','auto','무게가 10 kg을 초과하는 가방은 비행기에 가지고 탈 수 없어요. 가방의 무게가 8.9 kg, 10.5 kg, 13 kg, 9.5 kg, 12 kg, 10 kg일 때, 가지고 탈 수 없는 가방의 무게를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":1,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"무게가 10 kg을 초과하는 가방은 비행기에 가지고 탈 수 없어요. 가방의 무게가 8.9 kg, 10.5 kg, 13 kg, 9.5 kg, 12 kg, 10 kg일 때, 가지고 탈 수 없는 가방의 무게를 모두 고른 것은 어느 것인가요?","options":[{"t":"10.5 kg, 13 kg, 12 kg","correct":true},{"t":"10.5 kg, 13 kg, 12 kg, 10 kg","mis":"M5-2-u1-X02"},{"t":"8.9 kg, 9.5 kg","mis":"M5-2-u1-X03"},{"t":"10.5 kg, 13 kg","mis":"M5-2-u1-X16"}],"explanation":["10 초과인 수는 10보다 큰 수예요.","경곗값을 살펴보면 10은 들어가지 않아요.","그래서 10.5 kg, 13 kg, 12 kg이에요."],"variant_rule":{"alt":[{"stem":"반려동물과 가방을 함께 잰 무게가 8 kg 미만이면 비행기에 데리고 탈 수 있어요. 무게가 8 kg, 6.4 kg, 8.5 kg, 9 kg, 7.9 kg일 때, 데리고 탈 수 있는 무게를 모두 고른 것은 어느 것인가요?","options":[{"t":"6.4 kg, 7.9 kg","correct":true},{"t":"8 kg, 6.4 kg, 7.9 kg","mis":"M5-2-u1-X02"},{"t":"8.5 kg, 9 kg","mis":"M5-2-u1-X03"},{"t":"6.4 kg","mis":"M5-2-u1-X16"}],"explanation":["8 미만인 수는 8보다 작은 수예요.","경곗값을 살펴보면 8은 들어가지 않아요.","그래서 6.4 kg, 7.9 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#2','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'mc','auto','10보다 큰 수를 무엇이라고 하나요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03']::text[],true,'{"seq":2,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"10보다 큰 수를 무엇이라고 하나요?","options":[{"t":"10 초과인 수","correct":true},{"t":"10 이상인 수","mis":"M5-2-u1-X02"},{"t":"10 미만인 수","mis":"M5-2-u1-X03"},{"t":"10 이하인 수","mis":"M5-2-u1-X03"}],"explanation":["「보다 큰 수」는 초과예요.","10 초과인 수에는 10이 들어가지 않아요.","수직선에는 10에 ○을 그리고 오른쪽으로 선을 그어요."],"variant_rule":{"alt":[{"stem":"8보다 작은 수를 무엇이라고 하나요?","options":[{"t":"8 미만인 수","correct":true},{"t":"8 이하인 수","mis":"M5-2-u1-X02"},{"t":"8 초과인 수","mis":"M5-2-u1-X03"},{"t":"8 이상인 수","mis":"M5-2-u1-X03"}],"explanation":["「보다 작은 수」는 미만이에요.","8 미만인 수에는 8이 들어가지 않아요.","수직선에는 8에 ○을 그리고 왼쪽으로 선을 그어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#3','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'mc','auto','수직선에 34에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],true,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"수직선에 34에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"34 초과인 수","correct":true},{"t":"34 이상인 수","mis":"M5-2-u1-X04"},{"t":"34 미만인 수","mis":"M5-2-u1-X03"},{"t":"34 이하인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","34는 ○이라 들어가지 않아요.","그래서 34 초과인 수예요."],"variant_rule":{"alt":[{"stem":"수직선에 46에 ○이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"46 미만인 수","correct":true},{"t":"46 이하인 수","mis":"M5-2-u1-X04"},{"t":"46 초과인 수","mis":"M5-2-u1-X03"},{"t":"46 이상인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","46은 ○이라 들어가지 않아요.","그래서 46 미만인 수예요."]},{"stem":"수직선에 29에 ○이 그려져 있고 거기서 오른쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"29 초과인 수","correct":true},{"t":"29 이상인 수","mis":"M5-2-u1-X04"},{"t":"29 미만인 수","mis":"M5-2-u1-X03"},{"t":"29 이하인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","29는 ○이라 들어가지 않아요.","그래서 29 초과인 수예요."]},{"stem":"수직선에 42에 ○이 그려져 있고 거기서 왼쪽으로 선이 그어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"42 미만인 수","correct":true},{"t":"42 이하인 수","mis":"M5-2-u1-X04"},{"t":"42 초과인 수","mis":"M5-2-u1-X03"},{"t":"42 이상인 수","mis":"M5-2-u1-X03"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","42는 ○이라 들어가지 않아요.","그래서 42 미만인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#4','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',1,'ox','auto','10 초과인 수에는 10이 들어가요.',ARRAY['M5-2-u1-X02']::text[],true,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":1,"kind":"ox","stem":"10 초과인 수에는 10이 들어가요.","answer":"X","reason_options":[{"t":"초과는 「보다 큰 수」라서 10이 들어가지 않아서","correct":true},{"t":"초과도 이상처럼 10을 포함해서","mis":"M5-2-u1-X02"}],"mis":"M5-2-u1-X02","explanation":["초과의 뜻에는 「같거나」가 없어요.","그래서 10 초과인 수에는 10이 들어가지 않아요.","수직선에도 10에 ○을 그려요."],"variant_rule":{"alt":[{"stem":"8 미만인 수에는 8이 들어가지 않아요.","answer":"O","reason_options":[{"t":"미만은 「보다 작은 수」라서 8이 들어가지 않아서","correct":true},{"t":"미만도 이하처럼 8을 포함해서","mis":"M5-2-u1-X02"}],"explanation":["미만의 뜻에는 「같거나」가 없어요.","그래서 8 미만인 수에는 8이 들어가지 않아요.","수직선에도 8에 ○을 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#5','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'mc','auto','42, 40, 39.5, 7, 32, 15.8, 31.9, 45.8 중에서 40 초과인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":2,"kind":"mc","stem":"42, 40, 39.5, 7, 32, 15.8, 31.9, 45.8 중에서 40 초과인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"42, 45.8","correct":true},{"t":"42, 40, 45.8","mis":"M5-2-u1-X02"},{"t":"39.5, 7, 32, 15.8, 31.9","mis":"M5-2-u1-X03"},{"t":"42","mis":"M5-2-u1-X16"}],"explanation":["40 초과인 수는 40보다 큰 수예요.","경곗값을 살펴보면 40은 들어가지 않아요.","그래서 42, 45.8이에요."],"variant_rule":{"alt":[{"stem":"42, 40, 39.5, 7, 32, 15.8, 31.9, 45.8 중에서 32 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"7, 15.8, 31.9","correct":true},{"t":"7, 32, 15.8, 31.9","mis":"M5-2-u1-X02"},{"t":"42, 40, 39.5, 45.8","mis":"M5-2-u1-X03"},{"t":"7, 15.8","mis":"M5-2-u1-X16"}],"explanation":["32 미만인 수는 32보다 작은 수예요.","경곗값을 살펴보면 32는 들어가지 않아요.","그래서 7, 15.8, 31.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#6','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'mc','auto','높이가 4.4 m를 초과하는 자동차는 지나갈 수 없는 해저 터널이 있어요. 이 터널을 지나갈 수 없는 자동차를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":6,"concept":"M5-2-u1-C2","difficulty":2,"kind":"mc","stem":"높이가 4.4 m를 초과하는 자동차는 지나갈 수 없는 해저 터널이 있어요. 이 터널을 지나갈 수 없는 자동차를 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다","correct":true},{"t":"나, 다, 라","mis":"M5-2-u1-X02"},{"t":"가, 라","mis":"M5-2-u1-X03"},{"t":"나","mis":"M5-2-u1-X16"}],"explanation":["4.4 m 초과는 4.4 m보다 높은 것이에요.","나 5.1 m, 다 4.9 m가 4.4 m보다 높아요.","라는 딱 4.4 m라 들어가지 않아요 — 나, 다예요."],"asset":{"type":"passage","lines":["자동차의 높이","가 4 m · 나 5.1 m · 다 4.9 m · 라 4.4 m"]},"variant_rule":{"alt":[{"stem":"높이가 3.5 m 미만인 자동차만 지나갈 수 있는 터널이 있어요. 이 터널을 지나갈 수 있는 자동차를 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가, 다, 라","mis":"M5-2-u1-X02"},{"t":"나, 다","mis":"M5-2-u1-X03"},{"t":"라","mis":"M5-2-u1-X16"}],"explanation":["3.5 m 미만은 3.5 m보다 낮은 것이에요.","가 3.45 m, 라 3.2 m가 3.5 m보다 낮아요.","다는 딱 3.5 m라 들어가지 않아요 — 가, 라예요."],"asset":{"type":"passage","lines":["자동차의 높이","가 3.45 m · 나 3.8 m · 다 3.5 m · 라 3.2 m"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#7','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'mc','auto','12.7, 15.1, ⟨12 7/8⟩, 15, 30, 14.78, 19 중에서 15 초과인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C2","difficulty":2,"kind":"mc","stem":"12.7, 15.1, ⟨12 7/8⟩, 15, 30, 14.78, 19 중에서 15 초과인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"15.1, 30, 19","correct":true},{"t":"15.1, 15, 30, 19","mis":"M5-2-u1-X02"},{"t":"12.7, ⟨12 7/8⟩, 14.78","mis":"M5-2-u1-X03"},{"t":"15.1, 30","mis":"M5-2-u1-X16"}],"explanation":["15 초과인 수는 15보다 큰 수예요.","경곗값을 살펴보면 15는 들어가지 않아요.","그래서 15.1, 30, 19예요."],"variant_rule":{"alt":[{"stem":"49, 61, 56, 38, 52 중에서 52 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"49, 38","correct":true},{"t":"49, 38, 52","mis":"M5-2-u1-X02"},{"t":"61, 56","mis":"M5-2-u1-X03"},{"t":"49","mis":"M5-2-u1-X16"}],"explanation":["52 미만인 수는 52보다 작은 수예요.","경곗값을 살펴보면 52는 들어가지 않아요.","그래서 49, 38이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#8','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'match','auto','수의 범위와 그 뜻을 바르게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C2","difficulty":2,"kind":"match","stem":"수의 범위와 그 뜻을 바르게 이으세요.","pairs":[{"l":"10 초과인 수","r":"10보다 큰 수"},{"l":"10 이상인 수","r":"10과 같거나 큰 수"},{"l":"8 미만인 수","r":"8보다 작은 수"},{"l":"8 이하인 수","r":"8과 같거나 작은 수"}],"mis":"M5-2-u1-X02","explanation":["이상·이하에는 「같거나」가 들어가요.","초과는 「보다 큰」, 미만은 「보다 작은」이에요.","경곗값 10·8이 들어가는지가 둘을 가르는 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#9','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',2,'mc','auto','딸기의 무게가 30 g 초과인 것은 파란색 바구니에 담아요. 21 g, 32 g, 29.9 g, 30.9 g, 17 g인 딸기 중에서 파란색 바구니에 담을 딸기를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":9,"concept":"M5-2-u1-C2","difficulty":2,"kind":"mc","stem":"딸기의 무게가 30 g 초과인 것은 파란색 바구니에 담아요. 21 g, 32 g, 29.9 g, 30.9 g, 17 g인 딸기 중에서 파란색 바구니에 담을 딸기를 모두 고른 것은 어느 것인가요?","options":[{"t":"32 g, 30.9 g","correct":true},{"t":"21 g, 29.9 g, 17 g","mis":"M5-2-u1-X03"},{"t":"32 g","mis":"M5-2-u1-X16"},{"t":"32 g, 30.9 g, 29.9 g","mis":"M5-2-u1-X16"}],"explanation":["30 g 초과는 30 g보다 무거운 것이에요.","32 g과 30.9 g이 30 g보다 무거워요.","29.9 g은 30 g보다 가벼워서 빠져요 — 32 g, 30.9 g이에요."],"variant_rule":{"alt":[{"stem":"딸기의 무게가 30 g 미만인 것은 초록색 바구니에 담아요. 21 g, 32 g, 29.9 g, 30.9 g, 17 g인 딸기 중에서 초록색 바구니에 담을 딸기를 모두 고른 것은 어느 것인가요?","options":[{"t":"21 g, 29.9 g, 17 g","correct":true},{"t":"32 g, 30.9 g","mis":"M5-2-u1-X03"},{"t":"21 g, 17 g","mis":"M5-2-u1-X16"},{"t":"21 g, 29.9 g, 30.9 g, 17 g","mis":"M5-2-u1-X16"}],"explanation":["30 g 미만은 30 g보다 가벼운 것이에요.","21 g, 29.9 g, 17 g이 30 g보다 가벼워요.","30.9 g은 30 g보다 무거워서 빠져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_basic#10','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_basic','lesson_basic','M5-2-u1-C2',3,'mc','auto','10 초과인 수와 10 이상인 수는 어떤 점이 다른가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X02','M5-2-u1-X19']::text[],true,'{"seq":10,"concept":"M5-2-u1-C2","difficulty":3,"kind":"mc","stem":"10 초과인 수와 10 이상인 수는 어떤 점이 다른가요?","options":[{"t":"10 초과인 수는 10을 포함하지 않고, 10 이상인 수는 10을 포함한다","correct":true},{"t":"10 초과인 수는 10을 포함하고, 10 이상인 수는 10을 포함하지 않는다","mis":"M5-2-u1-X01"},{"t":"다른 점이 없다","mis":"M5-2-u1-X02"},{"t":"10 초과인 수는 11, 12, 13뿐이다","mis":"M5-2-u1-X19"}],"explanation":["10 초과는 10보다 큰 수, 10 이상은 10과 같거나 큰 수예요.","경곗값 10을 넣느냐 빼느냐가 달라요.","10 초과인 수에는 10.5, 12.9, ⟨12 1/10⟩도 있어 셀 수 없이 많아요."],"variant_rule":{"alt":[{"stem":"8 미만인 수와 8 이하인 수는 어떤 점이 다른가요?","options":[{"t":"8 미만인 수는 8을 포함하지 않고, 8 이하인 수는 8을 포함한다","correct":true},{"t":"8 미만인 수는 8을 포함하고, 8 이하인 수는 8을 포함하지 않는다","mis":"M5-2-u1-X01"},{"t":"다른 점이 없다","mis":"M5-2-u1-X02"},{"t":"8 미만인 수는 5, 6, 7뿐이다","mis":"M5-2-u1-X19"}],"explanation":["8 미만은 8보다 작은 수, 8 이하는 8과 같거나 작은 수예요.","경곗값 8을 넣느냐 빼느냐가 달라요.","8 미만인 수에는 6.1, 7.5, ⟨7 1/10⟩도 있어 셀 수 없이 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#1','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C1',2,'mc','auto','1부터 9까지의 자연수 중에서 6 이상인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"1부터 9까지의 자연수 중에서 6 이상인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"6, 7, 8, 9","correct":true},{"t":"7, 8, 9","mis":"M5-2-u1-X01"},{"t":"1, 2, 3, 4, 5, 6","mis":"M5-2-u1-X03"},{"t":"6, 7, 8","mis":"M5-2-u1-X16"}],"explanation":["6 이상은 6과 같거나 큰 수예요.","6이 들어가고 9까지 이어져요.","그래서 6, 7, 8, 9예요."],"variant_rule":{"alt":[{"stem":"4 미만인 자연수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 2, 3","correct":true},{"t":"1, 2, 3, 4","mis":"M5-2-u1-X02"},{"t":"5, 6, 7","mis":"M5-2-u1-X03"},{"t":"2, 3","mis":"M5-2-u1-X16"}],"explanation":["4 미만은 4보다 작은 수예요.","4는 들어가지 않아요.","그래서 4 미만인 자연수는 1, 2, 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#2','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',2,'sa','auto','10 초과인 자연수 중에서 가장 작은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u1-C2","difficulty":2,"kind":"sa","stem":"10 초과인 자연수 중에서 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["10 초과인 수에는 10이 들어가지 않아요.","10보다 큰 자연수는 11, 12, 13, …이에요.","가장 작은 수는 11이에요."],"variant_rule":{"alt":[{"stem":"8 미만인 자연수 중에서 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["8 미만인 수에는 8이 들어가지 않아요.","8보다 작은 자연수는 …, 5, 6, 7이에요.","가장 큰 수는 7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#3','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'error','auto','두 친구의 말을 읽고 잘못 말한 것을 고르세요.',ARRAY['M5-2-u1-X02','M5-2-u1-X17']::text[],true,'{"seq":3,"concept":"M5-2-u1-C2","difficulty":3,"kind":"error","stem":"두 친구의 말을 읽고 잘못 말한 것을 고르세요.","options":[{"t":"선재 — 「64세 미만에는 64세도 포함돼요.」","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"연서 — 「11세, 12세, 13세 중에서 12세 초과인 나이는 13세뿐이에요.」","mis":"M5-2-u1-X17"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u1-X02"}],"explanation":["64 미만인 수는 64보다 작은 수예요.","그래서 64세 미만에는 64세가 포함되지 않아요.","12 초과인 수는 12보다 큰 수라 12세는 빠지고 13세뿐 — 연서는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"선재","text":"64세 미만에는 64세도 포함돼요."},{"who":"연서","text":"11세, 12세, 13세 중에서 12세 초과인 나이는 13세뿐이에요."}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 두 친구의 말을 읽고 잘못 말한 것을 고르세요.","options":[{"t":"현아 — 「52 초과인 수에는 52가 포함돼요.」","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"민규 — 「35 이하인 수에는 35가 포함돼요.」","mis":"M5-2-u1-X17"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u1-X02"}],"explanation":["52 초과인 수는 52보다 큰 수예요.","그래서 52 초과인 수에는 52가 포함되지 않아요.","35 이하는 35와 같거나 작은 수라 35가 포함돼요 — 민규는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"민규","text":"35 이하인 수에는 35가 포함돼요."},{"who":"현아","text":"52 초과인 수에는 52가 포함돼요."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#4','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'essay','teacher','잘못 말한 친구를 찾고, 그 친구의 문장을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M5-2-u1-C2","difficulty":3,"kind":"essay","stem":"잘못 말한 친구를 찾고, 그 친구의 문장을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 선재 — 64세 미만에는 64세가 포함되지 않습니다.","scoring_points":["잘못 말한 친구 선재를 찾았는가","「64세 미만에는 64세가 포함되지 않는다」로 고쳤는가","미만은 경곗값을 포함하지 않음을 알고 썼는가"]},"explanation":["64 미만인 수는 64보다 작은 수예요.","경곗값 64세는 들어가지 않아요.","이름과 바른 문장이 모두 맞아야 해요."],"asset":{"type":"speech","turns":[{"who":"선재","text":"64세 미만에는 64세도 포함돼요."},{"who":"연서","text":"11세, 12세, 13세 중에서 12세 초과인 나이는 13세뿐이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#5','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'sa','auto','무게가 10 kg을 초과하는 가방은 비행기에 가지고 탈 수 없어요. 8.9 kg, 10.5 kg, 13 kg, 9.5 kg, 12 kg, 10 kg인 가방 중에서 가지고 탈 수 없는 가방은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u1-C2","difficulty":3,"kind":"sa","stem":"무게가 10 kg을 초과하는 가방은 비행기에 가지고 탈 수 없어요. 8.9 kg, 10.5 kg, 13 kg, 9.5 kg, 12 kg, 10 kg인 가방 중에서 가지고 탈 수 없는 가방은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["10 kg 초과는 10 kg보다 무거운 것이에요.","10.5 kg, 13 kg, 12 kg이 10 kg보다 무거워요.","딱 10 kg인 가방은 가지고 탈 수 있으니 3개예요."],"variant_rule":{"alt":[{"stem":"반려동물과 가방을 함께 잰 무게가 8 kg 미만이면 데리고 탈 수 있어요. 8 kg, 6.4 kg, 8.5 kg, 9 kg, 7.9 kg 중에서 데리고 탈 수 있는 것은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["8 kg 미만은 8 kg보다 가벼운 것이에요.","6.4 kg, 7.9 kg이 8 kg보다 가벼워요.","딱 8 kg은 들어가지 않으니 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#6','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'mc','auto','무게가 10 kg을 초과하는 가방은 비행기에 가지고 탈 수 없어요. 무게가 딱 10 kg인 가방은 어떻게 될까요?',ARRAY['M5-2-u1-X02','M5-2-u1-X17']::text[],true,'{"seq":6,"concept":"M5-2-u1-C2","difficulty":3,"kind":"mc","stem":"무게가 10 kg을 초과하는 가방은 비행기에 가지고 탈 수 없어요. 무게가 딱 10 kg인 가방은 어떻게 될까요?","options":[{"t":"가지고 탈 수 있다","correct":true},{"t":"가지고 탈 수 없다","mis":"M5-2-u1-X02"},{"t":"10 kg보다 가벼워야만 탈 수 있다","mis":"M5-2-u1-X02"},{"t":"알 수 없다","mis":"M5-2-u1-X17"}],"explanation":["10 kg 초과는 10 kg보다 무거운 무게예요.","딱 10 kg은 10 kg 초과에 들어가지 않아요.","그래서 10 kg인 가방은 가지고 탈 수 있어요."],"variant_rule":{"alt":[{"stem":"반려동물과 가방을 함께 잰 무게가 8 kg 미만이면 데리고 탈 수 있어요. 함께 잰 무게가 딱 8 kg이면 어떻게 될까요?","options":[{"t":"데리고 탈 수 없다","correct":true},{"t":"데리고 탈 수 있다","mis":"M5-2-u1-X02"},{"t":"8 kg보다 무거워야 탈 수 있다","mis":"M5-2-u1-X03"},{"t":"알 수 없다","mis":"M5-2-u1-X17"}],"explanation":["8 kg 미만은 8 kg보다 가벼운 무게예요.","딱 8 kg은 8 kg 미만에 들어가지 않아요.","그래서 데리고 탈 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#7','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',3,'ox','auto','40 초과인 수에 40은 들어가지 않지만 39.5는 들어가요.',ARRAY['M5-2-u1-X03']::text[],true,'{"seq":7,"concept":"M5-2-u1-C2","difficulty":3,"kind":"ox","stem":"40 초과인 수에 40은 들어가지 않지만 39.5는 들어가요.","answer":"X","reason_options":[{"t":"39.5는 40보다 작아서 40 초과인 수가 아니라서","correct":true},{"t":"40에 가까운 수는 모두 들어가서","mis":"M5-2-u1-X03"}],"mis":"M5-2-u1-X03","explanation":["40 초과인 수는 40보다 큰 수예요.","39.5는 40보다 작아요.","그래서 39.5는 40 초과인 수가 아니에요."],"variant_rule":{"alt":[{"stem":"32 미만인 수에 31.9는 들어가요.","answer":"O","reason_options":[{"t":"31.9는 32보다 작아서","correct":true},{"t":"32에 가까운 수는 빠져서","mis":"M5-2-u1-X03"}],"explanation":["32 미만인 수는 32보다 작은 수예요.","31.9는 32보다 0.1 작아요.","그래서 31.9는 32 미만인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#8','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',4,'essay','teacher','「제 용돈 중에서 간식을 사 먹는 데 쓸 수 있는 돈은 25000원 미만입니다.」에서 딱 25000원을 간식에 쓸 수 있는지 쓰고, 그 까닭을 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C2","difficulty":4,"kind":"essay","stem":"「제 용돈 중에서 간식을 사 먹는 데 쓸 수 있는 돈은 25000원 미만입니다.」에서 딱 25000원을 간식에 쓸 수 있는지 쓰고, 그 까닭을 설명하세요.","answer_guide":{"answer":"예: 쓸 수 없다. 25000원 미만은 25000원보다 적은 돈이라 25000원은 들어가지 않기 때문이다.","scoring_points":["쓸 수 없다고 답했는가","미만은 「보다 작은(적은)」 뜻임을 썼는가","경곗값 25000원이 들어가지 않음을 밝혔는가"]},"explanation":["25000원 미만은 25000원보다 적은 돈이에요.","경곗값 25000원은 들어가지 않아요.","그래서 딱 25000원은 쓸 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#9','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',4,'mc','auto','높이가 4.4 m를 초과하는 자동차는 지나갈 수 없는 해저 터널이 있어요. 이 터널을 지나갈 수 있는 자동차의 높이 범위는 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X17']::text[],true,'{"seq":9,"concept":"M5-2-u1-C2","difficulty":4,"kind":"mc","stem":"높이가 4.4 m를 초과하는 자동차는 지나갈 수 없는 해저 터널이 있어요. 이 터널을 지나갈 수 있는 자동차의 높이 범위는 어느 것인가요?","options":[{"t":"4.4 m 이하","correct":true},{"t":"4.4 m 미만","mis":"M5-2-u1-X01"},{"t":"4.4 m 이상","mis":"M5-2-u1-X03"},{"t":"4.4 m 초과","mis":"M5-2-u1-X17"}],"explanation":["4.4 m를 초과하면 지나갈 수 없어요.","딱 4.4 m는 초과가 아니라 지나갈 수 있어요.","그래서 지나갈 수 있는 높이는 4.4 m와 같거나 낮은 4.4 m 이하예요."],"variant_rule":{"alt":[{"stem":"높이가 3.5 m 미만인 자동차만 지나갈 수 있는 터널이 있어요. 이 터널을 지나갈 수 없는 자동차의 높이 범위는 어느 것인가요?","options":[{"t":"3.5 m 이상","correct":true},{"t":"3.5 m 초과","mis":"M5-2-u1-X01"},{"t":"3.5 m 이하","mis":"M5-2-u1-X03"},{"t":"3.5 m 미만","mis":"M5-2-u1-X17"}],"explanation":["3.5 m보다 낮아야 지나갈 수 있어요.","딱 3.5 m는 미만이 아니라 지나갈 수 없어요.","그래서 지나갈 수 없는 높이는 3.5 m와 같거나 높은 3.5 m 이상이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L03_challenge#10','math',5,2,'u1','L03','tb_g5_2_math_u1_L03_challenge','lesson_challenge','M5-2-u1-C2',4,'essay','teacher','「8 미만인 수」와 「8 이하인 수」를 수직선에 나타내는 방법을 각각 쓰고, 두 범위의 같은 점과 다른 점을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C2","difficulty":4,"kind":"essay","stem":"「8 미만인 수」와 「8 이하인 수」를 수직선에 나타내는 방법을 각각 쓰고, 두 범위의 같은 점과 다른 점을 설명하세요.","answer_guide":{"answer":"예: 8 미만은 8에 ○, 8 이하는 8에 ●을 그리고 둘 다 왼쪽으로 선을 긋는다. 둘 다 8보다 작은 수를 포함하는 점은 같고, 8 미만은 8을 포함하지 않고 8 이하는 8을 포함하는 점이 다르다.","scoring_points":["8 미만은 ○, 8 이하는 ●임을 썼는가","둘 다 왼쪽으로 선을 그음을 썼는가","경곗값 8의 포함 여부가 다르다고 설명했는가"]},"explanation":["8 미만은 8보다 작은 수, 8 이하는 8과 같거나 작은 수예요.","둘 다 왼쪽으로 선을 긋고, 8에 ○과 ●이 달라요.","다른 점은 경곗값 8을 포함하느냐예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#1','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'mc','auto','수직선에 5에는 ●, 10에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],true,'{"seq":1,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"수직선에 5에는 ●, 10에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"5 이상 10 이하인 수","correct":true},{"t":"5 초과 10 이하인 수","mis":"M5-2-u1-X04"},{"t":"5 이상 10 미만인 수","mis":"M5-2-u1-X04"},{"t":"5 초과 10 미만인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","5는 ●이라 들어가요 · 10은 ●이라 들어가요.","그래서 5 이상 10 이하인 수예요."],"variant_rule":{"alt":[{"stem":"수직선에 9에는 ●, 13에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"9 이상 13 미만인 수","correct":true},{"t":"9 초과 13 미만인 수","mis":"M5-2-u1-X04"},{"t":"9 이상 13 이하인 수","mis":"M5-2-u1-X04"},{"t":"9 초과 13 이하인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","9는 ●이라 들어가요 · 13은 ○이라 들어가지 않아요.","그래서 9 이상 13 미만인 수예요."]},{"stem":"수직선에 52에는 ○, 58에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"52 초과 58 이하인 수","correct":true},{"t":"52 이상 58 이하인 수","mis":"M5-2-u1-X04"},{"t":"52 초과 58 미만인 수","mis":"M5-2-u1-X04"},{"t":"52 이상 58 미만인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","52는 ○이라 들어가지 않아요 · 58은 ●이라 들어가요.","그래서 52 초과 58 이하인 수예요."]},{"stem":"수직선에 17에는 ●, 22에는 ○이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 수직선이 나타내는 수의 범위는 어느 것인가요?","options":[{"t":"17 이상 22 미만인 수","correct":true},{"t":"17 초과 22 미만인 수","mis":"M5-2-u1-X04"},{"t":"17 이상 22 이하인 수","mis":"M5-2-u1-X04"},{"t":"17 초과 22 이하인 수","mis":"M5-2-u1-X04"}],"explanation":["●은 그 수를 포함하고 ○은 포함하지 않아요.","17은 ●이라 들어가요 · 22는 ○이라 들어가지 않아요.","그래서 17 이상 22 미만인 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#2','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'mc','auto','경고 단계의 체감 온도 범위는 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X01','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"경고 단계의 체감 온도 범위는 어느 것인가요?","options":[{"t":"34 °C 이상 37 °C 미만","correct":true},{"t":"34 °C 이상 37 °C 이하","mis":"M5-2-u1-X02"},{"t":"34 °C 초과 37 °C 미만","mis":"M5-2-u1-X01"},{"t":"31 °C 이상 34 °C 미만","mis":"M5-2-u1-X16"}],"explanation":["표에서 경고 단계 칸을 찾아요.","경고는 34 °C와 같거나 높고 37 °C보다 낮은 온도예요.","그래서 34 °C 이상 37 °C 미만이에요."],"asset":{"type":"passage","lines":["체감 온도(어린이)에 따른 단계","관심 — 29 °C 이상 31 °C 미만","주의 — 31 °C 이상 34 °C 미만","경고 — 34 °C 이상 37 °C 미만","위험 — 37 °C 이상"]},"variant_rule":{"alt":[{"stem":"주의 단계의 체감 온도 범위는 어느 것인가요?","options":[{"t":"31 °C 이상 34 °C 미만","correct":true},{"t":"31 °C 이상 34 °C 이하","mis":"M5-2-u1-X02"},{"t":"31 °C 초과 34 °C 미만","mis":"M5-2-u1-X01"},{"t":"29 °C 이상 31 °C 미만","mis":"M5-2-u1-X16"}],"explanation":["표에서 주의 단계 칸을 찾아요.","주의는 31 °C와 같거나 높고 34 °C보다 낮은 온도예요.","그래서 31 °C 이상 34 °C 미만이에요."],"asset":{"type":"passage","lines":["체감 온도(어린이)에 따른 단계","관심 — 29 °C 이상 31 °C 미만","주의 — 31 °C 이상 34 °C 미만","경고 — 34 °C 이상 37 °C 미만","위험 — 37 °C 이상"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#3','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'mc','auto','지금 체감 온도는 30.9 °C예요. 어느 단계인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],true,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"지금 체감 온도는 30.9 °C예요. 어느 단계인가요?","options":[{"t":"관심","correct":true},{"t":"주의","mis":"M5-2-u1-X02"},{"t":"경고","mis":"M5-2-u1-X16"},{"t":"위험","mis":"M5-2-u1-X16"}],"explanation":["관심은 29 °C 이상 31 °C 미만이에요.","30.9 °C는 29 °C보다 높고 31 °C보다 낮아요.","그래서 관심 단계예요."],"asset":{"type":"passage","lines":["체감 온도(어린이)에 따른 단계","관심 — 29 °C 이상 31 °C 미만","주의 — 31 °C 이상 34 °C 미만","경고 — 34 °C 이상 37 °C 미만","위험 — 37 °C 이상"]},"variant_rule":{"alt":[{"stem":"2시에는 예상 체감 온도가 31 °C라고 해요. 어느 단계인가요?","options":[{"t":"주의","correct":true},{"t":"관심","mis":"M5-2-u1-X02"},{"t":"경고","mis":"M5-2-u1-X16"},{"t":"위험","mis":"M5-2-u1-X16"}],"explanation":["관심은 31 °C 미만, 주의는 31 °C 이상이에요.","31 °C는 관심의 「31 °C 미만」에 들지 않고 주의의 「31 °C 이상」에 들어요.","그래서 주의 단계 — 야외 활동 때 충분히 쉬어야 해요."],"asset":{"type":"passage","lines":["체감 온도(어린이)에 따른 단계","관심 — 29 °C 이상 31 °C 미만","주의 — 31 °C 이상 34 °C 미만","경고 — 34 °C 이상 37 °C 미만","위험 — 37 °C 이상"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#4','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',1,'mc','auto','윤지가 소포의 무게를 재었더니 20 kg이에요. 윤지가 내야 하는 요금은 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],true,'{"seq":4,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"윤지가 소포의 무게를 재었더니 20 kg이에요. 윤지가 내야 하는 요금은 얼마인가요?","options":[{"t":"10000원","correct":true},{"t":"14000원","mis":"M5-2-u1-X02"},{"t":"8000원","mis":"M5-2-u1-X16"},{"t":"5000원","mis":"M5-2-u1-X16"}],"explanation":["20 kg이 어느 칸에 드는지 찾아요.","20 kg은 「10 kg 초과 20 kg 이하」에 들어요 — 20 kg 이하에는 20이 들어가요.","그래서 10000원이에요."],"asset":{"type":"passage","lines":["방문 접수 요금","5 kg 이하 — 5000원","5 kg 초과 10 kg 이하 — 8000원","10 kg 초과 20 kg 이하 — 10000원","20 kg 초과 30 kg 이하 — 14000원"]},"variant_rule":{"alt":[{"stem":"숲 체험장에 12세인 소진이가 입장해요. 소진이의 입장료는 얼마인가요?","options":[{"t":"8000원","correct":true},{"t":"6000원","mis":"M5-2-u1-X02"},{"t":"10000원","mis":"M5-2-u1-X16"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["12세가 어느 칸에 드는지 찾아요.","12세는 「7세 이상 12세 미만」에 들지 않고 「12세 이상 19세 미만」에 들어요.","그래서 8000원이에요."],"asset":{"type":"passage","lines":["숲 체험장 나이별 입장료","7세 미만 — 4000원","7세 이상 12세 미만 — 6000원","12세 이상 19세 미만 — 8000원","19세 이상 — 10000원"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#5','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'mc','auto','5, 7, 8.5, 10 중에서 5 초과 10 미만인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],true,'{"seq":5,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"5, 7, 8.5, 10 중에서 5 초과 10 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"7, 8.5","correct":true},{"t":"5, 7, 8.5","mis":"M5-2-u1-X02"},{"t":"7, 8.5, 10","mis":"M5-2-u1-X02"},{"t":"7","mis":"M5-2-u1-X16"}],"explanation":["5 초과 10 미만인 수는 5보다 크고 10보다 작은 수예요.","경곗값을 살펴보면 5는 들어가지 않고, 10은 들어가지 않아요.","그래서 7, 8.5예요."],"variant_rule":{"alt":[{"stem":"5.1, 8, 10 중에서 5 이상 10 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5.1, 8","correct":true},{"t":"5.1, 8, 10","mis":"M5-2-u1-X02"},{"t":"5.1","mis":"M5-2-u1-X16"},{"t":"10","mis":"M5-2-u1-X03"}],"explanation":["5 이상 10 미만인 수는 5와 같거나 크고 10보다 작은 수예요.","경곗값을 살펴보면 5는 들어가고, 10은 들어가지 않아요.","그래서 5.1, 8이에요."]},{"stem":"5, 6, 9.8 중에서 5 초과 10 이하인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"6, 9.8","correct":true},{"t":"5, 6, 9.8","mis":"M5-2-u1-X02"},{"t":"6","mis":"M5-2-u1-X16"},{"t":"6, 9.8, 5","mis":"M5-2-u1-X16"}],"explanation":["5 초과 10 이하인 수는 5보다 크고 10과 같거나 작은 수예요.","경곗값을 살펴보면 5는 들어가지 않고, 10은 들어가요.","그래서 6, 9.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#6','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'mc','auto','27, 17, 30, 21, 50, 12, 29 중에서 21 초과 30 이하인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X01','M5-2-u1-X16']::text[],true,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"27, 17, 30, 21, 50, 12, 29 중에서 21 초과 30 이하인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"27, 30, 29","correct":true},{"t":"27, 30, 21, 29","mis":"M5-2-u1-X02"},{"t":"27, 29","mis":"M5-2-u1-X01"},{"t":"27, 30","mis":"M5-2-u1-X16"}],"explanation":["21 초과 30 이하인 수는 21보다 크고 30과 같거나 작은 수예요.","경곗값을 살펴보면 21은 들어가지 않고, 30은 들어가요.","그래서 27, 30, 29예요."],"variant_rule":{"alt":[{"stem":"29, 38.2, 45.1, 36, 42.7, 43, 40, 35.9 중에서 36 이상 43 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"38.2, 36, 42.7, 40","correct":true},{"t":"38.2, 42.7, 40","mis":"M5-2-u1-X01"},{"t":"38.2, 36, 42.7, 43, 40","mis":"M5-2-u1-X02"},{"t":"38.2, 36, 42.7","mis":"M5-2-u1-X16"}],"explanation":["36 이상 43 미만인 수는 36과 같거나 크고 43보다 작은 수예요.","경곗값을 살펴보면 36은 들어가고, 43은 들어가지 않아요.","그래서 38.2, 36, 42.7, 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#7','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'mc','auto','8세인 윤우는 이 감기약을 한 번에 몇 mL 먹어야 하나요?',ARRAY['M5-2-u1-X03','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"8세인 윤우는 이 감기약을 한 번에 몇 mL 먹어야 하나요?","options":[{"t":"7.5 mL","correct":true},{"t":"5 mL","mis":"M5-2-u1-X03"},{"t":"10 mL","mis":"M5-2-u1-X16"},{"t":"3.75 mL","mis":"M5-2-u1-X16"}],"explanation":["8세가 어느 칸에 드는지 찾아요.","8세는 7세와 같거나 많고 11세보다 적어 「7세 이상 11세 미만」에 들어요.","그래서 7.5 mL예요."],"asset":{"type":"passage","lines":["어린이 감기약 한 번에 먹는 용량","2세 이상 3세 미만 — 3.75 mL","3세 이상 7세 미만 — 5 mL","7세 이상 11세 미만 — 7.5 mL","11세 이상 15세 미만 — 10 mL","15세 이상 — 15 mL"]},"variant_rule":{"alt":[{"stem":"11세인 서진이는 이 감기약을 한 번에 몇 mL 먹어야 하나요?","options":[{"t":"10 mL","correct":true},{"t":"7.5 mL","mis":"M5-2-u1-X02"},{"t":"15 mL","mis":"M5-2-u1-X16"},{"t":"5 mL","mis":"M5-2-u1-X16"}],"explanation":["11세가 어느 칸에 드는지 찾아요.","11세는 「7세 이상 11세 미만」에 들지 않고 「11세 이상 15세 미만」에 들어요.","그래서 10 mL예요."],"asset":{"type":"passage","lines":["어린이 감기약 한 번에 먹는 용량","2세 이상 3세 미만 — 3.75 mL","3세 이상 7세 미만 — 5 mL","7세 이상 11세 미만 — 7.5 mL","11세 이상 15세 미만 — 10 mL","15세 이상 — 15 mL"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#8','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'mc','auto','가희와 등급이 같은 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X02','M5-2-u1-X03']::text[],false,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"가희와 등급이 같은 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"나리, 유나","correct":true},{"t":"유나","mis":"M5-2-u1-X01"},{"t":"지아, 나리, 유나","mis":"M5-2-u1-X02"},{"t":"성윤, 나리, 유나","mis":"M5-2-u1-X03"}],"explanation":["가희 37회는 「35회 초과 59회 이하」라 2등급이에요.","나리 59회는 59회 이하라 들어가고, 유나 41회도 들어가요.","지아 35회는 35회 초과가 아니라 빠지고, 성윤 61회는 1등급이에요 — 나리, 유나."],"asset":{"type":"passage","lines":["윗몸 말아 올리기 평가 기준(여자)","1등급 59회 초과 · 2등급 35회 초과 59회 이하","3등급 22회 초과 35회 이하 · 4등급 6회 초과 22회 이하","5등급 6회 이하","기록 — 가희 37회 · 성윤 61회 · 지아 35회 · 나리 59회 · 유나 41회"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#9','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',2,'sa','auto','11세인 은우와 19세인 형이 박물관에 가요. 은우와 형의 입장료는 모두 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"11세인 은우와 19세인 형이 박물관에 가요. 은우와 형의 입장료는 모두 얼마인가요? 숫자로 쓰세요.","answer":["3000"],"explanation":["은우 11세는 13세 미만이라 어린이 1000원이에요.","형 19세는 「13세 이상 19세 미만」에 들지 않고 「19세 이상」에 들어 어른 2000원이에요.","1000 + 2000 = 3000(원)이에요."],"asset":{"type":"passage","lines":["박물관 입장료","어린이(13세 미만) — 1000원","청소년(13세 이상 19세 미만) — 1500원","어른(19세 이상) — 2000원"]},"variant_rule":{"alt":[{"stem":"준석이네 가족 중에서 입장료로 2000원을 내야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["2000원은 「19세 초과」예요.","아빠 42세와 엄마 39세가 19세보다 많아요.","형 15세는 「14세 초과 19세 이하」라 1000원 — 2000원은 2명이에요."],"asset":{"type":"passage","lines":["준석이네 가족의 나이","아빠 42세 · 엄마 39세 · 형 15세 · 준석 11세 · 동생 7세","박물관 나이별 입장료","19세 초과 — 2000원 · 14세 초과 19세 이하 — 1000원","7세 초과 14세 이하 — 500원 · 7세 이하 — 무료"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_basic#10','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_basic','lesson_basic','M5-2-u1-C3',3,'mc','auto','5학년 남학생인 정우의 몸무게가 36 kg이에요. 정우가 속한 체급과 그 체급의 몸무게 범위를 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X04','M5-2-u1-X16']::text[],false,'{"seq":10,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"5학년 남학생인 정우의 몸무게가 36 kg이에요. 정우가 속한 체급과 그 체급의 몸무게 범위를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"밴텀급 — 34 kg 초과 36 kg 이하","correct":true},{"t":"페더급 — 36 kg 초과 39 kg 이하","mis":"M5-2-u1-X02"},{"t":"밴텀급 — 34 kg 이상 36 kg 미만","mis":"M5-2-u1-X04"},{"t":"플라이급 — 32 kg 초과 34 kg 이하","mis":"M5-2-u1-X16"}],"explanation":["36 kg이 어느 칸에 드는지 찾아요.","36 kg은 「34 kg 초과 36 kg 이하」에 들어요 — 36 kg 이하에는 36이 들어가요.","「36 kg 초과」인 페더급에는 36 kg이 들지 않으니 밴텀급이에요."],"asset":{"type":"passage","lines":["체급별 몸무게(초등학교 5학년 남학생용)","핀급 — 32 kg 이하","플라이급 — 32 kg 초과 34 kg 이하","밴텀급 — 34 kg 초과 36 kg 이하","페더급 — 36 kg 초과 39 kg 이하"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#1','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',2,'mc','auto','㉠ 5 초과 7 이하인 수 ㉡ 6 이상 10 이하인 수 ㉢ 4 초과 11 미만인 수 중에서 5를 포함하는 수의 범위는 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],true,'{"seq":1,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"㉠ 5 초과 7 이하인 수 ㉡ 6 이상 10 이하인 수 ㉢ 4 초과 11 미만인 수 중에서 5를 포함하는 수의 범위는 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-2-u1-X02"},{"t":"㉡","mis":"M5-2-u1-X16"},{"t":"㉠, ㉢","mis":"M5-2-u1-X02"}],"explanation":["㉠ 5 초과에는 5가 들어가지 않아요.","㉡은 6과 같거나 큰 수라 5가 빠져요.","㉢ 4 초과 11 미만에는 5가 들어가요 — 답은 ㉢이에요."],"variant_rule":{"alt":[{"stem":"6.5, 5, 7, 7.1, 4, 4.9, 8.1, 9 중에서 7 초과인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"7.1, 8.1, 9","correct":true},{"t":"7, 7.1, 8.1, 9","mis":"M5-2-u1-X02"},{"t":"6.5, 5, 4, 4.9","mis":"M5-2-u1-X03"},{"t":"8.1, 9","mis":"M5-2-u1-X16"}],"explanation":["7 초과인 수는 7보다 큰 수예요.","7은 들어가지 않고 7.1은 들어가요.","그래서 7.1, 8.1, 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#2','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',2,'sa','auto','86, 87, 88, 89, 90, 91은 「□ 초과 91 이하인 자연수」를 모두 쓴 것이에요. □에 알맞은 자연수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"86, 87, 88, 89, 90, 91은 「□ 초과 91 이하인 자연수」를 모두 쓴 것이에요. □에 알맞은 자연수를 쓰세요.","answer":["85"],"explanation":["□ 초과에는 □가 들어가지 않아요.","가장 작은 수가 86이니 □는 86보다 1 작은 수예요.","그래서 □는 85 — 85 초과 91 이하인 자연수예요."],"variant_rule":{"alt":[{"stem":"10 초과 15 이하인 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["10 초과에는 10이, 15 이하에는 15가 들어가는지 봐요.","11, 12, 13, 14, 15가 들어가요.","모두 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#3','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'sa','auto','167 이상 175 미만인 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"167 이상 175 미만인 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["167 이상이니 167이 들어가고, 175 미만이니 175는 빠져요.","167부터 174까지 세면 174 − 167 + 1 = 8이에요.","175 − 167 = 8과 같아요 — 모두 8개예요."],"variant_rule":{"alt":[{"stem":"20, 17.8, 25, 21.3, 18.6, 16, 19.1, 30 중에서 19 초과 25 미만인 수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19보다 크고 25보다 작은 수를 찾아요.","20, 21.3, 19.1이 들어가고 25는 빠져요.","모두 3개예요."]},{"stem":"25 이상 30 이하인 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["25 이상이니 25, 30 이하이니 30이 들어가요.","25, 26, 27, 28, 29, 30을 세어요.","모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#4','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'sa','auto','한 수직선에는 87에 ●, 92에 ●이 그려져 두 점 사이가 이어져 있고, 다른 수직선에는 89에 ○, 94에 ●이 그려져 두 점 사이가 이어져 있어요. 두 수직선에 나타낸 수의 범위에 공통으로 포함되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"한 수직선에는 87에 ●, 92에 ●이 그려져 두 점 사이가 이어져 있고, 다른 수직선에는 89에 ○, 94에 ●이 그려져 두 점 사이가 이어져 있어요. 두 수직선에 나타낸 수의 범위에 공통으로 포함되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["첫째 수직선은 87 이상 92 이하, 둘째 수직선은 89 초과 94 이하예요.","둘 다 들어가는 자연수는 90, 91, 92예요.","89는 둘째에서 빠지니 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#5','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'mc','auto','수직선에 70에는 ○, 74에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 이 수의 범위에 포함되지 않는 수는 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X17']::text[],false,'{"seq":5,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"수직선에 70에는 ○, 74에는 ●이 그려져 있고 두 점 사이가 선으로 이어져 있어요. 이 수의 범위에 포함되지 않는 수는 어느 것인가요?","options":[{"t":"70","correct":true},{"t":"74","mis":"M5-2-u1-X04"},{"t":"71","mis":"M5-2-u1-X17"},{"t":"72","mis":"M5-2-u1-X17"}],"explanation":["70에 ○, 74에 ●이니 70 초과 74 이하인 수예요.","70은 ○이라 포함되지 않고, 74는 ●이라 포함돼요.","그래서 포함되지 않는 수는 70이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#6','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'mc','auto','자연수 부분이 2이고, 소수 첫째 자리 숫자가 5 이상 8 미만인 소수 한 자리 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X01','M5-2-u1-X05']::text[],false,'{"seq":6,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"자연수 부분이 2이고, 소수 첫째 자리 숫자가 5 이상 8 미만인 소수 한 자리 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2.5, 2.6, 2.7","correct":true},{"t":"2.5, 2.6, 2.7, 2.8","mis":"M5-2-u1-X02"},{"t":"2.6, 2.7","mis":"M5-2-u1-X01"},{"t":"2.6, 2.7, 2.8","mis":"M5-2-u1-X05"}],"explanation":["소수 첫째 자리 숫자가 5 이상 8 미만이면 5, 6, 7이에요.","8은 미만이라 빠지고 5는 이상이라 들어가요.","그래서 2.5, 2.6, 2.7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#7','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',3,'mc','auto','7세인 준석이의 동생은 입장료가 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"7세인 준석이의 동생은 입장료가 얼마인가요?","options":[{"t":"무료","correct":true},{"t":"500원","mis":"M5-2-u1-X02"},{"t":"1000원","mis":"M5-2-u1-X16"},{"t":"2000원","mis":"M5-2-u1-X16"}],"explanation":["7세가 어느 칸에 드는지 찾아요.","7세는 「7세 초과 14세 이하」에 들지 않고 「7세 이하」에 들어요.","그래서 동생은 무료예요."],"asset":{"type":"passage","lines":["준석이네 가족의 나이","아빠 42세 · 엄마 39세 · 형 15세 · 준석 11세 · 동생 7세","박물관 나이별 입장료","19세 초과 — 2000원 · 14세 초과 19세 이하 — 1000원","7세 초과 14세 이하 — 500원 · 7세 이하 — 무료"]},"variant_rule":{"alt":[{"stem":"15세인 준석이의 형은 입장료가 얼마인가요?","options":[{"t":"1000원","correct":true},{"t":"500원","mis":"M5-2-u1-X03"},{"t":"2000원","mis":"M5-2-u1-X03"},{"t":"무료","mis":"M5-2-u1-X16"}],"explanation":["15세가 어느 칸에 드는지 찾아요.","15세는 14세보다 많고 19세와 같거나 적어 「14세 초과 19세 이하」에 들어요.","그래서 형은 1000원이에요."],"asset":{"type":"passage","lines":["준석이네 가족의 나이","아빠 42세 · 엄마 39세 · 형 15세 · 준석 11세 · 동생 7세","박물관 나이별 입장료","19세 초과 — 2000원 · 14세 초과 19세 이하 — 1000원","7세 초과 14세 이하 — 500원 · 7세 이하 — 무료"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#8','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',4,'mc','auto','12세인 소진이와 39세인 어머니가 숲 체험장에 입장할 때 내야 하는 입장료는 모두 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],true,'{"seq":8,"concept":"M5-2-u1-C3","difficulty":4,"kind":"mc","stem":"12세인 소진이와 39세인 어머니가 숲 체험장에 입장할 때 내야 하는 입장료는 모두 얼마인가요?","options":[{"t":"18000원","correct":true},{"t":"16000원","mis":"M5-2-u1-X02"},{"t":"20000원","mis":"M5-2-u1-X16"},{"t":"14000원","mis":"M5-2-u1-X16"}],"explanation":["소진이 12세는 「12세 이상 19세 미만」이라 8000원이에요.","어머니 39세는 「19세 이상」이라 10000원이에요.","8000 + 10000 = 18000(원)이에요."],"asset":{"type":"passage","lines":["숲 체험장 나이별 입장료","7세 미만 — 4000원","7세 이상 12세 미만 — 6000원","12세 이상 19세 미만 — 8000원","19세 이상 — 10000원"]},"variant_rule":{"alt":[{"stem":"11세인 은우와 19세인 형이 박물관에 갈 때 입장료는 모두 얼마인가요?","options":[{"t":"3000원","correct":true},{"t":"2500원","mis":"M5-2-u1-X02"},{"t":"3500원","mis":"M5-2-u1-X16"},{"t":"2000원","mis":"M5-2-u1-X16"}],"explanation":["은우 11세는 13세 미만이라 1000원이에요.","형 19세는 「19세 미만」에 들지 않고 「19세 이상」이라 2000원이에요.","1000 + 2000 = 3000(원)이에요."],"asset":{"type":"passage","lines":["박물관 입장료","어린이(13세 미만) — 1000원","청소년(13세 이상 19세 미만) — 1500원","어른(19세 이상) — 2000원"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#9','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',4,'essay','teacher','체감 온도 표에서 31 °C는 관심 단계가 아니라 주의 단계예요. 그 까닭을 「이상」과 「미만」의 뜻으로 설명하고, 표가 이렇게 짜인 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"체감 온도 표에서 31 °C는 관심 단계가 아니라 주의 단계예요. 그 까닭을 「이상」과 「미만」의 뜻으로 설명하고, 표가 이렇게 짜인 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 관심은 31 °C 미만이라 31 °C가 들지 않고, 주의는 31 °C 이상이라 31 °C가 든다. 경곗값을 한쪽에만 넣어 어떤 온도든 한 단계에만 들어가므로 헷갈리지 않는다.","scoring_points":["관심은 31 °C 미만이라 31을 포함하지 않음을 썼는가","주의는 31 °C 이상이라 31을 포함함을 썼는가","경곗값을 한쪽에만 넣어 겹치지 않게 했다는 좋은 점을 썼는가"]},"explanation":["31 °C 미만에는 31 °C가 들지 않아요.","31 °C 이상에는 31 °C가 들어요.","경곗값을 한쪽에만 넣어 어느 온도든 한 단계에만 들어가요."],"asset":{"type":"passage","lines":["체감 온도(어린이)에 따른 단계","관심 — 29 °C 이상 31 °C 미만","주의 — 31 °C 이상 34 °C 미만","경고 — 34 °C 이상 37 °C 미만","위험 — 37 °C 이상"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L04_challenge#10','math',5,2,'u1','L04','tb_g5_2_math_u1_L04_challenge','lesson_challenge','M5-2-u1-C3',4,'essay','teacher','「5 이상인 수」와 「10 이하인 수」를 투명 종이에 각각 수직선으로 나타내고 겹쳐 보았어요. 겹친 부분은 어떤 수의 범위인지 쓰고, 수직선에 나타내는 방법을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「5 이상인 수」와 「10 이하인 수」를 투명 종이에 각각 수직선으로 나타내고 겹쳐 보았어요. 겹친 부분은 어떤 수의 범위인지 쓰고, 수직선에 나타내는 방법을 설명하세요.","answer_guide":{"answer":"예: 5 이상 10 이하인 수이다. 5와 10을 포함하므로 5와 10에 ●을 그리고 두 점 사이를 선으로 잇는다.","scoring_points":["겹친 부분이 5 이상 10 이하인 수라고 썼는가","5와 10에 ●을 그림을 썼는가","두 점 사이를 선으로 이음을 썼는가"]},"explanation":["5 이상은 5에서 오른쪽, 10 이하는 10에서 왼쪽으로 이어져요.","두 선이 겹치는 곳은 5부터 10까지예요.","5와 10을 포함하니 둘 다 ●, 사이는 선으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#1','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',1,'mc','auto','학생회에서 우리 학교 학생 543명 모두에게 친환경 가방을 1개씩 나누어 주려고 해요. 친환경 가방은 10개 묶음 또는 100개 묶음으로만 팔아요. 10개 묶음으로 산다면 최소 몇 개를 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"학생회에서 우리 학교 학생 543명 모두에게 친환경 가방을 1개씩 나누어 주려고 해요. 친환경 가방은 10개 묶음 또는 100개 묶음으로만 팔아요. 10개 묶음으로 산다면 최소 몇 개를 사야 하나요?","options":[{"t":"550개","correct":true},{"t":"540개","mis":"M5-2-u1-X13"},{"t":"543개","mis":"M5-2-u1-X14"},{"t":"600개","mis":"M5-2-u1-X09"}],"explanation":["10개 54묶음은 540개라 543명에게 나누어 주기에 모자라요.","한 묶음을 더 사서 55묶음, 550개를 사야 해요.","543을 올림하여 십의 자리까지 나타내면 550이에요."],"variant_rule":{"alt":[{"stem":"학생회에서 우리 학교 학생 543명 모두에게 친환경 가방을 1개씩 나누어 주려고 해요. 친환경 가방은 10개 묶음 또는 100개 묶음으로만 팔아요. 100개 묶음으로 산다면 최소 몇 개를 사야 하나요?","options":[{"t":"600개","correct":true},{"t":"500개","mis":"M5-2-u1-X13"},{"t":"543개","mis":"M5-2-u1-X14"},{"t":"550개","mis":"M5-2-u1-X09"}],"explanation":["100개 5묶음은 500개라 543명에게 나누어 주기에 모자라요.","한 묶음을 더 사서 6묶음, 600개를 사야 해요.","543을 올림하여 백의 자리까지 나타내면 600이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#2','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',1,'mc','auto','3.457을 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"3.457을 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.46","correct":true},{"t":"3.45","mis":"M5-2-u1-X08"},{"t":"3.5","mis":"M5-2-u1-X09"},{"t":"3.47","mis":"M5-2-u1-X16"}],"explanation":["올림은 소수 둘째 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 소수 둘째 자리 숫자를 1 크게 하고 아래는 0으로 해요.","3.457 → 3.46이에요."],"variant_rule":{"alt":[{"stem":"3.457을 올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.5","correct":true},{"t":"3.4","mis":"M5-2-u1-X08"},{"t":"3.46","mis":"M5-2-u1-X09"},{"t":"4","mis":"M5-2-u1-X09"}],"explanation":["올림은 소수 첫째 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 소수 첫째 자리 숫자를 1 크게 하고 아래는 0으로 해요.","3.457 → 3.5예요."]},{"stem":"3.457을 올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"4","correct":true},{"t":"3","mis":"M5-2-u1-X08"},{"t":"3.5","mis":"M5-2-u1-X09"},{"t":"10","mis":"M5-2-u1-X09"}],"explanation":["올림은 일의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 일의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","3.457 → 4예요."]},{"stem":"4.521을 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.53","correct":true},{"t":"4.52","mis":"M5-2-u1-X08"},{"t":"4.6","mis":"M5-2-u1-X09"},{"t":"4.54","mis":"M5-2-u1-X16"}],"explanation":["올림은 소수 둘째 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 소수 둘째 자리 숫자를 1 크게 하고 아래는 0으로 해요.","4.521 → 4.53이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true