INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#4','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',1,'mc','auto','구하려는 자리의 아래 수를 올려서 나타내는 방법을 무엇이라고 하나요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],false,'{"seq":4,"concept":"M5-2-u1-C4","difficulty":1,"kind":"mc","stem":"구하려는 자리의 아래 수를 올려서 나타내는 방법을 무엇이라고 하나요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X08"},{"t":"반올림","mis":"M5-2-u1-X08"},{"t":"수의 범위","mis":"M5-2-u1-X17"}],"explanation":["아래 수를 올려서 나타내면 올림이에요.","543을 올림하여 십의 자리까지 나타내면 550이에요.","올림하면 원래 수보다 크거나 같은 수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#5','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'mc','auto','1.528을 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":5,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"1.528을 올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.53","correct":true},{"t":"1.52","mis":"M5-2-u1-X08"},{"t":"1.6","mis":"M5-2-u1-X09"},{"t":"1.54","mis":"M5-2-u1-X16"}],"explanation":["올림은 소수 둘째 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 소수 둘째 자리 숫자를 1 크게 하고 아래는 0으로 해요.","1.528 → 1.53이에요."],"variant_rule":{"alt":[{"stem":"1.528을 올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.6","correct":true},{"t":"1.5","mis":"M5-2-u1-X08"},{"t":"1.53","mis":"M5-2-u1-X09"},{"t":"2","mis":"M5-2-u1-X09"}],"explanation":["올림은 소수 첫째 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 소수 첫째 자리 숫자를 1 크게 하고 아래는 0으로 해요.","1.528 → 1.6이에요."]},{"stem":"1.528을 올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M5-2-u1-X08"},{"t":"1.6","mis":"M5-2-u1-X09"},{"t":"10","mis":"M5-2-u1-X09"}],"explanation":["올림은 일의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 일의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","1.528 → 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#6','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'match','auto','올림하여 백의 자리까지 나타낸 수가 같은 것끼리 이으세요.','{}'::text[],false,'{"seq":6,"concept":"M5-2-u1-C4","difficulty":2,"kind":"match","stem":"올림하여 백의 자리까지 나타낸 수가 같은 것끼리 이으세요.","pairs":[{"l":"2616","r":"2669"},{"l":"2500","r":"2461"},{"l":"2563","r":"2506"}],"mis":"M5-2-u1-X07","explanation":["2616과 2669는 2700, 2563과 2506은 2600이 돼요.","2461은 2500이 되고, 2500은 백의 자리 아래가 모두 0이라 그대로 2500이에요.","그래서 2616–2669, 2500–2461, 2563–2506이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#7','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'sa','auto','439를 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C4","difficulty":2,"kind":"sa","stem":"439를 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["올림은 백의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 백의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","439 → 500이에요."],"variant_rule":{"alt":[{"stem":"537을 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["600"],"explanation":["올림은 백의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 백의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","537 → 600이에요."]},{"stem":"5461을 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["5500"],"explanation":["올림은 백의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 백의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","5461 → 5500이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#8','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'mc','auto','301, 310, 311, 314, 320, 321, 324 중에서 올림하여 십의 자리까지 나타내면 320이 되는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X08','M5-2-u1-X15']::text[],false,'{"seq":8,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"301, 310, 311, 314, 320, 321, 324 중에서 올림하여 십의 자리까지 나타내면 320이 되는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"311, 314, 320","correct":true},{"t":"310, 311, 314, 320","mis":"M5-2-u1-X07"},{"t":"311, 314, 320, 321, 324","mis":"M5-2-u1-X08"},{"t":"311, 314","mis":"M5-2-u1-X15"}],"explanation":["올림하여 320이 되려면 311부터 320까지의 수여야 해요.","310은 일의 자리가 0이라 그대로 310, 321·324는 330이 돼요.","320은 일의 자리가 0이라 그대로 320 — 311, 314, 320이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#9','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',2,'error','auto','두 친구의 말을 읽고 잘못 말한 것을 고르세요.',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],false,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":2,"kind":"error","stem":"두 친구의 말을 읽고 잘못 말한 것을 고르세요.","options":[{"t":"우제 — 「2406을 올림하여 백의 자리까지 나타내면 2400이에요.」","correct":true,"mis_target":"M5-2-u1-X08"},{"t":"현지 — 「7415를 올림하여 천의 자리까지 나타내면 8000이에요.」","mis":"M5-2-u1-X17"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u1-X08"}],"explanation":["2406의 백의 자리 아래 수 6을 올리면 2500이에요.","2400은 아래 수를 버린 버림이에요.","7415의 천의 자리 아래 수를 올리면 8000 — 현지는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"우제","text":"2406을 올림하여 백의 자리까지 나타내면 2400이에요."},{"who":"현지","text":"7415를 올림하여 천의 자리까지 나타내면 8000이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_basic#10','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_basic','lesson_basic','M5-2-u1-C4',3,'ox','auto','2500을 올림하여 백의 자리까지 나타내면 2600이에요.',ARRAY['M5-2-u1-X07']::text[],true,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":3,"kind":"ox","stem":"2500을 올림하여 백의 자리까지 나타내면 2600이에요.","answer":"X","reason_options":[{"t":"백의 자리 아래 수가 모두 0이라 올릴 것이 없어 2500이라서","correct":true},{"t":"올림은 언제나 한 칸 올리니까","mis":"M5-2-u1-X07"}],"mis":"M5-2-u1-X07","explanation":["올림은 구하려는 자리의 아래 수를 올려요.","2500은 백의 자리 아래가 00이라 올릴 것이 없어요.","그래서 그대로 2500이에요."],"variant_rule":{"alt":[{"stem":"310을 올림하여 십의 자리까지 나타내면 320이에요.","answer":"X","reason_options":[{"t":"십의 자리 아래 수가 0이라 올릴 것이 없어 310이라서","correct":true},{"t":"올림은 언제나 한 칸 올리니까","mis":"M5-2-u1-X07"}],"explanation":["올림은 구하려는 자리의 아래 수를 올려요.","310은 일의 자리가 0이라 올릴 것이 없어요.","그래서 그대로 310이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#1','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',2,'mc','auto','만들기 재료로 찰흙 170 g이 필요한데 찰흙은 100 g씩 포장되어 있어요. 찰흙을 최소 몇 g 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X16']::text[],true,'{"seq":1,"concept":"M5-2-u1-C4","difficulty":2,"kind":"mc","stem":"만들기 재료로 찰흙 170 g이 필요한데 찰흙은 100 g씩 포장되어 있어요. 찰흙을 최소 몇 g 사야 하나요?","options":[{"t":"200 g","correct":true},{"t":"100 g","mis":"M5-2-u1-X13"},{"t":"170 g","mis":"M5-2-u1-X14"},{"t":"300 g","mis":"M5-2-u1-X16"}],"explanation":["100 g 한 봉지로는 70 g이 모자라요.","모자라면 안 되니 한 봉지 더 — 올림해요.","170을 올림하여 백의 자리까지 나타내면 200이라 200 g을 사요."],"variant_rule":{"alt":[{"stem":"색종이가 23장 필요한데 색종이는 한 묶음이 10장이에요. 색종이를 최소 몇 장 사야 하나요?","options":[{"t":"30장","correct":true},{"t":"20장","mis":"M5-2-u1-X13"},{"t":"23장","mis":"M5-2-u1-X14"},{"t":"100장","mis":"M5-2-u1-X09"}],"explanation":["2묶음 20장으로는 3장이 모자라요.","모자라면 안 되니 한 묶음 더 — 올림해요.","23을 올림하여 십의 자리까지 나타내면 30이라 30장을 사요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#2','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',2,'sa','auto','올림하여 십의 자리까지 나타내면 230이 되는 수 중에서 가장 큰 자연수를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u1-C4","difficulty":2,"kind":"sa","stem":"올림하여 십의 자리까지 나타내면 230이 되는 수 중에서 가장 큰 자연수를 구하세요. 숫자로 쓰세요.","answer":["230"],"explanation":["올림하여 230이 되는 자연수는 221, 222, …, 229, 230이에요.","230은 일의 자리가 0이라 올릴 것이 없어 그대로 230이에요.","그래서 가장 큰 자연수는 230이에요."],"variant_rule":{"alt":[{"stem":"올림하여 십의 자리까지 나타내면 230이 되는 수 중에서 가장 작은 자연수를 구하세요. 숫자로 쓰세요.","answer":["221"],"explanation":["220은 올릴 것이 없어 그대로 220이에요.","221부터는 일의 자리를 올려 230이 돼요.","그래서 가장 작은 자연수는 221이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#3','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'sa','auto','네 자리 수 2□31을 올림하여 백의 자리까지 나타내면 2700이에요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-2-u1-C4","difficulty":3,"kind":"sa","stem":"네 자리 수 2□31을 올림하여 백의 자리까지 나타내면 2700이에요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["올림하여 백의 자리까지 2700이 되려면 2601부터 2700까지의 수예요.","2□31은 일의 자리가 1이라 백의 자리 숫자 □가 1 커져서 7이 돼요.","그래서 □는 6 — 2631을 올림하면 2700이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#4','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','740, 745, 751, 763, 772 중에서 올림하여 십의 자리까지 나타낸 수가 760인 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16','M5-2-u1-X09']::text[],false,'{"seq":4,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"740, 745, 751, 763, 772 중에서 올림하여 십의 자리까지 나타낸 수가 760인 것은 어느 것인가요?","options":[{"t":"751","correct":true},{"t":"763","mis":"M5-2-u1-X08"},{"t":"745","mis":"M5-2-u1-X16"},{"t":"772","mis":"M5-2-u1-X09"}],"explanation":["751의 일의 자리 1을 올리면 760이에요.","763은 770, 745는 750, 772는 780이 돼요.","763을 버림하거나 반올림하면 760이지만 올림하면 770이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#5','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','문구점에서 색종이를 100장씩 묶음으로만 팔아요. 학생 237명에게 색종이를 3장씩 나누어 주려면 색종이를 최소 몇 장 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X16']::text[],false,'{"seq":5,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"문구점에서 색종이를 100장씩 묶음으로만 팔아요. 학생 237명에게 색종이를 3장씩 나누어 주려면 색종이를 최소 몇 장 사야 하나요?","options":[{"t":"800장","correct":true},{"t":"700장","mis":"M5-2-u1-X13"},{"t":"711장","mis":"M5-2-u1-X14"},{"t":"300장","mis":"M5-2-u1-X16"}],"explanation":["필요한 색종이는 237 × 3 = 711(장)이에요.","100장 묶음 7개는 700장이라 모자라요.","711을 올림하여 백의 자리까지 나타내면 800 — 800장을 사요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#6','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','연도를 세기로 나타낼 때 100년을 한 세기라고 하고, 2001년부터 2100년까지가 21세기예요. 2026년을 올림하여 백의 자리까지 나타내면 2100이에요. 2026년은 몇 세기인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X16','M5-2-u1-X14']::text[],false,'{"seq":6,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"연도를 세기로 나타낼 때 100년을 한 세기라고 하고, 2001년부터 2100년까지가 21세기예요. 2026년을 올림하여 백의 자리까지 나타내면 2100이에요. 2026년은 몇 세기인가요?","options":[{"t":"21세기","correct":true},{"t":"20세기","mis":"M5-2-u1-X13"},{"t":"22세기","mis":"M5-2-u1-X16"},{"t":"2100세기","mis":"M5-2-u1-X14"}],"explanation":["세기는 1년부터 100년을 한 묶음으로 세요.","2026년을 올림하여 백의 자리까지 나타내면 2100이에요.","2100년까지가 21세기이니 2026년은 21세기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#7','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',3,'mc','auto','수를 올림하여 소수 첫째 자리까지 나타낸 것 중에서 바른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08']::text[],false,'{"seq":7,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"수를 올림하여 소수 첫째 자리까지 나타낸 것 중에서 바른 것은 어느 것인가요?","options":[{"t":"2.418 → 2.5","correct":true},{"t":"12.06 → 12.0","mis":"M5-2-u1-X08"},{"t":"4.521 → 4.5","mis":"M5-2-u1-X08"},{"t":"3.457 → 3.4","mis":"M5-2-u1-X08"}],"explanation":["올림은 소수 첫째 자리 아래 수가 0이 아니면 소수 첫째 자리 숫자를 1 크게 해요.","2.418 → 2.5, 12.06 → 12.1, 4.521 → 4.6, 3.457 → 3.5예요.","12.06은 아래 수 6이 0이 아니라 올려야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#8','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',4,'essay','teacher','학생회에서 우리 학교 학생 543명 모두에게 친환경 가방을 1개씩 나누어 주려고 해요. 친환경 가방은 10개 묶음 또는 100개 묶음으로만 팔아요. 10개 묶음과 100개 묶음으로 각각 살 때 최소 몇 개를 사야 하는지 쓰고, 540개나 500개를 사면 안 되는 까닭을 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C4","difficulty":4,"kind":"essay","stem":"학생회에서 우리 학교 학생 543명 모두에게 친환경 가방을 1개씩 나누어 주려고 해요. 친환경 가방은 10개 묶음 또는 100개 묶음으로만 팔아요. 10개 묶음과 100개 묶음으로 각각 살 때 최소 몇 개를 사야 하는지 쓰고, 540개나 500개를 사면 안 되는 까닭을 설명하세요.","answer_guide":{"answer":"예: 10개 묶음은 550개, 100개 묶음은 600개를 사야 한다. 540개(54묶음)와 500개(5묶음)는 543개보다 적어 가방이 모자라기 때문에 필요한 수보다 큰 수로 올림해야 한다.","scoring_points":["550개와 600개를 바르게 구했는가","540개·500개는 543개보다 적어 모자란다고 썼는가","모자라면 안 되니 올림한다는 까닭을 썼는가"]},"explanation":["10개 묶음: 54묶음 540개는 모자라 55묶음 550개예요.","100개 묶음: 5묶음 500개는 모자라 6묶음 600개예요.","모자라면 안 되니 필요한 수보다 크게 — 올림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#9','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',4,'mc','auto','선미는 6400원짜리 필통과 14800원짜리 지갑을 한 개씩 사고 10000원짜리 지폐로만 돈을 내려고 해요. 최소 얼마를 내야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],false,'{"seq":9,"concept":"M5-2-u1-C4","difficulty":4,"kind":"mc","stem":"선미는 6400원짜리 필통과 14800원짜리 지갑을 한 개씩 사고 10000원짜리 지폐로만 돈을 내려고 해요. 최소 얼마를 내야 하나요?","options":[{"t":"30000원","correct":true},{"t":"20000원","mis":"M5-2-u1-X13"},{"t":"21200원","mis":"M5-2-u1-X14"},{"t":"22000원","mis":"M5-2-u1-X09"}],"explanation":["물건값은 6400 + 14800 = 21200(원)이에요.","10000원짜리 지폐로만 내니 만의 자리까지 올림해요.","21200을 올림하여 만의 자리까지 나타내면 30000 — 30000원을 내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L05_challenge#10','math',5,2,'u1','L05','tb_g5_2_math_u1_L05_challenge','lesson_challenge','M5-2-u1-C4',4,'sa','auto','올림하여 십의 자리까지 나타내면 230이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C4","difficulty":4,"kind":"sa","stem":"올림하여 십의 자리까지 나타내면 230이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["올림하여 230이 되는 자연수는 221부터 230까지예요.","220은 그대로 220, 231은 240이 되어 빠져요.","221부터 230까지 세면 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_basic#1','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',1,'mc','auto','세계 식량의 날 행사에서 곤충으로 만든 과자 657개를 10개씩 포장한다면 최대 몇 개까지 포장할 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"세계 식량의 날 행사에서 곤충으로 만든 과자 657개를 10개씩 포장한다면 최대 몇 개까지 포장할 수 있나요?","options":[{"t":"650개","correct":true},{"t":"660개","mis":"M5-2-u1-X13"},{"t":"657개","mis":"M5-2-u1-X14"},{"t":"600개","mis":"M5-2-u1-X09"}],"explanation":["10개씩 66묶음으로 포장하려면 과자가 660개 있어야 해서 모자라요.","65묶음, 650개까지 포장하고 남는 7개는 포장할 수 없어요.","657을 버림하여 십의 자리까지 나타내면 650이에요."],"variant_rule":{"alt":[{"stem":"세계 식량의 날 행사에서 곤충으로 만든 과자 657개를 100개씩 포장한다면 최대 몇 개까지 포장할 수 있나요?","options":[{"t":"600개","correct":true},{"t":"700개","mis":"M5-2-u1-X13"},{"t":"657개","mis":"M5-2-u1-X14"},{"t":"650개","mis":"M5-2-u1-X09"}],"explanation":["100개씩 7묶음으로 포장하려면 과자가 700개 있어야 해서 모자라요.","6묶음, 600개까지 포장하고 남는 57개는 포장할 수 없어요.","657을 버림하여 백의 자리까지 나타내면 600이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_basic#2','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',1,'mc','auto','5.639를 버림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"5.639를 버림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"5.63","correct":true},{"t":"5.64","mis":"M5-2-u1-X08"},{"t":"5.6","mis":"M5-2-u1-X09"},{"t":"5.65","mis":"M5-2-u1-X16"}],"explanation":["버림은 소수 둘째 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","5.639 → 5.63이에요."],"variant_rule":{"alt":[{"stem":"5.639를 버림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"5.6","correct":true},{"t":"5.7","mis":"M5-2-u1-X08"},{"t":"5.63","mis":"M5-2-u1-X09"},{"t":"5","mis":"M5-2-u1-X09"}],"explanation":["버림은 소수 첫째 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","5.639 → 5.6이에요."]},{"stem":"5.639를 버림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"6","mis":"M5-2-u1-X08"},{"t":"5.6","mis":"M5-2-u1-X09"},{"t":"7","mis":"M5-2-u1-X16"}],"explanation":["버림은 일의 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","5.639 → 5예요."]},{"stem":"6.815를 버림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"6.81","correct":true},{"t":"6.82","mis":"M5-2-u1-X08"},{"t":"6.8","mis":"M5-2-u1-X09"},{"t":"6.83","mis":"M5-2-u1-X16"}],"explanation":["버림은 소수 둘째 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","6.815 → 6.81이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
