INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_basic#4','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',1,'mc','auto','구하려는 자리의 아래 수를 버려서 나타내는 방법을 무엇이라고 하나요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],false,'{"seq":4,"concept":"M5-2-u1-C5","difficulty":1,"kind":"mc","stem":"구하려는 자리의 아래 수를 버려서 나타내는 방법을 무엇이라고 하나요?","options":[{"t":"버림","correct":true},{"t":"올림","mis":"M5-2-u1-X08"},{"t":"반올림","mis":"M5-2-u1-X08"},{"t":"수의 범위","mis":"M5-2-u1-X17"}],"explanation":["아래 수를 버려서 나타내면 버림이에요.","657을 버림하여 십의 자리까지 나타내면 650이에요.","버림하면 원래 수보다 작거나 같은 수가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
