INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_basic#7','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',2,'sa','auto','과수원에서 딴 단감 4953개를 한 상자에 100개씩 포장하려고 해요. 포장할 수 있는 단감은 최대 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"과수원에서 딴 단감 4953개를 한 상자에 100개씩 포장하려고 해요. 포장할 수 있는 단감은 최대 몇 개인가요? 숫자로 쓰세요.","answer":["4900"],"explanation":["100개씩 포장하니 남는 53개는 포장할 수 없어요.","4953을 버림하여 백의 자리까지 나타내요.","그래서 최대 4900개예요."],"variant_rule":{"alt":[{"stem":"당근주스를 한 사람에게 100 mL씩 주려고 해요. 당근주스 623 mL를 만들었을 때 나누어 줄 수 있는 당근주스는 최대 몇 mL인가요? 숫자로 쓰세요.","answer":["600"],"explanation":["100 mL씩 주니 남는 23 mL는 한 사람 몫이 안 돼요.","623을 버림하여 백의 자리까지 나타내요.","그래서 최대 600 mL예요."]},{"stem":"공장에서 볼펜을 460자루 만들었어요. 한 상자에 100자루씩 담아 팔 때 상자에 담아 팔 수 있는 볼펜은 최대 몇 자루인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["100자루씩 담으니 남는 60자루는 상자에 담아 팔 수 없어요.","460을 버림하여 백의 자리까지 나타내요.","그래서 최대 400자루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
