INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_basic#9','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',2,'ox','auto','6017을 버림하여 백의 자리까지 나타낸 수와 천의 자리까지 나타낸 수는 같아요.',ARRAY['M5-2-u1-X09']::text[],false,'{"seq":9,"concept":"M5-2-u1-C5","difficulty":2,"kind":"ox","stem":"6017을 버림하여 백의 자리까지 나타낸 수와 천의 자리까지 나타낸 수는 같아요.","answer":"O","reason_options":[{"t":"백의 자리 숫자가 0이라 둘 다 6000이 되어서","correct":true},{"t":"자리가 다르면 언제나 다른 수가 되어서","mis":"M5-2-u1-X09"}],"mis":"M5-2-u1-X09","explanation":["6017을 버림하여 백의 자리까지 나타내면 6000이에요.","천의 자리까지 나타내도 6000이에요.","백의 자리 숫자가 0이라 둘이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_basic#10','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_basic','lesson_basic','M5-2-u1-C5',3,'mc','auto','수를 버림하여 천의 자리까지 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X09','M5-2-u1-X08']::text[],false,'{"seq":10,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"수를 버림하여 천의 자리까지 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8950 → 8000","correct":true},{"t":"21076 → 20000","mis":"M5-2-u1-X09"},{"t":"8950 → 9000","mis":"M5-2-u1-X08"},{"t":"21076 → 22000","mis":"M5-2-u1-X08"}],"explanation":["버림은 천의 자리 아래 수를 어떤 수든 버려요.","8950 → 8000이고, 21076은 천의 자리 숫자 1을 남겨 21000이에요.","21076 → 20000은 천의 자리 숫자까지 버린 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#1','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',2,'mc','auto','매듭 장식 한 개를 만드는 데 끈 10 cm가 필요해요. 끈 56 cm로 매듭 장식을 최대 몇 개 만들 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14']::text[],true,'{"seq":1,"concept":"M5-2-u1-C5","difficulty":2,"kind":"mc","stem":"매듭 장식 한 개를 만드는 데 끈 10 cm가 필요해요. 끈 56 cm로 매듭 장식을 최대 몇 개 만들 수 있나요?","options":[{"t":"5개","correct":true},{"t":"6개","mis":"M5-2-u1-X13"},{"t":"50개","mis":"M5-2-u1-X14"},{"t":"56개","mis":"M5-2-u1-X14"}],"explanation":["10 cm씩 쓰니 남는 6 cm로는 장식을 만들 수 없어요.","56을 버림하여 십의 자리까지 나타내면 50이에요.","끈 50 cm를 이용해 장식 5개를 만들어요."],"variant_rule":{"alt":[{"stem":"책을 10권 읽을 때마다 공책 한 권을 받을 수 있는 도서관 행사에서 책을 27권 읽었어요. 공책을 몇 권 받을 수 있나요?","options":[{"t":"2권","correct":true},{"t":"3권","mis":"M5-2-u1-X13"},{"t":"20권","mis":"M5-2-u1-X14"},{"t":"27권","mis":"M5-2-u1-X14"}],"explanation":["10권마다 한 권이니 남는 7권으로는 받을 수 없어요.","27을 버림하여 십의 자리까지 나타내면 20이에요.","20권은 10권이 2번 — 공책 2권을 받아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#2','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',2,'sa','auto','수 카드 3, 6, 1, 7을 한 번씩만 이용하여 가장 큰 네 자리 수를 만들었어요. 만든 수를 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"수 카드 3, 6, 1, 7을 한 번씩만 이용하여 가장 큰 네 자리 수를 만들었어요. 만든 수를 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["7630"],"explanation":["큰 숫자부터 놓으면 가장 큰 네 자리 수는 7631이에요.","버림하여 십의 자리까지 나타내면 일의 자리 1을 버려요.","그래서 7630이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#3','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'mc','auto','수 카드 「.」, 9, 2, 6을 한 번씩만 이용하여 가장 큰 소수 두 자리 수를 만들고, 만든 수를 버림하여 소수 첫째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":3,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"수 카드 「.」, 9, 2, 6을 한 번씩만 이용하여 가장 큰 소수 두 자리 수를 만들고, 만든 수를 버림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"9.6","correct":true},{"t":"9.7","mis":"M5-2-u1-X08"},{"t":"9.62","mis":"M5-2-u1-X09"},{"t":"6.9","mis":"M5-2-u1-X16"}],"explanation":["소수 두 자리 수는 □.□□ 꼴이라 가장 큰 수는 9.62예요.","버림하여 소수 첫째 자리까지 나타내면 소수 둘째 자리 2를 버려요.","그래서 9.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#4','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'mc','auto','㉠ 3459 ㉡ 3572 ㉢ 3501 ㉣ 3600 중에서 버림하여 백의 자리까지 나타낸 수가 같은 것을 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16']::text[],false,'{"seq":4,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"㉠ 3459 ㉡ 3572 ㉢ 3501 ㉣ 3600 중에서 버림하여 백의 자리까지 나타낸 수가 같은 것을 고른 것은 어느 것인가요?","options":[{"t":"㉡, ㉢","correct":true},{"t":"㉠, ㉢","mis":"M5-2-u1-X08"},{"t":"㉡, ㉢, ㉣","mis":"M5-2-u1-X08"},{"t":"㉢, ㉣","mis":"M5-2-u1-X16"}],"explanation":["버림하여 백의 자리까지 나타내면 3400, 3500, 3500, 3600이에요.","㉡ 3572와 ㉢ 3501이 3500으로 같아요.","반올림하면 ㉠과 ㉢이 같아지니 방법을 잘 봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#5','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'mc','auto','「2347을 버림하여 십의 자리까지 나타낸 수」와 「2347을 버림하여 백의 자리까지 나타낸 수」의 크기를 비교한 것은 어느 것인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X09','M5-2-u1-X08']::text[],true,'{"seq":5,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"「2347을 버림하여 십의 자리까지 나타낸 수」와 「2347을 버림하여 백의 자리까지 나타낸 수」의 크기를 비교한 것은 어느 것인가요?","options":[{"t":"2340 > 2300","correct":true},{"t":"2340 < 2300","mis":"M5-2-u1-X16"},{"t":"2300 = 2300","mis":"M5-2-u1-X09"},{"t":"2350 > 2300","mis":"M5-2-u1-X08"}],"explanation":["2347을 버림하여 십의 자리까지 나타내면 2340이에요.","백의 자리까지 나타내면 2300이에요.","2340이 더 크니 2340 > 2300이에요."],"variant_rule":{"alt":[{"stem":"「35861을 버림하여 천의 자리까지 나타낸 수」와 「34927을 올림하여 백의 자리까지 나타낸 수」의 크기를 비교한 것은 어느 것인가요?","options":[{"t":"35000 > 34900","correct":true},{"t":"35000 < 34900","mis":"M5-2-u1-X16"},{"t":"36000 > 34900","mis":"M5-2-u1-X08"},{"t":"35000 = 35000","mis":"M5-2-u1-X09"}],"explanation":["35861을 버림하여 천의 자리까지 나타내면 35000이에요.","34927을 올림하여 백의 자리까지 나타내면 34900이에요.","35000이 더 크니 35000 > 34900이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#6','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'mc','auto','과일 가게에서 귤 214개를 한 상자에 10개씩 담아 팔려고 해요. 상자에 담긴 귤을 한 상자에 3000원씩 받고 모두 판다면 얼마를 받을 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],true,'{"seq":6,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"과일 가게에서 귤 214개를 한 상자에 10개씩 담아 팔려고 해요. 상자에 담긴 귤을 한 상자에 3000원씩 받고 모두 판다면 얼마를 받을 수 있나요?","options":[{"t":"63000원","correct":true},{"t":"66000원","mis":"M5-2-u1-X13"},{"t":"64200원","mis":"M5-2-u1-X14"},{"t":"60000원","mis":"M5-2-u1-X09"}],"explanation":["10개씩 담으니 214를 버림하여 십의 자리까지 — 210개, 21상자예요.","남는 4개는 상자에 담을 수 없어요.","3000 × 21 = 63000(원)이에요."],"variant_rule":{"alt":[{"stem":"밭에서 캔 감자 658 kg을 한 상자에 10 kg씩 담아 팔려고 해요. 상자에 담아 팔 수 있는 감자는 최대 몇 kg인가요?","options":[{"t":"650 kg","correct":true},{"t":"660 kg","mis":"M5-2-u1-X13"},{"t":"658 kg","mis":"M5-2-u1-X14"},{"t":"600 kg","mis":"M5-2-u1-X09"}],"explanation":["10 kg씩 담으니 남는 8 kg은 상자에 담을 수 없어요.","658을 버림하여 십의 자리까지 나타내요.","그래서 최대 650 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#7','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',3,'ox','auto','21076을 버림하여 천의 자리까지 나타내면 20000이에요.',ARRAY['M5-2-u1-X09']::text[],false,'{"seq":7,"concept":"M5-2-u1-C5","difficulty":3,"kind":"ox","stem":"21076을 버림하여 천의 자리까지 나타내면 20000이에요.","answer":"X","reason_options":[{"t":"천의 자리 숫자 1은 남기고 그 아래만 버려 21000이라서","correct":true},{"t":"버림은 맨 앞자리 아래를 모두 버려서","mis":"M5-2-u1-X09"}],"mis":"M5-2-u1-X09","explanation":["버림은 구하려는 자리의 아래 수를 버려요.","21076의 천의 자리 숫자는 1 — 그대로 남겨요.","그래서 21000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#8','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',4,'essay','teacher','세계 식량의 날 행사에서 곤충으로 만든 과자 657개를 10개씩 또는 100개씩 포장하려고 해요. 각각 최대 몇 개까지 포장할 수 있는지 쓰고, 660개나 700개라고 하면 안 되는 까닭을 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C5","difficulty":4,"kind":"essay","stem":"세계 식량의 날 행사에서 곤충으로 만든 과자 657개를 10개씩 또는 100개씩 포장하려고 해요. 각각 최대 몇 개까지 포장할 수 있는지 쓰고, 660개나 700개라고 하면 안 되는 까닭을 설명하세요.","answer_guide":{"answer":"예: 10개씩은 650개, 100개씩은 600개까지 포장할 수 있다. 66묶음(660개)이나 7묶음(700개)으로 포장하려면 과자가 657개보다 많이 있어야 하므로 모자라고, 남는 과자는 포장할 수 없어 버림한다.","scoring_points":["650개와 600개를 바르게 구했는가","660개·700개는 과자가 모자라 포장할 수 없다고 썼는가","남는 것은 쓸 수 없으니 버림한다는 까닭을 썼는가"]},"explanation":["10개씩: 66묶음은 660개가 필요해 모자라니 650개예요.","100개씩: 7묶음은 700개가 필요해 모자라니 600개예요.","남는 과자는 포장할 수 없으니 버림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#9','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',4,'mc','auto','다음 중 버림을 이용하여 어림해야 하는 상황은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":9,"concept":"M5-2-u1-C5","difficulty":4,"kind":"mc","stem":"다음 중 버림을 이용하여 어림해야 하는 상황은 어느 것인가요?","options":[{"t":"단감 4953개를 한 상자에 100개씩 포장하기","correct":true},{"t":"학생 543명에게 나누어 줄 가방을 10개 묶음으로 사기","mis":"M5-2-u1-X13"},{"t":"도서관에서 1학기 동안 빌려준 책 5813권을 몇 권쯤이라고 말하기","mis":"M5-2-u1-X13"},{"t":"찰흙 170 g을 100 g씩 포장된 것으로 사기","mis":"M5-2-u1-X13"}],"explanation":["포장하고 남는 단감은 상자에 담아 팔 수 없어요 — 버림이에요.","가방·찰흙은 모자라면 안 되니 올림이에요.","책 수를 몇 권쯤이라고 말할 때는 가까운 수 — 반올림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L06_challenge#10','math',5,2,'u1','L06','tb_g5_2_math_u1_L06_challenge','lesson_challenge','M5-2-u1-C5',4,'essay','teacher','생활에서 버림이 쓰이는 경우를 한 가지 쓰고, 왜 올림이나 반올림이 아니라 버림을 써야 하는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C5","difficulty":4,"kind":"essay","stem":"생활에서 버림이 쓰이는 경우를 한 가지 쓰고, 왜 올림이나 반올림이 아니라 버림을 써야 하는지 설명하세요.","answer_guide":{"answer":"예: 동전을 1000원짜리 지폐로 바꿀 때 버림을 쓴다. 1000원이 안 되는 남는 동전은 지폐로 바꿀 수 없으므로 아래 수를 버려야 하고, 올림하면 가진 돈보다 많아진다.","scoring_points":["버림이 쓰이는 상황(동전을 지폐로 바꾸기·묶음으로 포장하기·농작물을 상자에 담아 팔기 등)을 썼는가","남는 것을 쓸 수 없다는 까닭을 썼는가","올림·반올림을 쓰면 안 되는 까닭을 밝혔는가"]},"explanation":["동전을 지폐로 바꾸거나 묶음으로 포장할 때 버림을 써요.","남는 양은 지폐나 묶음이 되지 못해요.","올림하면 가진 것보다 많아져서 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#1','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'mc','auto','우리 학교 도서관에서 지난 1학기 동안 빌려준 책의 수가 5813권이에요. 5800과 5900 중에서 5813은 어느 쪽에 더 가까운가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16','M5-2-u1-X11']::text[],true,'{"seq":1,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"우리 학교 도서관에서 지난 1학기 동안 빌려준 책의 수가 5813권이에요. 5800과 5900 중에서 5813은 어느 쪽에 더 가까운가요?","options":[{"t":"5800","correct":true},{"t":"5900","mis":"M5-2-u1-X08"},{"t":"5850","mis":"M5-2-u1-X16"},{"t":"둘 다 같다","mis":"M5-2-u1-X11"}],"explanation":["5800과 5900의 한가운데는 5850이에요.","5813은 5850보다 작아서 5800 쪽에 있어요.","그래서 약 5800권이라고 할 수 있어요."],"variant_rule":{"alt":[{"stem":"우리 학교 도서관에서 지난 1학기 동안 빌려준 책의 수가 5813권이에요. 5000과 6000 중에서 5813은 어느 쪽에 더 가까운가요?","options":[{"t":"6000","correct":true},{"t":"5000","mis":"M5-2-u1-X08"},{"t":"5500","mis":"M5-2-u1-X16"},{"t":"둘 다 같다","mis":"M5-2-u1-X11"}],"explanation":["5000과 6000의 한가운데는 5500이에요.","5813은 5500보다 커서 6000 쪽에 있어요.","그래서 약 6000권이라고 할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#2','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'mc','auto','1.573을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":2,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"1.573을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.57","correct":true},{"t":"1.58","mis":"M5-2-u1-X08"},{"t":"1.6","mis":"M5-2-u1-X09"},{"t":"1.59","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 둘째 자리 바로 아래 숫자가 3이라 버려요.","1.573 → 1.57이에요."],"variant_rule":{"alt":[{"stem":"1.573을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"1.6","correct":true},{"t":"1.5","mis":"M5-2-u1-X08"},{"t":"1.57","mis":"M5-2-u1-X09"},{"t":"2","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 7이라 올려요.","1.573 → 1.6이에요."]},{"stem":"1.573을 반올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"2","correct":true},{"t":"1","mis":"M5-2-u1-X08"},{"t":"1.6","mis":"M5-2-u1-X09"},{"t":"3","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","일의 자리 바로 아래 숫자가 5라 올려요.","1.573 → 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#3','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'sa','auto','4752를 반올림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C6","difficulty":1,"kind":"sa","stem":"4752를 반올림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["4750"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","십의 자리 바로 아래 숫자가 2라 버려요.","4752 → 4750이에요."],"variant_rule":{"alt":[{"stem":"4752를 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["4800"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 5라 올려요.","4752 → 4800이에요."]},{"stem":"4752를 반올림하여 천의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["5000"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 7이라 올려요.","4752 → 5000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#4','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',1,'mc','auto','구하려는 자리 바로 아래 자리의 숫자가 0, 1, 2, 3, 4면 버리고, 5, 6, 7, 8, 9면 올려서 나타내는 방법을 무엇이라고 하나요?',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],false,'{"seq":4,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"구하려는 자리 바로 아래 자리의 숫자가 0, 1, 2, 3, 4면 버리고, 5, 6, 7, 8, 9면 올려서 나타내는 방법을 무엇이라고 하나요?","options":[{"t":"반올림","correct":true},{"t":"올림","mis":"M5-2-u1-X08"},{"t":"버림","mis":"M5-2-u1-X08"},{"t":"수의 범위","mis":"M5-2-u1-X17"}],"explanation":["바로 아래 한 자리의 숫자를 보고 버리거나 올리면 반올림이에요.","5813을 반올림하여 백의 자리까지 나타내면 5800이에요.","반올림은 원래 수에 가깝게 어림하는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#5','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'mc','auto','3.406을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16']::text[],true,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"3.406을 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.41","correct":true},{"t":"3.40","mis":"M5-2-u1-X08"},{"t":"3.42","mis":"M5-2-u1-X16"},{"t":"3.43","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 둘째 자리 바로 아래 숫자가 6이라 올려요.","3.406 → 3.41이에요."],"variant_rule":{"alt":[{"stem":"3.406을 반올림하여 소수 첫째 자리까지 나타내면 얼마인가요?","options":[{"t":"3.4","correct":true},{"t":"3.5","mis":"M5-2-u1-X08"},{"t":"3.41","mis":"M5-2-u1-X09"},{"t":"3","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 0이라 버려요.","3.406 → 3.4예요."]},{"stem":"3.406을 반올림하여 일의 자리까지 나타내면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M5-2-u1-X08"},{"t":"3.4","mis":"M5-2-u1-X09"},{"t":"5","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","일의 자리 바로 아래 숫자가 4라 버려요.","3.406 → 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#6','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'match','auto','2.148을 반올림하여 주어진 자리까지 나타낸 수를 바르게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"M5-2-u1-C6","difficulty":2,"kind":"match","stem":"2.148을 반올림하여 주어진 자리까지 나타낸 수를 바르게 이으세요.","pairs":[{"l":"소수 둘째 자리까지","r":"2.15"},{"l":"소수 첫째 자리까지","r":"2.1"},{"l":"일의 자리까지","r":"2"}],"mis":"M5-2-u1-X09","explanation":["소수 둘째 자리까지: 소수 셋째 자리 숫자 8을 올려 2.15예요.","소수 첫째 자리까지: 소수 둘째 자리 숫자 4를 버려 2.1이에요.","일의 자리까지: 소수 첫째 자리 숫자 1을 버려 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#7','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'sa','auto','어제 하루 동안 박물관에 방문한 관람객은 8542명이에요. 관람객 수를 반올림하여 천의 자리까지 나타내면 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"어제 하루 동안 박물관에 방문한 관람객은 8542명이에요. 관람객 수를 반올림하여 천의 자리까지 나타내면 몇 명인가요? 숫자로 쓰세요.","answer":["9000"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 5라 올려요.","8542 → 9000이에요."],"variant_rule":{"alt":[{"stem":"384를 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 8이라 올려요.","384 → 400이에요."]},{"stem":"671을 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["700"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 7이라 올려요.","671 → 700이에요."]},{"stem":"915를 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 1이라 버려요.","915 → 900이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#8','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'mc','auto','반딧불 축제에 찾아온 방문객이 17058명이에요. 방문객 수를 반올림하여 만의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":8,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"반딧불 축제에 찾아온 방문객이 17058명이에요. 방문객 수를 반올림하여 만의 자리까지 나타내면 얼마인가요?","options":[{"t":"20000","correct":true},{"t":"10000","mis":"M5-2-u1-X08"},{"t":"17000","mis":"M5-2-u1-X09"},{"t":"17100","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 7이라 올려요.","17058 → 20000이에요."],"variant_rule":{"alt":[{"stem":"반딧불 축제에 찾아온 방문객이 17058명이에요. 방문객 수를 반올림하여 천의 자리까지 나타내면 얼마인가요?","options":[{"t":"17000","correct":true},{"t":"18000","mis":"M5-2-u1-X08"},{"t":"17100","mis":"M5-2-u1-X09"},{"t":"17060","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 0이라 버려요.","17058 → 17000이에요."]},{"stem":"반딧불 축제에 찾아온 방문객이 17058명이에요. 방문객 수를 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"17100","correct":true},{"t":"17000","mis":"M5-2-u1-X08"},{"t":"17060","mis":"M5-2-u1-X09"},{"t":"171","mis":"M5-2-u1-X12"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 5라 올려요.","17058 → 17100이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#9','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',2,'ox','auto','반올림할 때 바로 아래 자리의 숫자가 5이면 버려요.',ARRAY['M5-2-u1-X11']::text[],false,'{"seq":9,"concept":"M5-2-u1-C6","difficulty":2,"kind":"ox","stem":"반올림할 때 바로 아래 자리의 숫자가 5이면 버려요.","answer":"X","reason_options":[{"t":"0부터 9까지 10개 숫자 중 0~4 다섯 개는 버리고 5~9 다섯 개는 올려서","correct":true},{"t":"5는 0과 10의 한가운데 수라서","mis":"M5-2-u1-X11"}],"mis":"M5-2-u1-X11","explanation":["바로 아래 자리에 올 수 있는 숫자는 0부터 9까지 10개예요.","5는 한가운데가 아니라 오른쪽에 치우친 숫자예요.","그래서 0~4는 버리고 5~9는 올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_basic#10','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_basic','lesson_basic','M5-2-u1-C6',3,'mc','auto','㉠ 8563 ㉡ 9427 ㉢ 8951 ㉣ 8379 중에서 반올림하여 천의 자리까지 나타낸 수가 다른 것은 어느 것인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X08']::text[],false,'{"seq":10,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"㉠ 8563 ㉡ 9427 ㉢ 8951 ㉣ 8379 중에서 반올림하여 천의 자리까지 나타낸 수가 다른 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉡","mis":"M5-2-u1-X16"},{"t":"㉢","mis":"M5-2-u1-X08"},{"t":"㉠","mis":"M5-2-u1-X08"}],"explanation":["반올림하여 천의 자리까지 나타내면 9000, 9000, 9000, 8000이에요.","8379는 백의 자리 숫자가 3이라 버려서 8000이에요.","그래서 다른 것은 ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#1','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',2,'mc','auto','126□를 반올림하여 십의 자리까지 나타낸 수가 1270일 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X11','M5-2-u1-X15','M5-2-u1-X08']::text[],false,'{"seq":1,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"126□를 반올림하여 십의 자리까지 나타낸 수가 1270일 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M5-2-u1-X11"},{"t":"0, 1, 2, 3, 4","mis":"M5-2-u1-X15"},{"t":"1, 2, 3, 4, 5, 6, 7, 8, 9","mis":"M5-2-u1-X08"}],"explanation":["126□가 1270이 되려면 일의 자리 숫자를 올려야 해요.","올리는 숫자는 5, 6, 7, 8, 9예요.","0~4를 넣으면 버려서 1260이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#2','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',2,'sa','auto','반올림하여 십의 자리까지 나타내면 50이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"반올림하여 십의 자리까지 나타내면 50이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["일의 자리에서 올려 50이 되는 수는 45, 46, 47, 48, 49예요.","버려서 50이 되는 수는 50, 51, 52, 53, 54예요.","모두 10개예요."],"variant_rule":{"alt":[{"stem":"반올림하여 십의 자리까지 나타내면 130이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["올려서 130이 되는 수는 125부터 129까지예요.","버려서 130이 되는 수는 130부터 134까지예요.","모두 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#3','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'sa','auto','반올림하여 백의 자리까지 나타내면 3200이 되는 가장 큰 자연수와 가장 작은 자연수의 차를 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M5-2-u1-C6","difficulty":3,"kind":"sa","stem":"반올림하여 백의 자리까지 나타내면 3200이 되는 가장 큰 자연수와 가장 작은 자연수의 차를 구하세요. 숫자로 쓰세요.","answer":["99"],"explanation":["가장 작은 자연수는 3150 — 십의 자리 5를 올려 3200이에요.","가장 큰 자연수는 3249 — 3250은 3300이 되어 빠져요.","3249 − 3150 = 99예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#4','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'mc','auto','수를 반올림하여 백의 자리까지 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":4,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"수를 반올림하여 백의 자리까지 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3676 → 3700","correct":true},{"t":"4573 → 4500","mis":"M5-2-u1-X08"},{"t":"4573 → 5000","mis":"M5-2-u1-X09"},{"t":"3676 → 3600","mis":"M5-2-u1-X08"}],"explanation":["반올림하여 백의 자리까지 나타낼 때는 십의 자리 숫자를 봐요.","3676은 7이라 올려 3700, 4573도 7이라 올려 4600이에요.","4573 → 4500은 올려야 할 것을 버린 잘못이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#5','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'mc','auto','5.49를 반올림하여 일의 자리까지 나타낸 수와 소수 첫째 자리까지 나타낸 수 중에서 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u1-X10','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"5.49를 반올림하여 일의 자리까지 나타낸 수와 소수 첫째 자리까지 나타낸 수 중에서 더 큰 것은 어느 것인가요?","options":[{"t":"소수 첫째 자리까지 나타낸 수 5.5","correct":true},{"t":"일의 자리까지 나타낸 수 6","mis":"M5-2-u1-X10"},{"t":"둘이 같다 — 모두 5.5","mis":"M5-2-u1-X09"},{"t":"일의 자리까지 나타낸 수 5","mis":"M5-2-u1-X16"}],"explanation":["일의 자리까지: 소수 첫째 자리 숫자 4를 버려 5예요.","소수 첫째 자리까지: 소수 둘째 자리 숫자 9를 올려 5.5예요.","5.5를 다시 반올림해 6으로 하면 안 돼요 — 더 큰 것은 5.5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#6','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'mc','auto','4.67을 올림, 버림, 반올림하여 소수 첫째 자리까지 차례로 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X11','M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":6,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"4.67을 올림, 버림, 반올림하여 소수 첫째 자리까지 차례로 나타낸 것은 어느 것인가요?","options":[{"t":"4.7, 4.6, 4.7","correct":true},{"t":"4.7, 4.6, 4.6","mis":"M5-2-u1-X11"},{"t":"4.7, 4.7, 4.7","mis":"M5-2-u1-X08"},{"t":"5, 4, 5","mis":"M5-2-u1-X09"}],"explanation":["올림: 소수 둘째 자리 7을 올려 4.7이에요.","버림: 7을 버려 4.6이에요.","반올림: 7은 5~9라 올려 4.7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#7','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',3,'match','auto','왼쪽 수를 반올림하여 십의 자리까지 나타낸 수를 오른쪽에서 찾아 이으세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u1-C6","difficulty":3,"kind":"match","stem":"왼쪽 수를 반올림하여 십의 자리까지 나타낸 수를 오른쪽에서 찾아 이으세요.","pairs":[{"l":"283","r":"280"},{"l":"265","r":"270"}],"mis":"M5-2-u1-X11","explanation":["283은 일의 자리 숫자 3을 버려 280이에요.","265는 일의 자리 숫자 5를 올려 270이에요.","290은 어느 수와도 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#8','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',4,'mc','auto','㉠ 9715를 올림하여 백의 자리까지 나타낸 수와 ㉡ 9769를 반올림하여 십의 자리까지 나타낸 수의 합을 구한 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":8,"concept":"M5-2-u1-C6","difficulty":4,"kind":"mc","stem":"㉠ 9715를 올림하여 백의 자리까지 나타낸 수와 ㉡ 9769를 반올림하여 십의 자리까지 나타낸 수의 합을 구한 것은 어느 것인가요?","options":[{"t":"19570","correct":true},{"t":"19500","mis":"M5-2-u1-X08"},{"t":"19560","mis":"M5-2-u1-X08"},{"t":"19670","mis":"M5-2-u1-X09"}],"explanation":["㉠ 9715를 올림하여 백의 자리까지 나타내면 9800이에요.","㉡ 9769를 반올림하여 십의 자리까지 나타내면 9770이에요.","9800 + 9770 = 19570이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#9','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',4,'essay','teacher','우리 학교 도서관에서 지난 1학기 동안 빌려준 책의 수가 5813권이에요. 이 수를 약 5800권이라고도 하고 약 6000권이라고도 할 수 있어요. 각각 어떻게 어림한 것인지 수직선에서 가까운 쪽을 찾아 설명하세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C6","difficulty":4,"kind":"essay","stem":"우리 학교 도서관에서 지난 1학기 동안 빌려준 책의 수가 5813권이에요. 이 수를 약 5800권이라고도 하고 약 6000권이라고도 할 수 있어요. 각각 어떻게 어림한 것인지 수직선에서 가까운 쪽을 찾아 설명하세요.","answer_guide":{"answer":"예: 5800과 5900 사이에서 5813은 한가운데 5850보다 작아 5800에 더 가까우므로 약 5800권(반올림하여 백의 자리까지)이다. 5000과 6000 사이에서는 5500보다 커서 6000에 더 가까우므로 약 6000권(반올림하여 천의 자리까지)이다.","scoring_points":["5800과 5900 중 5800에 더 가깝다고 썼는가","5000과 6000 중 6000에 더 가깝다고 썼는가","원래 수에 가까운 쪽으로 어림하는 반올림임을 밝혔는가"]},"explanation":["5813은 5800과 5900 중 5800에 더 가까워요.","5000과 6000 중에서는 6000에 더 가까워요.","원래 수에 가깝게 어림하는 방법이 반올림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L07_challenge#10','math',5,2,'u1','L07','tb_g5_2_math_u1_L07_challenge','lesson_challenge','M5-2-u1-C6',4,'mc','auto','백두산의 높이는 2744 m예요. 백두산의 높이를 반올림하여 백의 자리와 천의 자리까지 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":10,"concept":"M5-2-u1-C6","difficulty":4,"kind":"mc","stem":"백두산의 높이는 2744 m예요. 백두산의 높이를 반올림하여 백의 자리와 천의 자리까지 나타낸 것은 어느 것인가요?","options":[{"t":"2700 m, 3000 m","correct":true},{"t":"2800 m, 3000 m","mis":"M5-2-u1-X08"},{"t":"2700 m, 2000 m","mis":"M5-2-u1-X08"},{"t":"2740 m, 2700 m","mis":"M5-2-u1-X09"}],"explanation":["백의 자리까지: 십의 자리 숫자 4를 버려 2700 m예요.","천의 자리까지: 백의 자리 숫자 7을 올려 3000 m예요.","그래서 2700 m, 3000 m예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#1','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','재생 천으로 만들어진 예쁜 필통의 가격은 11200원이에요. 필통값을 지폐로 내려고 해요. 올림, 버림, 반올림 중에서 어떤 방법으로 어림하면 좋을까요?',ARRAY['M5-2-u1-X13']::text[],true,'{"seq":1,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"재생 천으로 만들어진 예쁜 필통의 가격은 11200원이에요. 필통값을 지폐로 내려고 해요. 올림, 버림, 반올림 중에서 어떤 방법으로 어림하면 좋을까요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"어림하지 않는다","mis":"M5-2-u1-X13"}],"explanation":["지폐로 낼 때 모자라면 필통을 살 수 없어요.","필통값보다 많이 내야 하니 올림해요.","올림하면 원래 수보다 크거나 같아져요."],"variant_rule":{"alt":[{"stem":"저금통에 모은 동전이 모두 58600원이에요. 동전을 지폐로 바꾸려고 해요. 올림, 버림, 반올림 중에서 어떤 방법으로 어림하면 좋을까요?","options":[{"t":"버림","correct":true},{"t":"올림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"어림하지 않는다","mis":"M5-2-u1-X13"}],"explanation":["지폐 한 장이 안 되는 남는 동전은 바꿀 수 없어요.","모은 돈보다 많이 바꿀 수는 없으니 버림해요.","버림하면 원래 수보다 작거나 같아져요."]},{"stem":"조사한 도시별 인구를 그래프로 나타내려고 해요. 실제 인구에 가깝게 어림하려면 올림, 버림, 반올림 중에서 어떤 방법으로 어림하면 좋을까요?","options":[{"t":"반올림","correct":true},{"t":"올림","mis":"M5-2-u1-X13"},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"어림하지 않는다","mis":"M5-2-u1-X13"}],"explanation":["그래프에는 실제 수와 차이가 작은 수가 좋아요.","원래 수에 가장 가깝게 어림하는 방법은 반올림이에요.","그래서 반올림해요."],"asset":{"type":"passage","lines":["도시별 인구(2025년 3월)","부산광역시 3259219명 · 대전광역시 1439482명","인천광역시 3031361명 · 광주광역시 1402478명"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#2','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','재생 천으로 만들어진 예쁜 필통의 가격은 11200원이에요. 1000원짜리 지폐와 10000원짜리 지폐를 같이 낸다면 최소 얼마를 내야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X14']::text[],true,'{"seq":2,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"재생 천으로 만들어진 예쁜 필통의 가격은 11200원이에요. 1000원짜리 지폐와 10000원짜리 지폐를 같이 낸다면 최소 얼마를 내야 하나요?","options":[{"t":"12000원","correct":true},{"t":"11000원","mis":"M5-2-u1-X13"},{"t":"20000원","mis":"M5-2-u1-X09"},{"t":"11200원","mis":"M5-2-u1-X14"}],"explanation":["1000원짜리 지폐까지 쓸 수 있으니 천의 자리까지 어림해요.","모자라면 안 되니 11200을 올림하여 천의 자리까지 — 12000이에요.","그래서 최소 12000원을 내요."],"variant_rule":{"alt":[{"stem":"재생 천으로 만들어진 예쁜 필통의 가격은 11200원이에요. 10000원짜리 지폐로만 낸다면 최소 얼마를 내야 하나요?","options":[{"t":"20000원","correct":true},{"t":"10000원","mis":"M5-2-u1-X13"},{"t":"12000원","mis":"M5-2-u1-X09"},{"t":"11200원","mis":"M5-2-u1-X14"}],"explanation":["10000원짜리 지폐로만 내니 만의 자리까지 어림해요.","모자라면 안 되니 11200을 올림하여 만의 자리까지 — 20000이에요.","그래서 최소 20000원을 내요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#3','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','저금통에 모은 동전이 모두 58600원이에요. 이 동전을 1000원짜리 지폐로 바꾸면 최대 얼마까지 바꿀 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09','M5-2-u1-X14']::text[],true,'{"seq":3,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"저금통에 모은 동전이 모두 58600원이에요. 이 동전을 1000원짜리 지폐로 바꾸면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"58000원","correct":true},{"t":"59000원","mis":"M5-2-u1-X13"},{"t":"50000원","mis":"M5-2-u1-X09"},{"t":"58600원","mis":"M5-2-u1-X14"}],"explanation":["1000원짜리 지폐로 바꾸니 천의 자리까지 어림해요.","남는 600원은 지폐로 못 바꾸니 버림해요.","58600을 버림하여 천의 자리까지 — 58000원이에요."],"variant_rule":{"alt":[{"stem":"저금통에 모은 동전이 모두 58600원이에요. 이 동전을 10000원짜리 지폐로만 바꾸면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"50000원","correct":true},{"t":"60000원","mis":"M5-2-u1-X13"},{"t":"58000원","mis":"M5-2-u1-X09"},{"t":"58600원","mis":"M5-2-u1-X14"}],"explanation":["10000원짜리 지폐로만 바꾸니 만의 자리까지 어림해요.","남는 8600원은 바꿀 수 없으니 버림해요.","58600을 버림하여 만의 자리까지 — 50000원이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#4','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',1,'mc','auto','저울로 잰 포도의 무게는 0.758 kg이에요. 포도의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"저울로 잰 포도의 무게는 0.758 kg이에요. 포도의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"0.8 kg","correct":true},{"t":"0.7 kg","mis":"M5-2-u1-X08"},{"t":"0.76 kg","mis":"M5-2-u1-X09"},{"t":"1 kg","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 5라 올려요.","0.758 → 0.8이에요."],"variant_rule":{"alt":[{"stem":"저울로 잰 수박의 무게는 10.26 kg이에요. 수박의 무게를 버림하여 일의 자리까지 나타내면 몇 kg인가요?","options":[{"t":"10 kg","correct":true},{"t":"11 kg","mis":"M5-2-u1-X08"},{"t":"10.2 kg","mis":"M5-2-u1-X09"},{"t":"12 kg","mis":"M5-2-u1-X16"}],"explanation":["버림은 일의 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","10.26 → 10이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#5','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'mc','auto','부산광역시의 인구를 반올림하여 만의 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":5,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"부산광역시의 인구를 반올림하여 만의 자리까지 나타내면 얼마인가요?","options":[{"t":"3260000","correct":true},{"t":"3250000","mis":"M5-2-u1-X08"},{"t":"3259000","mis":"M5-2-u1-X09"},{"t":"3300000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 9라 올려요.","3259219 → 3260000이에요."],"asset":{"type":"passage","lines":["도시별 인구(2025년 3월)","부산광역시 3259219명 · 대전광역시 1439482명","인천광역시 3031361명 · 광주광역시 1402478명"]},"variant_rule":{"alt":[{"stem":"대전광역시의 인구를 반올림하여 만의 자리까지 나타내면 얼마인가요?","options":[{"t":"1440000","correct":true},{"t":"1430000","mis":"M5-2-u1-X08"},{"t":"1439000","mis":"M5-2-u1-X09"},{"t":"1400000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 9라 올려요.","1439482 → 1440000이에요."],"asset":{"type":"passage","lines":["도시별 인구(2025년 3월)","부산광역시 3259219명 · 대전광역시 1439482명","인천광역시 3031361명 · 광주광역시 1402478명"]}},{"stem":"인천광역시의 인구를 반올림하여 만의 자리까지 나타내면 얼마인가요?","options":[{"t":"3030000","correct":true},{"t":"3040000","mis":"M5-2-u1-X08"},{"t":"3031000","mis":"M5-2-u1-X09"},{"t":"3000000","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 1이라 버려요.","3031361 → 3030000이에요."],"asset":{"type":"passage","lines":["도시별 인구(2025년 3월)","부산광역시 3259219명 · 대전광역시 1439482명","인천광역시 3031361명 · 광주광역시 1402478명"]}},{"stem":"광주광역시의 인구를 반올림하여 만의 자리까지 나타내면 얼마인가요?","options":[{"t":"1400000","correct":true},{"t":"1410000","mis":"M5-2-u1-X08"},{"t":"1402000","mis":"M5-2-u1-X09"},{"t":"1402500","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","만의 자리 바로 아래 숫자가 2라 버려요.","1402478 → 1400000이에요."],"asset":{"type":"passage","lines":["도시별 인구(2025년 3월)","부산광역시 3259219명 · 대전광역시 1439482명","인천광역시 3031361명 · 광주광역시 1402478명"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#6','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'mc','auto','국립 공원의 실제 넓이를 일의 자리까지 어림한 값이에요. 올림, 버림, 반올림 중에서 어떤 방법으로 어림했나요?',ARRAY['M5-2-u1-X18','M5-2-u1-X08']::text[],false,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"국립 공원의 실제 넓이를 일의 자리까지 어림한 값이에요. 올림, 버림, 반올림 중에서 어떤 방법으로 어림했나요?","options":[{"t":"반올림","correct":true},{"t":"버림","mis":"M5-2-u1-X18"},{"t":"올림","mis":"M5-2-u1-X08"},{"t":"셋이 모두 다른 방법","mis":"M5-2-u1-X18"}],"explanation":["2276.209 → 2276은 버림·반올림 둘 다 될 수 있어요.","228.919 → 229, 485.647 → 486은 버림이 아니에요(버림이면 228, 485).","셋 모두 맞는 방법은 반올림이에요."],"asset":{"type":"passage","lines":["국립 공원의 넓이와 어림한 값(km²)","다도해해상 2276.209 → 2276","덕유산 228.919 → 229","지리산 485.647 → 486"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#7','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'mc','auto','밭에서 캔 감자 658 kg을 한 상자에 10 kg씩 담아 팔려고 해요. 상자에 담아 팔 수 있는 감자는 최대 몇 kg인지 알아볼 때 알맞은 어림 방법과 답은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09']::text[],false,'{"seq":7,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"밭에서 캔 감자 658 kg을 한 상자에 10 kg씩 담아 팔려고 해요. 상자에 담아 팔 수 있는 감자는 최대 몇 kg인지 알아볼 때 알맞은 어림 방법과 답은 어느 것인가요?","options":[{"t":"버림, 650 kg","correct":true},{"t":"올림, 660 kg","mis":"M5-2-u1-X13"},{"t":"반올림, 660 kg","mis":"M5-2-u1-X13"},{"t":"버림, 600 kg","mis":"M5-2-u1-X09"}],"explanation":["10 kg이 안 되는 남는 감자는 상자에 담아 팔 수 없어요.","그래서 버림하여 십의 자리까지 나타내요.","658 → 650 — 최대 650 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#8','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'mc','auto','은호네 반 학생 32명에게 음료수를 한 개씩 나누어 주려고 해요. 음료수를 10개씩 묶음으로만 판다면, 은호가 말한 「음료수는 반올림하여 30개를 사야 해요.」를 바르게 고친 것은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14']::text[],false,'{"seq":8,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"은호네 반 학생 32명에게 음료수를 한 개씩 나누어 주려고 해요. 음료수를 10개씩 묶음으로만 판다면, 은호가 말한 「음료수는 반올림하여 30개를 사야 해요.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"음료수는 올림하여 40개를 사야 해요.","correct":true},{"t":"음료수는 버림하여 30개를 사야 해요.","mis":"M5-2-u1-X13"},{"t":"음료수는 반올림하여 40개를 사야 해요.","mis":"M5-2-u1-X13"},{"t":"음료수는 올림하여 32개를 사야 해요.","mis":"M5-2-u1-X14"}],"explanation":["필요한 음료수는 32개이고 10개씩 묶음으로만 팔아요.","30개를 사면 2개가 모자라니 반올림이나 버림은 안 돼요.","올림하여 40개를 사야 해요 — 「올림」이라는 말이 꼭 들어가야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#9','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',2,'mc','auto','1200원짜리 음료수 3개를 사려고 해요. 1000원짜리 지폐로만 내려면 최소 얼마를 내야 하는지 알아볼 때 알맞은 어림 방법과 답은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14']::text[],false,'{"seq":9,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"1200원짜리 음료수 3개를 사려고 해요. 1000원짜리 지폐로만 내려면 최소 얼마를 내야 하는지 알아볼 때 알맞은 어림 방법과 답은 어느 것인가요?","options":[{"t":"올림, 4000원","correct":true},{"t":"버림, 3000원","mis":"M5-2-u1-X13"},{"t":"반올림, 4000원","mis":"M5-2-u1-X13"},{"t":"올림, 3600원","mis":"M5-2-u1-X14"}],"explanation":["음료수 값은 1200 × 3 = 3600(원)이에요.","모자라면 안 되니 3600을 올림하여 천의 자리까지 나타내요.","그래서 올림, 4000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_basic#10','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_basic','lesson_basic','M5-2-u1-C7',3,'match','auto','상황에 알맞은 어림 방법을 이으세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C7","difficulty":3,"kind":"match","stem":"상황에 알맞은 어림 방법을 이으세요.","pairs":[{"l":"필통값 11200원을 지폐로 내기","r":"올림"},{"l":"동전 58600원을 지폐로 바꾸기","r":"버림"},{"l":"도시별 인구를 그래프로 나타내기","r":"반올림"}],"mis":"M5-2-u1-X13","explanation":["모자라면 안 되는 필통값은 올림이에요.","남는 동전을 바꿀 수 없는 경우는 버림이에요.","실제 수와 차이를 작게 나타내는 그래프는 반올림이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#1','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C6',2,'mc','auto','4.739를 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":1,"concept":"M5-2-u1-C6","difficulty":2,"kind":"mc","stem":"4.739를 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.74","correct":true},{"t":"4.73","mis":"M5-2-u1-X08"},{"t":"4.7","mis":"M5-2-u1-X09"},{"t":"4.75","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 둘째 자리 바로 아래 숫자가 9라 올려요.","4.739 → 4.74예요."],"variant_rule":{"alt":[{"stem":"384를 반올림하여 백의 자리까지 나타내면 얼마인가요?","options":[{"t":"400","correct":true},{"t":"300","mis":"M5-2-u1-X08"},{"t":"380","mis":"M5-2-u1-X09"},{"t":"4","mis":"M5-2-u1-X12"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 8이라 올려요.","384 → 400이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#2','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',2,'mc','auto','준하는 16400원짜리 과학책을 한 권 사고 1000원짜리 지폐로 책값을 내려고 해요. 알맞은 어림 방법과 최소로 내야 하는 돈을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09']::text[],false,'{"seq":2,"concept":"M5-2-u1-C7","difficulty":2,"kind":"mc","stem":"준하는 16400원짜리 과학책을 한 권 사고 1000원짜리 지폐로 책값을 내려고 해요. 알맞은 어림 방법과 최소로 내야 하는 돈을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"올림, 17000원","correct":true},{"t":"반올림, 16000원","mis":"M5-2-u1-X13"},{"t":"버림, 16000원","mis":"M5-2-u1-X13"},{"t":"올림, 20000원","mis":"M5-2-u1-X09"}],"explanation":["책값보다 적게 내면 책을 살 수 없으니 올림해요.","1000원짜리 지폐로 내니 천의 자리까지 어림해요.","16400을 올림하여 천의 자리까지 — 17000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#3','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'mc','auto','다도해해상국립공원의 넓이 2276.209 km²를 어림한 값 2276 km²만 보고는 어떤 방법으로 어림했는지 정할 수 없어요. 그 까닭은 어느 것인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X08','M5-2-u1-X18']::text[],false,'{"seq":3,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"다도해해상국립공원의 넓이 2276.209 km²를 어림한 값 2276 km²만 보고는 어떤 방법으로 어림했는지 정할 수 없어요. 그 까닭은 어느 것인가요?","options":[{"t":"버림한 수와 반올림한 수가 모두 2276이라서","correct":true},{"t":"올림한 수와 반올림한 수가 모두 2276이라서","mis":"M5-2-u1-X16"},{"t":"올림하면 2276이 되어서","mis":"M5-2-u1-X08"},{"t":"어림한 값은 늘 버림이라서","mis":"M5-2-u1-X18"}],"explanation":["2276.209를 올림하면 2277, 버림하면 2276, 반올림하면 2276이에요.","버림과 반올림의 결과가 같아 하나만 보고는 가릴 수 없어요.","다른 공원의 값까지 함께 견주어야 방법을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#4','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'mc','auto','필통값을 지폐로 낼 때와 모은 동전을 지폐로 바꿀 때는 모두 돈을 다루는데 어림 방법이 달라요. 그 까닭은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"필통값을 지폐로 낼 때와 모은 동전을 지폐로 바꿀 때는 모두 돈을 다루는데 어림 방법이 달라요. 그 까닭은 어느 것인가요?","options":[{"t":"필통값은 모자라면 안 되고, 동전은 남는 돈을 지폐로 바꿀 수 없어서","correct":true},{"t":"필통값은 남는 돈을 바꿀 수 없고, 동전은 모자라면 안 되어서","mis":"M5-2-u1-X13"},{"t":"돈은 언제나 반올림해야 해서","mis":"M5-2-u1-X13"},{"t":"필통값이 동전보다 적어서","mis":"M5-2-u1-X13"}],"explanation":["필통값은 모자라면 살 수 없으니 올림해요.","동전은 지폐 한 장이 안 되는 돈을 바꿀 수 없으니 버림해요.","수가 아니라 상황이 어림 방법을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#5','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'sa','auto','밭에서 캔 감자 658 kg을 한 상자에 10 kg씩 담아 팔려고 해요. 상자에 담아 팔 수 있는 감자는 최대 몇 kg인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u1-C7","difficulty":3,"kind":"sa","stem":"밭에서 캔 감자 658 kg을 한 상자에 10 kg씩 담아 팔려고 해요. 상자에 담아 팔 수 있는 감자는 최대 몇 kg인가요? 숫자로 쓰세요.","answer":["650"],"explanation":["10 kg이 안 되는 감자는 상자에 담을 수 없으니 버림해요.","658을 버림하여 십의 자리까지 나타내요.","그래서 최대 650 kg이에요."],"variant_rule":{"alt":[{"stem":"젤리 423개를 한 봉지에 10개씩 담아 판매한다면 최대 몇 개까지 팔 수 있나요? 숫자로 쓰세요.","answer":["420"],"explanation":["10개가 안 되는 젤리는 봉지에 담아 팔 수 없으니 버림해요.","423을 버림하여 십의 자리까지 나타내요.","그래서 최대 420개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#6','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'mc','auto','지리산국립공원의 넓이 485.647 km²를 올림, 버림, 반올림하여 일의 자리까지 차례로 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X11','M5-2-u1-X08','M5-2-u1-X09']::text[],true,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"지리산국립공원의 넓이 485.647 km²를 올림, 버림, 반올림하여 일의 자리까지 차례로 나타낸 것은 어느 것인가요?","options":[{"t":"486, 485, 486","correct":true},{"t":"486, 485, 485","mis":"M5-2-u1-X11"},{"t":"485, 486, 486","mis":"M5-2-u1-X08"},{"t":"490, 480, 490","mis":"M5-2-u1-X09"}],"explanation":["올림: 소수 아래 수를 올려 486이에요.","버림: 소수 아래 수를 버려 485예요.","반올림: 소수 첫째 자리 6을 올려 486이에요."],"variant_rule":{"alt":[{"stem":"덕유산국립공원의 넓이 228.919 km²를 올림, 버림, 반올림하여 일의 자리까지 차례로 나타낸 것은 어느 것인가요?","options":[{"t":"229, 228, 229","correct":true},{"t":"229, 228, 228","mis":"M5-2-u1-X11"},{"t":"228, 229, 229","mis":"M5-2-u1-X08"},{"t":"230, 220, 230","mis":"M5-2-u1-X09"}],"explanation":["올림: 소수 아래 수를 올려 229예요.","버림: 소수 아래 수를 버려 228이에요.","반올림: 소수 첫째 자리 9를 올려 229예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#7','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',3,'ox','auto','동전 58600원을 1000원짜리 지폐로 바꿀 때는 원래 수에 가장 가까운 반올림으로 어림해야 해요.',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":7,"concept":"M5-2-u1-C7","difficulty":3,"kind":"ox","stem":"동전 58600원을 1000원짜리 지폐로 바꿀 때는 원래 수에 가장 가까운 반올림으로 어림해야 해요.","answer":"X","reason_options":[{"t":"모은 돈보다 많은 지폐로 바꿀 수 없어 버림하여 58000원이라서","correct":true},{"t":"반올림이 원래 수에 가장 가까워서","mis":"M5-2-u1-X13"}],"mis":"M5-2-u1-X13","explanation":["반올림하면 59000원이 되지만 동전은 58600원뿐이라 400원이 모자라요.","모은 돈보다 많은 지폐로는 바꿀 수 없어요.","남는 600원은 바꿀 수 없으니 버림하여 58000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#8','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',4,'essay','teacher','은호네 반 학생 32명에게 음료수를 한 개씩 나누어 주려고 해요. 음료수는 10개씩 묶음으로만 팔아요. 은호는 「음료수는 반올림하여 30개를 사야 해요.」라고 말했어요. 은호의 말을 바르게 고쳐 쓰고, 그 까닭을 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"은호네 반 학생 32명에게 음료수를 한 개씩 나누어 주려고 해요. 음료수는 10개씩 묶음으로만 팔아요. 은호는 「음료수는 반올림하여 30개를 사야 해요.」라고 말했어요. 은호의 말을 바르게 고쳐 쓰고, 그 까닭을 설명하세요.","answer_guide":{"answer":"예: 음료수는 올림하여 40개를 사야 해요. 30개를 사면 32명에게 2개가 모자라므로, 필요한 수보다 크게 올림해야 한다.","scoring_points":["「올림」이라는 말을 넣어 40개로 고쳤는가","30개면 2개가 모자란다고 썼는가","모자라면 안 되니 올림한다는 까닭을 썼는가"]},"explanation":["필요한 음료수는 32개예요.","반올림한 30개로는 2개가 모자라요.","올림하여 40개를 사야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#9','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',4,'mc','auto','민우가 지난 3일 동안의 걸음 수를 어림하여 백의 자리까지 나타냈어요. 화요일만 보고 「버림했다」고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X18']::text[],false,'{"seq":9,"concept":"M5-2-u1-C7","difficulty":4,"kind":"mc","stem":"민우가 지난 3일 동안의 걸음 수를 어림하여 백의 자리까지 나타냈어요. 화요일만 보고 「버림했다」고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"월요일 5159가 5200이 되었으니 버림이 아니라 반올림이야","correct":true},{"t":"화요일 6010이 6000이 되었으니 버림이 맞아","mis":"M5-2-u1-X18"},{"t":"월요일 5159가 5200이 되었으니 올림이야","mis":"M5-2-u1-X18"},{"t":"날마다 다른 방법으로 어림했어","mis":"M5-2-u1-X18"}],"explanation":["5159 → 5200은 버림이 아니에요(버림이면 5100).","4963 → 5000도 버림이 아니고, 6010 → 6000은 올림이 아니에요.","세 날 모두 맞는 방법은 반올림이에요."],"asset":{"type":"passage","lines":["민우의 걸음 수와 어림한 값(백의 자리까지)","월요일 5159걸음 → 5200걸음","화요일 6010걸음 → 6000걸음","수요일 4963걸음 → 5000걸음"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L08_challenge#10','math',5,2,'u1','L08','tb_g5_2_math_u1_L08_challenge','lesson_challenge','M5-2-u1-C7',4,'essay','teacher','자동판매기에서 1200원짜리 음료수를 사려는데 1000원짜리 지폐만 있어서 2000원을 넣었어요. 어떤 어림 방법을 쓴 것인지 쓰고, 그 방법을 고른 까닭을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"자동판매기에서 1200원짜리 음료수를 사려는데 1000원짜리 지폐만 있어서 2000원을 넣었어요. 어떤 어림 방법을 쓴 것인지 쓰고, 그 방법을 고른 까닭을 설명하세요.","answer_guide":{"answer":"예: 올림이다. 1000원짜리 지폐로 1200원을 내려면 1000원으로는 200원이 모자라므로 1200을 올림하여 천의 자리까지 나타낸 2000원을 넣는다.","scoring_points":["올림이라고 썼는가","1000원 한 장으로는 모자란다고 썼는가","천의 자리까지 올림하여 2000원이 된다고 설명했는가"]},"explanation":["1000원짜리 지폐 한 장으로는 200원이 모자라요.","모자라면 안 되니 올림해요.","1200을 올림하여 천의 자리까지 — 2000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#1','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨을 만들 때 카레 가루는 몇 g을 구입해야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],true,'{"seq":1,"concept":"M5-2-u1-C8","difficulty":1,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨을 만들 때 카레 가루는 몇 g을 구입해야 하나요?","options":[{"t":"500 g","correct":true},{"t":"400 g","mis":"M5-2-u1-X13"},{"t":"480 g","mis":"M5-2-u1-X14"},{"t":"1000 g","mis":"M5-2-u1-X09"}],"explanation":["카레 가루는 100 g씩 한 봉지로 팔아요.","400 g을 사면 80 g이 모자라니 올림해요.","480을 올림하여 백의 자리까지 — 500 g을 구입해요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]},"variant_rule":{"alt":[{"stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨을 만들 때 고춧가루는 몇 g을 구입해야 하나요?","options":[{"t":"300 g","correct":true},{"t":"200 g","mis":"M5-2-u1-X13"},{"t":"220 g","mis":"M5-2-u1-X14"},{"t":"400 g","mis":"M5-2-u1-X16"}],"explanation":["고춧가루는 100 g씩 한 봉지로 팔아요.","200 g을 사면 20 g이 모자라니 올림해요.","220을 올림하여 백의 자리까지 — 300 g을 구입해요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}},{"stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미를 만들 때 고수는 몇 g을 구입해야 하나요?","options":[{"t":"800 g","correct":true},{"t":"700 g","mis":"M5-2-u1-X13"},{"t":"740 g","mis":"M5-2-u1-X14"},{"t":"1000 g","mis":"M5-2-u1-X09"}],"explanation":["고수는 100 g씩 한 봉지로 팔아요.","700 g을 사면 40 g이 모자라니 올림해요.","740을 올림하여 백의 자리까지 — 800 g을 구입해요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#2','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 음식에 필요한 재료의 양을 판매 단위에 맞추어 구입해야 하는 양을 정할 때 알맞은 어림 방법은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14']::text[],false,'{"seq":2,"concept":"M5-2-u1-C8","difficulty":1,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 음식에 필요한 재료의 양을 판매 단위에 맞추어 구입해야 하는 양을 정할 때 알맞은 어림 방법은 어느 것인가요?","options":[{"t":"올림","correct":true},{"t":"버림","mis":"M5-2-u1-X13"},{"t":"반올림","mis":"M5-2-u1-X13"},{"t":"어림하지 않는다","mis":"M5-2-u1-X14"}],"explanation":["재료가 모자라면 음식을 만들 수 없어요.","필요한 양보다 적지 않게 사야 하니 올림해요.","카레 가루 480 g → 500 g처럼 올림해요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#3','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'sa','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨을 만들 때 카레 가루는 몇 봉지를 구입해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u1-C8","difficulty":1,"kind":"sa","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨을 만들 때 카레 가루는 몇 봉지를 구입해야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["카레 가루 480 g을 올림하면 500 g이에요.","한 봉지가 100 g이니 500 g은 5봉지예요.","그래서 5봉지를 사요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]},"variant_rule":{"alt":[{"stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨을 만들 때 고춧가루는 몇 봉지를 구입해야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["고춧가루 220 g을 올림하면 300 g이에요.","한 봉지가 100 g이니 300 g은 3봉지예요.","그래서 3봉지를 사요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}},{"stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미를 만들 때 바게트는 몇 봉지를 구입해야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["바게트는 한 봉지에 10개예요.","50개는 10개씩 딱 5봉지라 남거나 모자라지 않아요.","그래서 5봉지를 사요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}},{"stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미를 만들 때 돼지고기는 몇 봉지를 구입해야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["돼지고기는 한 봉지에 1 kg이에요.","3.8 kg을 올림하여 일의 자리까지 나타내면 4 kg이에요.","그래서 4봉지를 사요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#4','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',1,'mc','auto','구입 비용을 어림셈하려고 닭고기 한 봉지의 가격 8800원을 반올림하여 천의 자리까지 나타냈어요. 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],true,'{"seq":4,"concept":"M5-2-u1-C8","difficulty":1,"kind":"mc","stem":"구입 비용을 어림셈하려고 닭고기 한 봉지의 가격 8800원을 반올림하여 천의 자리까지 나타냈어요. 얼마인가요?","options":[{"t":"9000원","correct":true},{"t":"8000원","mis":"M5-2-u1-X08"},{"t":"10000원","mis":"M5-2-u1-X09"},{"t":"11000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 8이라 올려요.","8800 → 9000이에요."],"variant_rule":{"alt":[{"stem":"구입 비용을 어림셈하려고 카레 가루 한 봉지의 가격 1900원을 반올림하여 천의 자리까지 나타냈어요. 얼마인가요?","options":[{"t":"2000원","correct":true},{"t":"1000원","mis":"M5-2-u1-X08"},{"t":"3000원","mis":"M5-2-u1-X16"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 9라 올려요.","1900 → 2000이에요."]},{"stem":"구입 비용을 어림셈하려고 고춧가루 한 봉지의 가격 2150원을 반올림하여 천의 자리까지 나타냈어요. 얼마인가요?","options":[{"t":"2000원","correct":true},{"t":"3000원","mis":"M5-2-u1-X08"},{"t":"2200원","mis":"M5-2-u1-X09"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 1이라 버려요.","2150 → 2000이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#5','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 탄두리치킨 재료의 구입 비용을 어림셈하면 약 얼마인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X17','M5-2-u1-X09']::text[],false,'{"seq":5,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 탄두리치킨 재료의 구입 비용을 어림셈하면 약 얼마인가요?","options":[{"t":"약 196000원","correct":true},{"t":"약 180000원","mis":"M5-2-u1-X16"},{"t":"약 191950원","mis":"M5-2-u1-X17"},{"t":"약 200000원","mis":"M5-2-u1-X09"}],"explanation":["닭고기 9000 × 20 = 180000(원), 카레 가루 2000 × 5 = 10000(원)이에요.","고춧가루 2000 × 3 = 6000(원)이에요.","180000 + 10000 + 6000 = 196000 — 약 196000원이에요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#6','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 계산기로 탄두리치킨 재료의 실제 구입 비용을 구하면 얼마인가요?',ARRAY['M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":6,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 계산기로 탄두리치킨 재료의 실제 구입 비용을 구하면 얼마인가요?","options":[{"t":"191950원","correct":true},{"t":"196000원","mis":"M5-2-u1-X17"},{"t":"176000원","mis":"M5-2-u1-X16"},{"t":"185500원","mis":"M5-2-u1-X16"}],"explanation":["닭고기 8800 × 20 = 176000(원), 카레 가루 1900 × 5 = 9500(원)이에요.","고춧가루 2150 × 3 = 6450(원)이에요.","176000 + 9500 + 6450 = 191950(원)이에요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#7','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자를 만들 때 치즈는 몇 kg을 구입해야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X16']::text[],true,'{"seq":7,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자를 만들 때 치즈는 몇 kg을 구입해야 하나요?","options":[{"t":"3 kg","correct":true},{"t":"2 kg","mis":"M5-2-u1-X13"},{"t":"2.7 kg","mis":"M5-2-u1-X14"},{"t":"4 kg","mis":"M5-2-u1-X16"}],"explanation":["치즈는 1 kg씩 한 봉지로 팔아요.","2 kg을 사면 0.7 kg이 모자라니 올림해요.","2.7을 올림하여 일의 자리까지 — 3 kg을 구입해요."],"asset":{"type":"passage","lines":["피자(이탈리아)에 필요한 재료의 양","치즈 2.7 kg · 햄 2.2 kg · 토마토소스 2 L","판매 단위당 가격","치즈 한 봉지 1 kg 13500원","햄 한 봉지 1 kg 11900원","토마토소스 한 봉지 1 L 4800원"]},"variant_rule":{"alt":[{"stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자를 만들 때 햄은 몇 kg을 구입해야 하나요?","options":[{"t":"3 kg","correct":true},{"t":"2 kg","mis":"M5-2-u1-X13"},{"t":"2.2 kg","mis":"M5-2-u1-X14"},{"t":"4 kg","mis":"M5-2-u1-X16"}],"explanation":["햄은 1 kg씩 한 봉지로 팔아요.","반올림하면 2 kg이지만 0.2 kg이 모자라요.","2.2를 올림하여 일의 자리까지 — 3 kg을 구입해요."],"asset":{"type":"passage","lines":["피자(이탈리아)에 필요한 재료의 양","치즈 2.7 kg · 햄 2.2 kg · 토마토소스 2 L","판매 단위당 가격","치즈 한 봉지 1 kg 13500원","햄 한 봉지 1 kg 11900원","토마토소스 한 봉지 1 L 4800원"]}},{"stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미를 만들 때 돼지고기는 몇 kg을 구입해야 하나요?","options":[{"t":"4 kg","correct":true},{"t":"3 kg","mis":"M5-2-u1-X13"},{"t":"3.8 kg","mis":"M5-2-u1-X14"},{"t":"5 kg","mis":"M5-2-u1-X16"}],"explanation":["돼지고기는 1 kg씩 한 봉지로 팔아요.","3 kg을 사면 0.8 kg이 모자라니 올림해요.","3.8을 올림하여 일의 자리까지 — 4 kg을 구입해요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#8','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자를 만들 때 토마토소스의 실제 구입 비용은 얼마인가요?',ARRAY['M5-2-u1-X14','M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":8,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자를 만들 때 토마토소스의 실제 구입 비용은 얼마인가요?","options":[{"t":"9600원","correct":true},{"t":"4800원","mis":"M5-2-u1-X14"},{"t":"10000원","mis":"M5-2-u1-X17"},{"t":"14400원","mis":"M5-2-u1-X16"}],"explanation":["토마토소스 2 L는 1 L 봉지 2개로 딱 맞아요.","한 봉지 4800원이니 4800 × 2를 해요.","4800 × 2 = 9600(원)이에요."],"asset":{"type":"passage","lines":["피자(이탈리아)에 필요한 재료의 양","치즈 2.7 kg · 햄 2.2 kg · 토마토소스 2 L","판매 단위당 가격","치즈 한 봉지 1 kg 13500원","햄 한 봉지 1 kg 11900원","토마토소스 한 봉지 1 L 4800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#9','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',2,'ox','auto','탄두리치킨에 필요한 카레 가루 480 g은 100 g짜리 4봉지를 사면 돼요.',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":9,"concept":"M5-2-u1-C8","difficulty":2,"kind":"ox","stem":"탄두리치킨에 필요한 카레 가루 480 g은 100 g짜리 4봉지를 사면 돼요.","answer":"X","reason_options":[{"t":"4봉지는 400 g이라 80 g이 모자라서 5봉지를 사야 해서","correct":true},{"t":"필요한 양보다 조금 적게 사는 것이 알뜰해서","mis":"M5-2-u1-X13"}],"mis":"M5-2-u1-X13","explanation":["100 g짜리 4봉지는 400 g이에요.","480 g에서 80 g이 모자라요.","모자라면 안 되니 올림하여 5봉지(500 g)를 사요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_basic#10','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_basic','lesson_basic','M5-2-u1-C8',3,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미 재료의 실제 구입 비용은 얼마인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],false,'{"seq":10,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미 재료의 실제 구입 비용은 얼마인가요?","options":[{"t":"100800원","correct":true},{"t":"96600원","mis":"M5-2-u1-X13"},{"t":"91000원","mis":"M5-2-u1-X13"},{"t":"102000원","mis":"M5-2-u1-X17"}],"explanation":["바게트 5봉지, 고수 800 g은 8봉지, 돼지고기 4 kg은 4봉지를 사요.","5600 × 5 + 4200 × 8 + 9800 × 4 = 28000 + 33600 + 39200이에요.","모두 100800원이에요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#1','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',2,'mc','auto','탄두리치킨 재료 구입 문제를 해결한 방법이에요. 「구입해야 하는 양은 필요한 재료의 양을 판매 단위에 맞춰 ( ㉠ )하여 구했고, 구입 비용은 ( ㉡ )을 이용하여 어림셈했습니다.」 ㉠과 ㉡에 알맞은 말을 차례로 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":1,"concept":"M5-2-u1-C8","difficulty":2,"kind":"mc","stem":"탄두리치킨 재료 구입 문제를 해결한 방법이에요. 「구입해야 하는 양은 필요한 재료의 양을 판매 단위에 맞춰 ( ㉠ )하여 구했고, 구입 비용은 ( ㉡ )을 이용하여 어림셈했습니다.」 ㉠과 ㉡에 알맞은 말을 차례로 고른 것은 어느 것인가요?","options":[{"t":"올림, 반올림","correct":true},{"t":"반올림, 올림","mis":"M5-2-u1-X13"},{"t":"올림, 올림","mis":"M5-2-u1-X13"},{"t":"버림, 반올림","mis":"M5-2-u1-X13"}],"explanation":["재료는 모자라면 안 되니 구입할 양은 올림해요.","비용은 실제와 가깝게 어림셈하니 단위당 가격을 반올림해요.","한 문제 안에서도 구하는 것에 따라 어림 방법이 달라요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#2','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',2,'sa','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자를 만들 때 구입해야 하는 치즈, 햄, 토마토소스는 모두 몇 봉지인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M5-2-u1-C8","difficulty":2,"kind":"sa","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자를 만들 때 구입해야 하는 치즈, 햄, 토마토소스는 모두 몇 봉지인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["치즈 2.7 kg → 3봉지, 햄 2.2 kg → 3봉지예요.","토마토소스 2 L → 2봉지예요.","3 + 3 + 2 = 8(봉지)예요."],"asset":{"type":"passage","lines":["피자(이탈리아)에 필요한 재료의 양","치즈 2.7 kg · 햄 2.2 kg · 토마토소스 2 L","판매 단위당 가격","치즈 한 봉지 1 kg 13500원","햄 한 봉지 1 kg 11900원","토마토소스 한 봉지 1 L 4800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#3','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자 재료의 실제 구입 비용은 얼마인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],false,'{"seq":3,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자 재료의 실제 구입 비용은 얼마인가요?","options":[{"t":"85800원","correct":true},{"t":"60400원","mis":"M5-2-u1-X13"},{"t":"73900원","mis":"M5-2-u1-X13"},{"t":"88000원","mis":"M5-2-u1-X17"}],"explanation":["치즈 3봉지, 햄 3봉지, 토마토소스 2봉지를 사요.","13500 × 3 + 11900 × 3 + 4800 × 2 = 40500 + 35700 + 9600이에요.","모두 85800원이에요."],"asset":{"type":"passage","lines":["피자(이탈리아)에 필요한 재료의 양","치즈 2.7 kg · 햄 2.2 kg · 토마토소스 2 L","판매 단위당 가격","치즈 한 봉지 1 kg 13500원","햄 한 봉지 1 kg 11900원","토마토소스 한 봉지 1 L 4800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#4','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 피자 재료의 구입 비용을 어림셈하면 약 얼마인가요?',ARRAY['M5-2-u1-X17','M5-2-u1-X08','M5-2-u1-X16']::text[],false,'{"seq":4,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 피자 재료의 구입 비용을 어림셈하면 약 얼마인가요?","options":[{"t":"약 88000원","correct":true},{"t":"약 85800원","mis":"M5-2-u1-X17"},{"t":"약 80000원","mis":"M5-2-u1-X08"},{"t":"약 42000원","mis":"M5-2-u1-X16"}],"explanation":["13500 → 14000, 11900 → 12000, 4800 → 5000으로 어림해요.","14000 × 3 + 12000 × 3 + 5000 × 2 = 42000 + 36000 + 10000이에요.","약 88000원이에요."],"asset":{"type":"passage","lines":["피자(이탈리아)에 필요한 재료의 양","치즈 2.7 kg · 햄 2.2 kg · 토마토소스 2 L","판매 단위당 가격","치즈 한 봉지 1 kg 13500원","햄 한 봉지 1 kg 11900원","토마토소스 한 봉지 1 L 4800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#5','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 반미 재료의 구입 비용을 어림셈하면 약 얼마인가요?',ARRAY['M5-2-u1-X17','M5-2-u1-X08','M5-2-u1-X16']::text[],false,'{"seq":5,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 반미 재료의 구입 비용을 어림셈하면 약 얼마인가요?","options":[{"t":"약 102000원","correct":true},{"t":"약 100800원","mis":"M5-2-u1-X17"},{"t":"약 93000원","mis":"M5-2-u1-X08"},{"t":"약 30000원","mis":"M5-2-u1-X16"}],"explanation":["5600 → 6000, 4200 → 4000, 9800 → 10000으로 어림해요.","6000 × 5 + 4000 × 8 + 10000 × 4 = 30000 + 32000 + 40000이에요.","약 102000원이에요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#6','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨 재료의 어림셈한 구입 비용과 실제 구입 비용의 차이를 가장 크게 만든 재료는 어느 것인가요?',ARRAY['M5-2-u1-X16']::text[],false,'{"seq":6,"concept":"M5-2-u1-C8","difficulty":3,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨 재료의 어림셈한 구입 비용과 실제 구입 비용의 차이를 가장 크게 만든 재료는 어느 것인가요?","options":[{"t":"닭고기","correct":true},{"t":"카레 가루","mis":"M5-2-u1-X16"},{"t":"고춧가루","mis":"M5-2-u1-X16"},{"t":"세 재료 모두 같다","mis":"M5-2-u1-X16"}],"explanation":["닭고기: 9000 × 20 − 8800 × 20 = 4000(원) 차이예요.","카레 가루는 500원, 고춧가루는 450원 차이예요.","20봉지나 사는 닭고기의 차이가 가장 커요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#7','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',3,'error','auto','반미 재료를 구입하려는 친구들의 말 중에서 잘못된 것을 고르세요.',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],false,'{"seq":7,"concept":"M5-2-u1-C8","difficulty":3,"kind":"error","stem":"반미 재료를 구입하려는 친구들의 말 중에서 잘못된 것을 고르세요.","options":[{"t":"「고수 740 g은 7봉지를 사요.」","correct":true,"mis_target":"M5-2-u1-X13"},{"t":"「바게트 50개는 5봉지를 사요.」","mis":"M5-2-u1-X17"},{"t":"「돼지고기 3.8 kg은 4봉지를 사요.」","mis":"M5-2-u1-X17"}],"explanation":["고수는 100 g씩 팔아 7봉지는 700 g이에요.","740 g에서 40 g이 모자라니 버림하면 안 돼요.","올림하여 8봉지(800 g)를 사야 해요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#8','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',4,'essay','teacher','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨, 반미, 피자 중에서 한 가지를 고르고, 구입해야 하는 재료의 양과 구입 비용을 어떻게 구했는지 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨, 반미, 피자 중에서 한 가지를 고르고, 구입해야 하는 재료의 양과 구입 비용을 어떻게 구했는지 설명하세요.","answer_guide":{"answer":"예: 탄두리치킨 — 필요한 양을 판매 단위에 맞춰 올림하여 닭고기 20마리, 카레 가루 500 g, 고춧가루 300 g을 구입한다. 단위당 가격을 반올림하여 9000원, 2000원, 2000원으로 어림셈하면 약 196000원이고, 계산기로 확인하면 191950원이다.","scoring_points":["구입할 양을 올림하여 구했다고 썼는가","단위당 가격을 반올림하여 비용을 어림셈했다고 썼는가","어림셈 결과와 실제 비용(계산)을 함께 견주었는가"]},"explanation":["구입할 양은 판매 단위에 맞춰 올림해요.","비용은 단위당 가격을 반올림하여 어림셈해요.","계산기로 실제 비용을 구해 어림셈이 알맞은지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#9','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',4,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨 재료의 어림셈한 구입 비용은 실제 구입 비용보다 얼마나 더 많은가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X17']::text[],false,'{"seq":9,"concept":"M5-2-u1-C8","difficulty":4,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 탄두리치킨 재료의 어림셈한 구입 비용은 실제 구입 비용보다 얼마나 더 많은가요?","options":[{"t":"4050원","correct":true},{"t":"4000원","mis":"M5-2-u1-X16"},{"t":"4950원","mis":"M5-2-u1-X16"},{"t":"196000원","mis":"M5-2-u1-X17"}],"explanation":["어림셈한 비용은 약 196000원, 실제 비용은 191950원이에요.","196000 − 191950 = 4050(원)이에요.","차이가 크지 않아 어림셈으로 비용을 미리 예상할 수 있어요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_L09_challenge#10','math',5,2,'u1','L09','tb_g5_2_math_u1_L09_challenge','lesson_challenge','M5-2-u1-C8',4,'essay','teacher','탄두리치킨 재료를 구입할 때 카레 가루 480 g은 500 g으로, 카레 가루 한 봉지의 가격 1900원은 2000원으로 어림했어요. 두 어림이 각각 어떤 방법이고 왜 그 방법을 썼는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C8","difficulty":4,"kind":"essay","stem":"탄두리치킨 재료를 구입할 때 카레 가루 480 g은 500 g으로, 카레 가루 한 봉지의 가격 1900원은 2000원으로 어림했어요. 두 어림이 각각 어떤 방법이고 왜 그 방법을 썼는지 설명하세요.","answer_guide":{"answer":"예: 480 g → 500 g은 올림이다. 재료가 모자라면 안 되므로 100 g 봉지에 맞춰 올림했다. 1900원 → 2000원은 반올림이다. 비용을 실제와 가깝게 어림셈하려고 백의 자리 숫자 9를 보고 올렸다.","scoring_points":["480 g → 500 g이 올림이고 모자라면 안 되어서라고 썼는가","1900원 → 2000원이 반올림이고 실제와 가깝게 어림셈하려고라고 썼는가","구하는 것에 따라 어림 방법이 달라진다는 점을 밝혔는가"]},"explanation":["구입할 양 480 g → 500 g은 모자라면 안 되어서 올림이에요.","가격 1900원 → 2000원은 실제와 가깝게 하려고 반올림이에요.","한 문제에서도 구하는 것이 다르면 어림 방법이 달라요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#1','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C1',1,'mc','auto','45, 35, 30, 25, 50 중에서 35 이상인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"45, 35, 30, 25, 50 중에서 35 이상인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"45, 35, 50","correct":true},{"t":"45, 50","mis":"M5-2-u1-X01"},{"t":"35, 30, 25","mis":"M5-2-u1-X03"},{"t":"45, 35","mis":"M5-2-u1-X16"}],"explanation":["35 이상인 수는 35와 같거나 큰 수예요.","경곗값을 살펴보면 35는 들어가요.","그래서 45, 35, 50이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#2','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',1,'mc','auto','52 초과 58 이하인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],false,'{"seq":2,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"52 초과 58 이하인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"52에 ○, 58에 ●을 그리고 두 점 사이를 선으로 잇는다","correct":true},{"t":"52에 ●, 58에 ●을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"},{"t":"52에 ○, 58에 ○을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"},{"t":"52에 ●, 58에 ○을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"}],"explanation":["이상·이하는 ●, 초과·미만은 ○으로 나타내요.","52는 포함하지 않으니 ○ · 58은 포함하니 ●.","두 점 사이를 선으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#3','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',1,'mc','auto','24, 14.6, 24.5, 17, 12, 20.7, 22, 10.1 중에서 12 초과 24 미만인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],false,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"24, 14.6, 24.5, 17, 12, 20.7, 22, 10.1 중에서 12 초과 24 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"14.6, 17, 20.7, 22","correct":true},{"t":"14.6, 17, 12, 20.7, 22","mis":"M5-2-u1-X02"},{"t":"24, 14.6, 17, 20.7, 22","mis":"M5-2-u1-X02"},{"t":"14.6, 17, 20.7","mis":"M5-2-u1-X16"}],"explanation":["12 초과 24 미만인 수는 12보다 크고 24보다 작은 수예요.","경곗값을 살펴보면 12는 들어가지 않고, 24는 들어가지 않아요.","그래서 14.6, 17, 20.7, 22예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#4','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',1,'mc','auto','오늘 하루 동안 극장에 온 관람객 수는 5217명이에요. 관람객 수를 올림, 버림, 반올림하여 백의 자리까지 차례로 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"오늘 하루 동안 극장에 온 관람객 수는 5217명이에요. 관람객 수를 올림, 버림, 반올림하여 백의 자리까지 차례로 나타낸 것은 어느 것인가요?","options":[{"t":"5300, 5200, 5200","correct":true},{"t":"5200, 5300, 5200","mis":"M5-2-u1-X08"},{"t":"5300, 5200, 5300","mis":"M5-2-u1-X08"},{"t":"5220, 5210, 5220","mis":"M5-2-u1-X09"}],"explanation":["올림: 백의 자리 아래 수를 올려 5300이에요.","버림: 백의 자리 아래 수를 버려 5200이에요.","반올림: 바로 아래 숫자 1을 보고 5200이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#5','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C6',1,'mc','auto','5.602, 5.58, 5.061, 5.63, 5.51 중에서 반올림하여 소수 첫째 자리까지 나타내면 5.6이 되는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X15','M5-2-u1-X09']::text[],false,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"5.602, 5.58, 5.061, 5.63, 5.51 중에서 반올림하여 소수 첫째 자리까지 나타내면 5.6이 되는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5.602, 5.58, 5.63","correct":true},{"t":"5.602, 5.63","mis":"M5-2-u1-X15"},{"t":"5.602, 5.58, 5.061, 5.63","mis":"M5-2-u1-X09"},{"t":"5.602, 5.58, 5.63, 5.51","mis":"M5-2-u1-X15"}],"explanation":["소수 둘째 자리 숫자를 보고 버리거나 올려요.","5.602 → 5.6, 5.58 → 5.6, 5.63 → 5.6이에요.","5.061 → 5.1, 5.51 → 5.5라 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#6','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',1,'mc','auto','세 친구가 어림한 방법을 말했어요. 어림한 방법이 다른 친구는 누구인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"세 친구가 어림한 방법을 말했어요. 어림한 방법이 다른 친구는 누구인가요?","options":[{"t":"시은","correct":true},{"t":"지민","mis":"M5-2-u1-X13"},{"t":"유나","mis":"M5-2-u1-X13"},{"t":"셋 다 같다","mis":"M5-2-u1-X13"}],"explanation":["지민·유나는 남는 돈과 젤리를 쓸 수 없어 버림했어요.","시은은 남는 학생 3명도 타야 하니 올림해서 6번이에요.","어림 방법이 다른 친구는 시은이에요."],"asset":{"type":"speech","turns":[{"who":"지민","text":"1000원짜리 지폐 48장을 모았어요. 모은 돈을 10000원짜리 지폐로 바꾸면 40000원까지 바꿀 수 있어요."},{"who":"유나","text":"젤리 423개를 한 봉지에 10개씩 담아 판매한다면 420개까지 팔 수 있어요."},{"who":"시은","text":"엘리베이터에는 10명까지 탈 수 있어서 우리 학년 학생 53명이 모두 이동하려면 6번 운행해야 해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#7','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',1,'sa','auto','11세인 은우와 19세인 형이 박물관에 가요. 은우와 형의 입장료는 모두 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":1,"kind":"sa","stem":"11세인 은우와 19세인 형이 박물관에 가요. 은우와 형의 입장료는 모두 얼마인가요? 숫자로 쓰세요.","answer":["3000"],"explanation":["은우 11세는 13세 미만이라 1000원이에요.","형 19세는 19세 이상이라 2000원이에요.","1000 + 2000 = 3000(원)이에요."],"asset":{"type":"passage","lines":["박물관 입장료","어린이(13세 미만) — 1000원","청소년(13세 이상 19세 미만) — 1500원","어른(19세 이상) — 2000원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#8','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',1,'mc','auto','밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아서 팔려고 해요. 상자에 담은 가지를 한 상자에 20000원씩 받고 모두 판다면 얼마를 받을 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],false,'{"seq":8,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아서 팔려고 해요. 상자에 담은 가지를 한 상자에 20000원씩 받고 모두 판다면 얼마를 받을 수 있나요?","options":[{"t":"140000원","correct":true},{"t":"160000원","mis":"M5-2-u1-X13"},{"t":"146000원","mis":"M5-2-u1-X14"},{"t":"100000원","mis":"M5-2-u1-X09"}],"explanation":["10 kg씩 담으니 남는 3 kg은 팔 수 없어 버림 — 70 kg, 7상자예요.","한 상자에 20000원씩 받아요.","20000 × 7 = 140000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#9','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C1',2,'sa','auto','뾰로롱 방 탈출 — 「1 이상 9 이하인 수 중에서 가장 작은 수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C1","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「1 이상 9 이하인 수 중에서 가장 작은 수」의 답을 숫자로 쓰세요.","answer":["1"],"explanation":["1 이상이니 1이 들어가요.","1 이상 9 이하인 수 중에서 가장 작은 수는 1이에요.","답 1이 쓰인 구슬에 「알」을 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#10','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C1',2,'sa','auto','뾰로롱 방 탈출 — 「5와 6 중에서 5 이하인 수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C1","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「5와 6 중에서 5 이하인 수」의 답을 숫자로 쓰세요.","answer":["5"],"explanation":["5 이하는 5와 같거나 작은 수예요.","5는 들어가고 6은 빠져요.","답은 5 — 「떼」를 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#11','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',2,'sa','auto','뾰로롱 방 탈출 — 「2 이상 5 미만인 자연수의 합」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「2 이상 5 미만인 자연수의 합」의 답을 숫자로 쓰세요.","answer":["9"],"explanation":["2 이상 5 미만인 자연수는 2, 3, 4예요.","2 + 3 + 4 = 9예요.","답은 9 — 「두」를 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#12','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C4',2,'sa','auto','439를 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C4","difficulty":2,"kind":"sa","stem":"439를 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["500"],"explanation":["올림은 백의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 백의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","439 → 500이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#13','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C5',2,'sa','auto','319를 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"319를 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["310"],"explanation":["버림은 십의 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","319 → 310이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#14','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C6',2,'sa','auto','671을 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"671을 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["700"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 7이라 올려요.","671 → 700이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#15','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C2',2,'error','auto','두 친구의 말을 읽고 잘못 설명한 것을 고르세요.',ARRAY['M5-2-u1-X02','M5-2-u1-X17']::text[],false,'{"seq":15,"concept":"M5-2-u1-C2","difficulty":2,"kind":"error","stem":"두 친구의 말을 읽고 잘못 설명한 것을 고르세요.","options":[{"t":"현아 — 「52 초과인 수에는 52가 포함돼요.」","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"민규 — 「35 이하인 수에는 35가 포함돼요.」","mis":"M5-2-u1-X17"},{"t":"둘 다 바르게 설명했다","mis":"M5-2-u1-X02"}],"explanation":["52 초과인 수는 52보다 큰 수라 52가 포함되지 않아요.","35 이하인 수는 35와 같거나 작은 수라 35가 포함돼요.","잘못 설명한 친구는 현아예요."],"asset":{"type":"speech","turns":[{"who":"민규","text":"35 이하인 수에는 35가 포함돼요."},{"who":"현아","text":"52 초과인 수에는 52가 포함돼요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#16','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C1',2,'mc','auto','획득한 금메달 수가 15개 이상인 나라를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":16,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"획득한 금메달 수가 15개 이상인 나라를 모두 고른 것은 어느 것인가요?","options":[{"t":"네덜란드, 일본","correct":true},{"t":"일본","mis":"M5-2-u1-X01"},{"t":"대한민국, 독일, 스웨덴, 캐나다","mis":"M5-2-u1-X03"},{"t":"대한민국, 네덜란드, 일본","mis":"M5-2-u1-X16"}],"explanation":["15개 이상은 15개와 같거나 많은 수예요.","네덜란드 15개, 일본 20개가 들어가요.","대한민국 13개는 빠져요."],"asset":{"type":"passage","lines":["나라별 획득한 금메달 수","대한민국 13개 · 독일 12개 · 네덜란드 15개","스웨덴 4개 · 일본 20개 · 캐나다 9개"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#17','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',3,'sa','auto','한 수직선에는 87에 ●, 92에 ●이 그려져 두 점 사이가 이어져 있고, 다른 수직선에는 89에 ○, 94에 ●이 그려져 두 점 사이가 이어져 있어요. 두 수직선에 나타낸 수의 범위에 공통으로 포함되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"한 수직선에는 87에 ●, 92에 ●이 그려져 두 점 사이가 이어져 있고, 다른 수직선에는 89에 ○, 94에 ●이 그려져 두 점 사이가 이어져 있어요. 두 수직선에 나타낸 수의 범위에 공통으로 포함되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["87 이상 92 이하와 89 초과 94 이하예요.","둘 다 들어가는 자연수는 90, 91, 92예요.","모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#18','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',3,'sa','auto','뾰로롱 방 탈출 — 약병 글자가 「루」인 문제는 「2 초과 4 이하인 자연수의 합」과 「7 초과 9 미만인 자연수」예요. 두 문제의 답을 더하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"뾰로롱 방 탈출 — 약병 글자가 「루」인 문제는 「2 초과 4 이하인 자연수의 합」과 「7 초과 9 미만인 자연수」예요. 두 문제의 답을 더하면 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["2 초과 4 이하인 자연수의 합은 3 + 4 = 7이에요.","7 초과 9 미만인 자연수는 8이에요.","7 + 8 = 15예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#19','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C6',3,'mc','auto','126□를 반올림하여 십의 자리까지 나타낸 수가 1270일 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X11','M5-2-u1-X15','M5-2-u1-X08']::text[],false,'{"seq":19,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"126□를 반올림하여 십의 자리까지 나타낸 수가 1270일 때, □ 안에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"5, 6, 7, 8, 9","correct":true},{"t":"6, 7, 8, 9","mis":"M5-2-u1-X11"},{"t":"0, 1, 2, 3, 4","mis":"M5-2-u1-X15"},{"t":"1, 2, 3, 4, 5, 6, 7, 8, 9","mis":"M5-2-u1-X08"}],"explanation":["1270이 되려면 일의 자리 숫자를 올려야 해요.","올리는 숫자는 5부터 9까지예요.","0~4는 버려서 1260이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#20','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C7',3,'mc','auto','「35861을 버림하여 천의 자리까지 나타낸 수」와 「34927을 올림하여 백의 자리까지 나타낸 수」의 크기를 비교한 것은 어느 것인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":20,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"「35861을 버림하여 천의 자리까지 나타낸 수」와 「34927을 올림하여 백의 자리까지 나타낸 수」의 크기를 비교한 것은 어느 것인가요?","options":[{"t":"35000 > 34900","correct":true},{"t":"35000 < 34900","mis":"M5-2-u1-X16"},{"t":"36000 > 34900","mis":"M5-2-u1-X08"},{"t":"35000 = 35000","mis":"M5-2-u1-X09"}],"explanation":["35861을 버림하여 천의 자리까지 — 35000이에요.","34927을 올림하여 백의 자리까지 — 34900이에요.","35000 > 34900이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#21','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C4',3,'mc','auto','선미는 6400원짜리 필통과 14800원짜리 지갑을 한 개씩 사고 10000원짜리 지폐로만 돈을 내려고 해요. 최소 얼마를 내야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],false,'{"seq":21,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"선미는 6400원짜리 필통과 14800원짜리 지갑을 한 개씩 사고 10000원짜리 지폐로만 돈을 내려고 해요. 최소 얼마를 내야 하나요?","options":[{"t":"30000원","correct":true},{"t":"20000원","mis":"M5-2-u1-X13"},{"t":"21200원","mis":"M5-2-u1-X14"},{"t":"22000원","mis":"M5-2-u1-X09"}],"explanation":["6400 + 14800 = 21200(원)이에요.","10000원짜리 지폐로만 내니 만의 자리까지 올림해요.","30000원을 내야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#22','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C6',3,'mc','auto','㉠ 8563 ㉡ 9427 ㉢ 8951 ㉣ 8379 중에서 반올림하여 천의 자리까지 나타낸 수가 다른 것은 어느 것인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X08']::text[],false,'{"seq":22,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"㉠ 8563 ㉡ 9427 ㉢ 8951 ㉣ 8379 중에서 반올림하여 천의 자리까지 나타낸 수가 다른 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉡","mis":"M5-2-u1-X16"},{"t":"㉢","mis":"M5-2-u1-X08"},{"t":"㉠","mis":"M5-2-u1-X08"}],"explanation":["반올림하여 천의 자리까지 나타내면 9000, 9000, 9000, 8000이에요.","8379는 백의 자리 숫자 3을 버려 8000이에요.","다른 것은 ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#23','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C4',4,'essay','teacher','문구점에서 색종이를 100장씩 묶음으로만 팔아요. 학생 237명에게 색종이를 3장씩 나누어 주려면 색종이를 최소 몇 장 사야 하는지 풀이 과정을 쓰고 답을 구하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C4","difficulty":4,"kind":"essay","stem":"문구점에서 색종이를 100장씩 묶음으로만 팔아요. 학생 237명에게 색종이를 3장씩 나누어 주려면 색종이를 최소 몇 장 사야 하는지 풀이 과정을 쓰고 답을 구하세요.","answer_guide":{"answer":"예: 필요한 색종이는 237 × 3 = 711(장)이다. 100장씩 묶음으로만 파는데 모자라면 안 되므로 711을 올림하여 백의 자리까지 나타내면 800이다. 최소 800장을 사야 한다.","scoring_points":["필요한 색종이 711장을 구했는가","모자라면 안 되니 올림한다고 썼는가","답 800장을 구했는가"]},"explanation":["237 × 3 = 711(장)이 필요해요.","100장 묶음으로 사니 711을 올림하여 백의 자리까지 나타내요.","최소 800장을 사야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#24','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C8',4,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 탄두리치킨 재료의 구입 비용을 어림셈하면 약 얼마인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X17','M5-2-u1-X09']::text[],false,'{"seq":24,"concept":"M5-2-u1-C8","difficulty":4,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 단위당 가격을 반올림하여 천의 자리까지 나타내어 탄두리치킨 재료의 구입 비용을 어림셈하면 약 얼마인가요?","options":[{"t":"약 196000원","correct":true},{"t":"약 180000원","mis":"M5-2-u1-X16"},{"t":"약 191950원","mis":"M5-2-u1-X17"},{"t":"약 200000원","mis":"M5-2-u1-X09"}],"explanation":["닭고기 20봉지, 카레 가루 5봉지, 고춧가루 3봉지를 사요.","9000 × 20 + 2000 × 5 + 2000 × 3 = 180000 + 10000 + 6000이에요.","약 196000원이에요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_a#25','math',5,2,'u1','','tb_g5_2_math_u1_review_a','unit_review','M5-2-u1-C3',4,'essay','teacher','「52 초과 58 이하인 수」를 수직선에 나타내는 방법을 쓰고, 52에 ●을 그리면 왜 틀리는지 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「52 초과 58 이하인 수」를 수직선에 나타내는 방법을 쓰고, 52에 ●을 그리면 왜 틀리는지 설명하세요.","answer_guide":{"answer":"예: 52에 ○, 58에 ●을 그리고 두 점 사이를 선으로 잇는다. 52 초과는 52보다 큰 수라 52를 포함하지 않으므로 ●(포함)이 아니라 ○으로 그려야 한다.","scoring_points":["52에 ○, 58에 ●을 그린다고 썼는가","두 점 사이를 선으로 잇는다고 썼는가","초과는 경곗값을 포함하지 않아 ●이 틀린다고 설명했는가"]},"explanation":["52 초과는 52를 포함하지 않으니 ○이에요.","58 이하는 58을 포함하니 ●이에요.","52에 ●을 그리면 52 이상을 나타낸 것이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#1','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C2',1,'mc','auto','26, 49, 40, 37, 30 중에서 40 미만인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":1,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"26, 49, 40, 37, 30 중에서 40 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"26, 37, 30","correct":true},{"t":"26, 40, 37, 30","mis":"M5-2-u1-X02"},{"t":"49","mis":"M5-2-u1-X03"},{"t":"26, 37","mis":"M5-2-u1-X16"}],"explanation":["40 미만인 수는 40보다 작은 수예요.","경곗값을 살펴보면 40은 들어가지 않아요.","그래서 26, 37, 30이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#2','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',1,'mc','auto','17 이상 22 미만인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],false,'{"seq":2,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"17 이상 22 미만인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"17에 ●, 22에 ○을 그리고 두 점 사이를 선으로 잇는다","correct":true},{"t":"17에 ○, 22에 ○을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"},{"t":"17에 ●, 22에 ●을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"},{"t":"17에 ○, 22에 ●을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"}],"explanation":["이상·이하는 ●, 초과·미만은 ○으로 나타내요.","17은 포함하니 ● · 22는 포함하지 않으니 ○.","두 점 사이를 선으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#3','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',1,'mc','auto','27, 17, 30, 21, 50, 12, 29 중에서 21 초과 30 이하인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X01','M5-2-u1-X16']::text[],false,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"27, 17, 30, 21, 50, 12, 29 중에서 21 초과 30 이하인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"27, 30, 29","correct":true},{"t":"27, 30, 21, 29","mis":"M5-2-u1-X02"},{"t":"27, 29","mis":"M5-2-u1-X01"},{"t":"27, 30","mis":"M5-2-u1-X16"}],"explanation":["21 초과 30 이하인 수는 21보다 크고 30과 같거나 작은 수예요.","경곗값을 살펴보면 21은 들어가지 않고, 30은 들어가요.","그래서 27, 30, 29예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#4','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',1,'mc','auto','15926을 올림, 버림, 반올림하여 백의 자리까지 차례로 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"15926을 올림, 버림, 반올림하여 백의 자리까지 차례로 나타낸 것은 어느 것인가요?","options":[{"t":"16000, 15900, 15900","correct":true},{"t":"15900, 16000, 15900","mis":"M5-2-u1-X08"},{"t":"16000, 15900, 16000","mis":"M5-2-u1-X08"},{"t":"15930, 15920, 15930","mis":"M5-2-u1-X09"}],"explanation":["올림: 백의 자리 아래 수를 올려 16000이에요.","버림: 백의 자리 아래 수를 버려 15900이에요.","반올림: 바로 아래 숫자 2를 보고 15900이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#5','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C6',1,'mc','auto','저울로 잰 파인애플의 무게는 1.593 kg이에요. 파인애플의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"저울로 잰 파인애플의 무게는 1.593 kg이에요. 파인애플의 무게를 반올림하여 소수 첫째 자리까지 나타내면 몇 kg인가요?","options":[{"t":"1.6 kg","correct":true},{"t":"1.5 kg","mis":"M5-2-u1-X08"},{"t":"1.59 kg","mis":"M5-2-u1-X09"},{"t":"2 kg","mis":"M5-2-u1-X09"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 첫째 자리 바로 아래 숫자가 9라 올려요.","1.593 → 1.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#6','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',1,'mc','auto','세 친구가 어림한 방법을 말했어요. 어림한 방법이 다른 것은 어느 것인가요?',ARRAY['M5-2-u1-X13']::text[],false,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"세 친구가 어림한 방법을 말했어요. 어림한 방법이 다른 것은 어느 것인가요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"M5-2-u1-X13"},{"t":"㉡","mis":"M5-2-u1-X13"},{"t":"셋 다 같다","mis":"M5-2-u1-X13"}],"explanation":["㉠·㉡은 상자에 담고 남는 것을 팔 수 없어 버림했어요.","㉢은 색종이가 모자라면 안 되니 711장을 올림해서 800장이에요.","어림 방법이 다른 것은 ㉢이에요."],"asset":{"type":"speech","turns":[{"who":"㉠","text":"볼펜 460자루를 한 상자에 100자루씩 담으면 400자루까지 팔 수 있어요."},{"who":"㉡","text":"감자 658 kg을 한 상자에 10 kg씩 담으면 650 kg까지 팔 수 있어요."},{"who":"㉢","text":"학생 237명에게 색종이를 3장씩 주려면 100장 묶음으로 800장을 사야 해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#7','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',1,'mc','auto','12세인 소진이와 39세인 어머니가 숲 체험장에 입장할 때 내야 하는 입장료는 모두 얼마인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"12세인 소진이와 39세인 어머니가 숲 체험장에 입장할 때 내야 하는 입장료는 모두 얼마인가요?","options":[{"t":"18000원","correct":true},{"t":"16000원","mis":"M5-2-u1-X02"},{"t":"20000원","mis":"M5-2-u1-X16"},{"t":"14000원","mis":"M5-2-u1-X16"}],"explanation":["소진이 12세는 12세 이상 19세 미만이라 8000원이에요.","어머니 39세는 19세 이상이라 10000원이에요.","8000 + 10000 = 18000(원)이에요."],"asset":{"type":"passage","lines":["숲 체험장 나이별 입장료","7세 미만 — 4000원","7세 이상 12세 미만 — 6000원","12세 이상 19세 미만 — 8000원","19세 이상 — 10000원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#8','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',1,'mc','auto','과일 가게에서 귤 214개를 한 상자에 10개씩 담아 팔려고 해요. 상자에 담긴 귤을 한 상자에 3000원씩 받고 모두 판다면 얼마를 받을 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],false,'{"seq":8,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"과일 가게에서 귤 214개를 한 상자에 10개씩 담아 팔려고 해요. 상자에 담긴 귤을 한 상자에 3000원씩 받고 모두 판다면 얼마를 받을 수 있나요?","options":[{"t":"63000원","correct":true},{"t":"66000원","mis":"M5-2-u1-X13"},{"t":"64200원","mis":"M5-2-u1-X14"},{"t":"60000원","mis":"M5-2-u1-X09"}],"explanation":["214를 버림하여 십의 자리까지 — 21상자예요.","남는 4개는 팔 수 없어요.","3000 × 21 = 63000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#9','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C2',2,'sa','auto','뾰로롱 방 탈출 — 「2.4, 5.1, 3.7 중에서 1 이상 4 미만인 수의 개수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C2","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「2.4, 5.1, 3.7 중에서 1 이상 4 미만인 수의 개수」의 답을 숫자로 쓰세요.","answer":["2"],"explanation":["1과 같거나 크고 4보다 작은 수를 찾아요.","2.4와 3.7이 들어가고 5.1은 빠져요.","답은 2 — 「쏭」을 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#10','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',2,'sa','auto','뾰로롱 방 탈출 — 「25 이상 30 이하인 자연수의 개수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「25 이상 30 이하인 자연수의 개수」의 답을 숫자로 쓰세요.","answer":["6"],"explanation":["25와 30이 모두 들어가요.","25, 26, 27, 28, 29, 30이에요.","답은 6 — 「구」를 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#11','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C1',2,'sa','auto','뾰로롱 방 탈출 — 「4 이하인 자연수의 합」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M5-2-u1-C1","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「4 이하인 자연수의 합」의 답을 숫자로 쓰세요.","answer":["10"],"explanation":["4 이하인 자연수는 1, 2, 3, 4예요.","1 + 2 + 3 + 4 = 10이에요.","답은 10 — 「둥」을 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#12','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C4',2,'sa','auto','537을 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C4","difficulty":2,"kind":"sa","stem":"537을 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["600"],"explanation":["올림은 백의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 백의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","537 → 600이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#13','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C5',2,'sa','auto','863을 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"863을 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["860"],"explanation":["버림은 십의 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","863 → 860이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#14','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C6',2,'sa','auto','915를 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"915를 반올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["900"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 1이라 버려요.","915 → 900이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#15','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C2',2,'error','auto','세 친구의 말을 읽고 잘못 설명한 것을 고르세요.',ARRAY['M5-2-u1-X02','M5-2-u1-X17']::text[],false,'{"seq":15,"concept":"M5-2-u1-C2","difficulty":2,"kind":"error","stem":"세 친구의 말을 읽고 잘못 설명한 것을 고르세요.","options":[{"t":"성호 — 「31, 32, 33 중에서 32 초과인 수는 32, 33이에요.」","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"민규 — 「50은 50 이상인 수에 포함돼요.」","mis":"M5-2-u1-X17"},{"t":"현아 — 「17은 17 미만인 수에 포함되지 않아요.」","mis":"M5-2-u1-X17"}],"explanation":["32 초과인 수는 32보다 큰 수예요.","31, 32, 33 중에서 32 초과인 수는 33뿐이에요.","민규와 현아는 바르게 설명했어요 — 잘못 설명한 친구는 성호예요."],"asset":{"type":"speech","turns":[{"who":"민규","text":"50은 50 이상인 수에 포함돼요."},{"who":"현아","text":"17은 17 미만인 수에 포함되지 않아요."},{"who":"성호","text":"31, 32, 33 중에서 32 초과인 수는 32, 33이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#16','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C1',2,'mc','auto','획득한 금메달 수가 10개 이하인 나라를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X03']::text[],false,'{"seq":16,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"획득한 금메달 수가 10개 이하인 나라를 모두 고른 것은 어느 것인가요?","options":[{"t":"스웨덴, 캐나다","correct":true},{"t":"스웨덴","mis":"M5-2-u1-X16"},{"t":"대한민국, 독일, 네덜란드, 일본","mis":"M5-2-u1-X03"},{"t":"스웨덴, 독일, 캐나다","mis":"M5-2-u1-X16"}],"explanation":["10개 이하는 10개와 같거나 적은 수예요.","스웨덴 4개, 캐나다 9개가 들어가요.","독일 12개는 빠져요."],"asset":{"type":"passage","lines":["나라별 획득한 금메달 수","대한민국 13개 · 독일 12개 · 네덜란드 15개","스웨덴 4개 · 일본 20개 · 캐나다 9개"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#17','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',3,'sa','auto','167 이상 175 미만인 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"167 이상 175 미만인 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["167은 들어가고 175는 빠져요.","167부터 174까지예요.","174 − 167 + 1 = 8(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#18','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C3',3,'sa','auto','뾰로롱 방 탈출 — 약병 글자가 「쏭」인 문제는 「2.4, 5.1, 3.7 중에서 1 이상 4 미만인 수의 개수」와 「3 초과 5 이하인 수 중에서 가장 작은 자연수」예요. 두 문제의 답을 더하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"뾰로롱 방 탈출 — 약병 글자가 「쏭」인 문제는 「2.4, 5.1, 3.7 중에서 1 이상 4 미만인 수의 개수」와 「3 초과 5 이하인 수 중에서 가장 작은 자연수」예요. 두 문제의 답을 더하면 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2.4, 3.7이 1 이상 4 미만이라 답은 2예요.","3 초과 5 이하인 자연수 중 가장 작은 수는 4예요.","2 + 4 = 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#19','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C6',3,'sa','auto','반올림하여 십의 자리까지 나타내면 50이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-2-u1-C6","difficulty":3,"kind":"sa","stem":"반올림하여 십의 자리까지 나타내면 50이 되는 자연수는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["45부터 49까지는 올려서 50이 돼요.","50부터 54까지는 버려서 50이 돼요.","모두 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#20','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C5',3,'mc','auto','「2347을 버림하여 십의 자리까지 나타낸 수」와 「2347을 버림하여 백의 자리까지 나타낸 수」의 크기를 비교한 것은 어느 것인가요?',ARRAY['M5-2-u1-X16','M5-2-u1-X09','M5-2-u1-X08']::text[],false,'{"seq":20,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"「2347을 버림하여 십의 자리까지 나타낸 수」와 「2347을 버림하여 백의 자리까지 나타낸 수」의 크기를 비교한 것은 어느 것인가요?","options":[{"t":"2340 > 2300","correct":true},{"t":"2340 < 2300","mis":"M5-2-u1-X16"},{"t":"2300 = 2300","mis":"M5-2-u1-X09"},{"t":"2350 > 2300","mis":"M5-2-u1-X08"}],"explanation":["십의 자리까지 버림하면 2340이에요.","백의 자리까지 버림하면 2300이에요.","2340 > 2300이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#21','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C7',3,'mc','auto','준하는 16400원짜리 과학책을 한 권 사고 1000원짜리 지폐로 책값을 내려고 해요. 알맞은 어림 방법과 최소로 내야 하는 돈을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09']::text[],false,'{"seq":21,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"준하는 16400원짜리 과학책을 한 권 사고 1000원짜리 지폐로 책값을 내려고 해요. 알맞은 어림 방법과 최소로 내야 하는 돈을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"올림, 17000원","correct":true},{"t":"반올림, 16000원","mis":"M5-2-u1-X13"},{"t":"버림, 16000원","mis":"M5-2-u1-X13"},{"t":"올림, 20000원","mis":"M5-2-u1-X09"}],"explanation":["책값보다 적게 내면 안 되니 올림해요.","1000원짜리 지폐라 천의 자리까지 어림해요.","16400 → 17000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#22','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C4',3,'mc','auto','㉠ 7352 ㉡ 8012 ㉢ 7864 ㉣ 7063 중에서 올림하여 천의 자리까지 나타낸 수가 다른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16']::text[],false,'{"seq":22,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"㉠ 7352 ㉡ 8012 ㉢ 7864 ㉣ 7063 중에서 올림하여 천의 자리까지 나타낸 수가 다른 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉣","mis":"M5-2-u1-X08"},{"t":"㉢","mis":"M5-2-u1-X08"},{"t":"㉠","mis":"M5-2-u1-X16"}],"explanation":["올림하여 천의 자리까지 나타내면 8000, 9000, 8000, 8000이에요.","8012는 천의 자리 아래 12를 올려 9000이에요.","다른 것은 ㉡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#23','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C5',4,'essay','teacher','수 카드 「.」, 9, 2, 6을 한 번씩만 이용하여 가장 큰 소수 두 자리 수를 만들고, 만든 수를 버림하여 소수 첫째 자리까지 나타내려고 해요. 풀이 과정을 쓰고 답을 구하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C5","difficulty":4,"kind":"essay","stem":"수 카드 「.」, 9, 2, 6을 한 번씩만 이용하여 가장 큰 소수 두 자리 수를 만들고, 만든 수를 버림하여 소수 첫째 자리까지 나타내려고 해요. 풀이 과정을 쓰고 답을 구하세요.","answer_guide":{"answer":"예: 소수 두 자리 수는 □.□□ 꼴이므로 큰 숫자부터 놓으면 가장 큰 수는 9.62이다. 9.62를 버림하여 소수 첫째 자리까지 나타내면 소수 둘째 자리 2를 버려 9.6이다.","scoring_points":["가장 큰 소수 두 자리 수 9.62를 만들었는가","소수 둘째 자리를 버린다고 썼는가","답 9.6을 구했는가"]},"explanation":["□.□□ 꼴에 큰 숫자부터 놓아 9.62를 만들어요.","버림하여 소수 첫째 자리까지 나타내면 2를 버려요.","답은 9.6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#24','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C8',4,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미 재료의 실제 구입 비용은 얼마인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],false,'{"seq":24,"concept":"M5-2-u1-C8","difficulty":4,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 반미 재료의 실제 구입 비용은 얼마인가요?","options":[{"t":"100800원","correct":true},{"t":"96600원","mis":"M5-2-u1-X13"},{"t":"91000원","mis":"M5-2-u1-X13"},{"t":"102000원","mis":"M5-2-u1-X17"}],"explanation":["바게트 5봉지, 고수 8봉지, 돼지고기 4봉지를 사요.","28000 + 33600 + 39200을 더해요.","100800원이에요."],"asset":{"type":"passage","lines":["반미(베트남)에 필요한 재료의 양","바게트 50개 · 고수 740 g · 돼지고기 3.8 kg","판매 단위당 가격","바게트 한 봉지 10개 5600원","고수 한 봉지 100 g 4200원","돼지고기 한 봉지 1 kg 9800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_b#25','math',5,2,'u1','','tb_g5_2_math_u1_review_b','unit_review','M5-2-u1-C6',4,'essay','teacher','오늘 하루 동안 극장에 온 관람객은 5217명이에요. 한 친구가 관람객 수를 반올림하여 백의 자리까지 나타내면 5000이라고 했어요. 잘못된 점을 찾아 바르게 고치고, 반올림할 때 살펴볼 자리를 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C6","difficulty":4,"kind":"essay","stem":"오늘 하루 동안 극장에 온 관람객은 5217명이에요. 한 친구가 관람객 수를 반올림하여 백의 자리까지 나타내면 5000이라고 했어요. 잘못된 점을 찾아 바르게 고치고, 반올림할 때 살펴볼 자리를 설명하세요.","answer_guide":{"answer":"예: 5000은 천의 자리까지 나타낸 수이다. 백의 자리까지 반올림하려면 바로 아래 십의 자리 숫자 1을 보고 버려서 5200이 된다.","scoring_points":["구하려는 자리를 잘못 잡았다고 썼는가","바로 아래 십의 자리 숫자 1을 살펴본다고 썼는가","바른 답 5200을 구했는가"]},"explanation":["백의 자리까지 반올림할 때는 바로 아래 십의 자리 숫자를 봐요.","5217의 십의 자리 숫자 1은 버려요.","바른 답은 5200이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#1','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C1',1,'mc','auto','84, 55, 49, 60, 63, 72, 52, 77 중에서 77 이상인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":1,"concept":"M5-2-u1-C1","difficulty":1,"kind":"mc","stem":"84, 55, 49, 60, 63, 72, 52, 77 중에서 77 이상인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"84, 77","correct":true},{"t":"84","mis":"M5-2-u1-X01"},{"t":"55, 49, 60, 63, 72, 52, 77","mis":"M5-2-u1-X03"},{"t":"84, 77, 55","mis":"M5-2-u1-X16"}],"explanation":["77 이상인 수는 77과 같거나 큰 수예요.","경곗값을 살펴보면 77은 들어가요.","그래서 84, 77이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#2','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C2',1,'mc','auto','47 초과인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X04','M5-2-u1-X03']::text[],false,'{"seq":2,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"47 초과인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"47에 ○을 그리고 오른쪽으로 선을 긋는다","correct":true},{"t":"47에 ●을 그리고 오른쪽으로 선을 긋는다","mis":"M5-2-u1-X04"},{"t":"47에 ○을 그리고 왼쪽으로 선을 긋는다","mis":"M5-2-u1-X03"},{"t":"47에 ●을 그리고 왼쪽으로 선을 긋는다","mis":"M5-2-u1-X03"}],"explanation":["이상·이하는 ●, 초과·미만은 ○으로 나타내요.","47은 포함하지 않으니 ○.","큰 쪽이니 오른쪽으로 선을 그어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#3','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',1,'mc','auto','29, 38.2, 45.1, 36, 42.7, 43, 40, 35.9 중에서 36 이상 43 미만인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X02','M5-2-u1-X16']::text[],false,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"29, 38.2, 45.1, 36, 42.7, 43, 40, 35.9 중에서 36 이상 43 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"38.2, 36, 42.7, 40","correct":true},{"t":"38.2, 42.7, 40","mis":"M5-2-u1-X01"},{"t":"38.2, 36, 42.7, 43, 40","mis":"M5-2-u1-X02"},{"t":"38.2, 36, 42.7","mis":"M5-2-u1-X16"}],"explanation":["36 이상 43 미만인 수는 36과 같거나 크고 43보다 작은 수예요.","경곗값을 살펴보면 36은 들어가고, 43은 들어가지 않아요.","그래서 38.2, 36, 42.7, 40이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#4','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C7',1,'mc','auto','21840을 올림, 버림, 반올림하여 천의 자리까지 차례로 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"21840을 올림, 버림, 반올림하여 천의 자리까지 차례로 나타낸 것은 어느 것인가요?","options":[{"t":"22000, 21000, 22000","correct":true},{"t":"21000, 22000, 22000","mis":"M5-2-u1-X08"},{"t":"22000, 21000, 21000","mis":"M5-2-u1-X08"},{"t":"21900, 21800, 21800","mis":"M5-2-u1-X09"}],"explanation":["올림: 천의 자리 아래 수를 올려 22000이에요.","버림: 천의 자리 아래 수를 버려 21000이에요.","반올림: 바로 아래 숫자 8을 보고 22000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#5','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C6',1,'mc','auto','4.739를 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"4.739를 반올림하여 소수 둘째 자리까지 나타내면 얼마인가요?","options":[{"t":"4.74","correct":true},{"t":"4.73","mis":"M5-2-u1-X08"},{"t":"4.7","mis":"M5-2-u1-X09"},{"t":"4.75","mis":"M5-2-u1-X16"}],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","소수 둘째 자리 바로 아래 숫자가 9라 올려요.","4.739 → 4.74예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#6','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C7',1,'mc','auto','1000원짜리 지폐 48장을 모았어요. 모은 돈을 10000원짜리 지폐로 바꾸면 최대 얼마까지 바꿀 수 있나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X16']::text[],false,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"1000원짜리 지폐 48장을 모았어요. 모은 돈을 10000원짜리 지폐로 바꾸면 최대 얼마까지 바꿀 수 있나요?","options":[{"t":"40000원","correct":true},{"t":"50000원","mis":"M5-2-u1-X13"},{"t":"48000원","mis":"M5-2-u1-X14"},{"t":"4000원","mis":"M5-2-u1-X16"}],"explanation":["1000원짜리 48장은 48000원이에요.","10000원짜리 지폐로 바꾸니 남는 8000원은 바꿀 수 없어 버림해요.","48000을 버림하여 만의 자리까지 — 40000원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#7','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',1,'sa','auto','준석이네 가족 중에서 입장료로 2000원을 내야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":1,"kind":"sa","stem":"준석이네 가족 중에서 입장료로 2000원을 내야 하는 사람은 모두 몇 명인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["2000원은 19세 초과예요.","아빠 42세와 엄마 39세가 들어가요.","형 15세는 1000원 — 2000원은 2명이에요."],"asset":{"type":"passage","lines":["준석이네 가족의 나이","아빠 42세 · 엄마 39세 · 형 15세 · 준석 11세 · 동생 7세","박물관 나이별 입장료","19세 초과 — 2000원 · 14세 초과 19세 이하 — 1000원","7세 초과 14세 이하 — 500원 · 7세 이하 — 무료"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#8','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C5',1,'sa','auto','공장에서 볼펜을 460자루 만들었어요. 한 상자에 100자루씩 담아 팔 때 상자에 담아 팔 수 있는 볼펜은 최대 몇 자루인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M5-2-u1-C5","difficulty":1,"kind":"sa","stem":"공장에서 볼펜을 460자루 만들었어요. 한 상자에 100자루씩 담아 팔 때 상자에 담아 팔 수 있는 볼펜은 최대 몇 자루인가요? 숫자로 쓰세요.","answer":["400"],"explanation":["100자루씩 담으니 남는 60자루는 팔 수 없어요.","460을 버림하여 백의 자리까지 나타내요.","최대 400자루예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#9','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C2',2,'sa','auto','뾰로롱 방 탈출 — 「15 초과 19 미만인 자연수의 개수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C2","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「15 초과 19 미만인 자연수의 개수」의 답을 숫자로 쓰세요.","answer":["3"],"explanation":["15와 19는 들어가지 않아요.","16, 17, 18이 들어가요.","답은 3 — 「달」을 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#10','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',2,'sa','auto','뾰로롱 방 탈출 — 「2 초과 4 이하인 자연수의 합」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「2 초과 4 이하인 자연수의 합」의 답을 숫자로 쓰세요.","answer":["7"],"explanation":["2 초과 4 이하인 자연수는 3, 4예요.","3 + 4 = 7이에요.","답은 7 — 「루」를 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#11','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C2',2,'sa','auto','뾰로롱 방 탈출 — 「12 미만인 수 중에서 가장 큰 자연수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M5-2-u1-C2","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「12 미만인 수 중에서 가장 큰 자연수」의 답을 숫자로 쓰세요.","answer":["11"],"explanation":["12 미만이라 12는 들어가지 않아요.","12보다 작은 자연수 중 가장 큰 수는 11이에요.","답은 11 — 「실」을 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#12','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C4',2,'sa','auto','5461을 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C4","difficulty":2,"kind":"sa","stem":"5461을 올림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["5500"],"explanation":["올림은 백의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 백의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","5461 → 5500이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#13','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C5',2,'sa','auto','6782를 버림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"6782를 버림하여 백의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["6700"],"explanation":["버림은 백의 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","6782 → 6700이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#14','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C6',2,'sa','auto','백두산의 높이는 2744 m예요. 백두산의 높이를 반올림하여 백의 자리까지 나타내면 몇 m인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"백두산의 높이는 2744 m예요. 백두산의 높이를 반올림하여 백의 자리까지 나타내면 몇 m인가요? 숫자로 쓰세요.","answer":["2700"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","백의 자리 바로 아래 숫자가 4라 버려요.","2744 → 2700이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#15','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C2',2,'error','auto','두 친구의 말을 읽고 잘못 말한 것을 고르세요.',ARRAY['M5-2-u1-X02','M5-2-u1-X17']::text[],false,'{"seq":15,"concept":"M5-2-u1-C2","difficulty":2,"kind":"error","stem":"두 친구의 말을 읽고 잘못 말한 것을 고르세요.","options":[{"t":"선재 — 「64세 미만에는 64세도 포함돼요.」","correct":true,"mis_target":"M5-2-u1-X02"},{"t":"연서 — 「11세, 12세, 13세 중에서 12세 초과인 나이는 13세뿐이에요.」","mis":"M5-2-u1-X17"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u1-X02"}],"explanation":["64세 미만은 64세보다 적은 나이예요.","그래서 64세는 포함되지 않아요.","12세 초과에는 12세가 빠져 13세뿐 — 연서는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"선재","text":"64세 미만에는 64세도 포함돼요."},{"who":"연서","text":"11세, 12세, 13세 중에서 12세 초과인 나이는 13세뿐이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#16','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',2,'mc','auto','가희와 등급이 같은 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X02','M5-2-u1-X03']::text[],false,'{"seq":16,"concept":"M5-2-u1-C3","difficulty":2,"kind":"mc","stem":"가희와 등급이 같은 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"나리, 유나","correct":true},{"t":"유나","mis":"M5-2-u1-X01"},{"t":"지아, 나리, 유나","mis":"M5-2-u1-X02"},{"t":"성윤, 나리, 유나","mis":"M5-2-u1-X03"}],"explanation":["가희 37회는 35회 초과 59회 이하라 2등급이에요.","나리 59회, 유나 41회가 같은 2등급이에요.","지아 35회는 35회 초과가 아니라 3등급이에요."],"asset":{"type":"passage","lines":["윗몸 말아 올리기 평가 기준(여자)","1등급 59회 초과 · 2등급 35회 초과 59회 이하","3등급 22회 초과 35회 이하 · 4등급 6회 초과 22회 이하","5등급 6회 이하","기록 — 가희 37회 · 성윤 61회 · 지아 35회 · 나리 59회 · 유나 41회"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#17','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',3,'mc','auto','자연수 부분이 2이고, 소수 첫째 자리 숫자가 5 이상 8 미만인 소수 한 자리 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X01','M5-2-u1-X05']::text[],false,'{"seq":17,"concept":"M5-2-u1-C3","difficulty":3,"kind":"mc","stem":"자연수 부분이 2이고, 소수 첫째 자리 숫자가 5 이상 8 미만인 소수 한 자리 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2.5, 2.6, 2.7","correct":true},{"t":"2.5, 2.6, 2.7, 2.8","mis":"M5-2-u1-X02"},{"t":"2.6, 2.7","mis":"M5-2-u1-X01"},{"t":"2.6, 2.7, 2.8","mis":"M5-2-u1-X05"}],"explanation":["소수 첫째 자리 숫자는 5, 6, 7이에요.","5 이상이라 5는 들어가고, 8 미만이라 8은 빠져요.","그래서 2.5, 2.6, 2.7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#18','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',3,'sa','auto','뾰로롱 방 탈출 — 「2 이상 5 미만인 자연수의 합」(두)과 「4 이하인 자연수의 합」(둥)의 답을 더하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"뾰로롱 방 탈출 — 「2 이상 5 미만인 자연수의 합」(두)과 「4 이하인 자연수의 합」(둥)의 답을 더하면 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["2 + 3 + 4 = 9예요.","1 + 2 + 3 + 4 = 10이에요.","9 + 10 = 19예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#19','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C6',3,'sa','auto','반올림하여 백의 자리까지 나타내면 3200이 되는 가장 큰 자연수와 가장 작은 자연수의 차를 구하세요. 숫자로 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-2-u1-C6","difficulty":3,"kind":"sa","stem":"반올림하여 백의 자리까지 나타내면 3200이 되는 가장 큰 자연수와 가장 작은 자연수의 차를 구하세요. 숫자로 쓰세요.","answer":["99"],"explanation":["가장 작은 자연수는 3150이에요.","가장 큰 자연수는 3249예요.","3249 − 3150 = 99예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#20','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C6',3,'mc','auto','5.49를 반올림하여 일의 자리까지 나타낸 수와 소수 첫째 자리까지 나타낸 수 중에서 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u1-X10','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":20,"concept":"M5-2-u1-C6","difficulty":3,"kind":"mc","stem":"5.49를 반올림하여 일의 자리까지 나타낸 수와 소수 첫째 자리까지 나타낸 수 중에서 더 큰 것은 어느 것인가요?","options":[{"t":"소수 첫째 자리까지 나타낸 수 5.5","correct":true},{"t":"일의 자리까지 나타낸 수 6","mis":"M5-2-u1-X10"},{"t":"둘이 같다 — 모두 5.5","mis":"M5-2-u1-X09"},{"t":"일의 자리까지 나타낸 수 5","mis":"M5-2-u1-X16"}],"explanation":["일의 자리까지: 4를 버려 5예요.","소수 첫째 자리까지: 9를 올려 5.5예요.","5.5를 다시 반올림하지 않아요 — 5.5가 더 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#21','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C4',3,'mc','auto','문구점에서 색종이를 100장씩 묶음으로만 팔아요. 학생 237명에게 색종이를 3장씩 나누어 주려면 색종이를 최소 몇 장 사야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X16']::text[],false,'{"seq":21,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"문구점에서 색종이를 100장씩 묶음으로만 팔아요. 학생 237명에게 색종이를 3장씩 나누어 주려면 색종이를 최소 몇 장 사야 하나요?","options":[{"t":"800장","correct":true},{"t":"700장","mis":"M5-2-u1-X13"},{"t":"711장","mis":"M5-2-u1-X14"},{"t":"300장","mis":"M5-2-u1-X16"}],"explanation":["237 × 3 = 711(장)이 필요해요.","100장 묶음으로 사니 올림하여 백의 자리까지 나타내요.","800장을 사야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#22','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C5',3,'mc','auto','㉠ 3459 ㉡ 3572 ㉢ 3501 ㉣ 3600 중에서 버림하여 백의 자리까지 나타낸 수가 같은 것을 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X16']::text[],false,'{"seq":22,"concept":"M5-2-u1-C5","difficulty":3,"kind":"mc","stem":"㉠ 3459 ㉡ 3572 ㉢ 3501 ㉣ 3600 중에서 버림하여 백의 자리까지 나타낸 수가 같은 것을 고른 것은 어느 것인가요?","options":[{"t":"㉡, ㉢","correct":true},{"t":"㉠, ㉢","mis":"M5-2-u1-X08"},{"t":"㉡, ㉢, ㉣","mis":"M5-2-u1-X08"},{"t":"㉢, ㉣","mis":"M5-2-u1-X16"}],"explanation":["버림하면 3400, 3500, 3500, 3600이에요.","㉡과 ㉢이 3500으로 같아요.","반올림하면 ㉠과 ㉢이 같아지니 방법을 잘 봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#23','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C3',4,'essay','teacher','167 이상 175 미만인 자연수는 모두 몇 개인지 풀이 과정을 쓰고 답을 구하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"167 이상 175 미만인 자연수는 모두 몇 개인지 풀이 과정을 쓰고 답을 구하세요.","answer_guide":{"answer":"예: 167 이상이므로 167은 포함되고, 175 미만이므로 175는 포함되지 않는다. 167부터 174까지의 자연수이므로 174 − 167 + 1 = 8, 모두 8개이다.","scoring_points":["167은 포함되고 175는 포함되지 않음을 썼는가","167부터 174까지라고 범위를 밝혔는가","8개를 구했는가"]},"explanation":["이상은 경곗값 167을 포함해요.","미만은 경곗값 175를 포함하지 않아요.","167부터 174까지 — 8개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#24','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C8',4,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자 재료의 실제 구입 비용은 얼마인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X17']::text[],false,'{"seq":24,"concept":"M5-2-u1-C8","difficulty":4,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 피자 재료의 실제 구입 비용은 얼마인가요?","options":[{"t":"85800원","correct":true},{"t":"60400원","mis":"M5-2-u1-X13"},{"t":"73900원","mis":"M5-2-u1-X13"},{"t":"88000원","mis":"M5-2-u1-X17"}],"explanation":["치즈 3봉지, 햄 3봉지, 토마토소스 2봉지를 사요.","40500 + 35700 + 9600을 더해요.","85800원이에요."],"asset":{"type":"passage","lines":["피자(이탈리아)에 필요한 재료의 양","치즈 2.7 kg · 햄 2.2 kg · 토마토소스 2 L","판매 단위당 가격","치즈 한 봉지 1 kg 13500원","햄 한 봉지 1 kg 11900원","토마토소스 한 봉지 1 L 4800원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_c#25','math',5,2,'u1','','tb_g5_2_math_u1_review_c','unit_review','M5-2-u1-C7',4,'essay','teacher','밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아서 한 상자에 20000원씩 받고 모두 팔려고 해요. 어떤 어림 방법을 써야 하는지 까닭과 함께 쓰고, 받을 수 있는 돈을 구하세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C7","difficulty":4,"kind":"essay","stem":"밭에서 딴 가지 73 kg을 한 상자에 10 kg씩 담아서 한 상자에 20000원씩 받고 모두 팔려고 해요. 어떤 어림 방법을 써야 하는지 까닭과 함께 쓰고, 받을 수 있는 돈을 구하세요.","answer_guide":{"answer":"예: 버림이다. 10 kg이 안 되는 남는 3 kg은 상자에 담아 팔 수 없으므로 73을 버림하여 70 kg, 7상자를 판다. 20000 × 7 = 140000(원)을 받는다.","scoring_points":["버림이라고 썼는가","남는 3 kg은 팔 수 없다는 까닭을 썼는가","7상자, 140000원을 구했는가"]},"explanation":["남는 3 kg은 상자에 담아 팔 수 없어 버림해요.","70 kg은 10 kg씩 7상자예요.","20000 × 7 = 140000(원)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#1','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C2',1,'mc','auto','55, 39, 59, 41, 43, 62 중에서 43 미만인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X03','M5-2-u1-X16']::text[],false,'{"seq":1,"concept":"M5-2-u1-C2","difficulty":1,"kind":"mc","stem":"55, 39, 59, 41, 43, 62 중에서 43 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"39, 41","correct":true},{"t":"39, 41, 43","mis":"M5-2-u1-X02"},{"t":"55, 59, 62","mis":"M5-2-u1-X03"},{"t":"39","mis":"M5-2-u1-X16"}],"explanation":["43 미만인 수는 43보다 작은 수예요.","경곗값을 살펴보면 43은 들어가지 않아요.","그래서 39, 41이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#2','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',1,'mc','auto','68 초과 74 이하인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u1-X04']::text[],false,'{"seq":2,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"68 초과 74 이하인 수를 수직선에 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"68에 ○, 74에 ●을 그리고 두 점 사이를 선으로 잇는다","correct":true},{"t":"68에 ●, 74에 ●을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"},{"t":"68에 ○, 74에 ○을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"},{"t":"68에 ●, 74에 ○을 그리고 두 점 사이를 선으로 잇는다","mis":"M5-2-u1-X04"}],"explanation":["이상·이하는 ●, 초과·미만은 ○으로 나타내요.","68은 포함하지 않으니 ○ · 74는 포함하니 ●.","두 점 사이를 선으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#3','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',1,'mc','auto','20, 17.8, 25, 21.3, 18.6, 16, 19.1, 30 중에서 19 초과 25 미만인 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],false,'{"seq":3,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"20, 17.8, 25, 21.3, 18.6, 16, 19.1, 30 중에서 19 초과 25 미만인 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"20, 21.3, 19.1","correct":true},{"t":"20, 25, 21.3, 19.1","mis":"M5-2-u1-X02"},{"t":"20, 21.3","mis":"M5-2-u1-X16"},{"t":"20, 21.3, 19.1, 17.8","mis":"M5-2-u1-X16"}],"explanation":["19 초과 25 미만인 수는 19보다 크고 25보다 작은 수예요.","경곗값을 살펴보면 19는 들어가지 않고, 25는 들어가지 않아요.","그래서 20, 21.3, 19.1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#4','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',1,'mc','auto','4.67을 올림, 버림, 반올림하여 소수 첫째 자리까지 차례로 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":4,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"4.67을 올림, 버림, 반올림하여 소수 첫째 자리까지 차례로 나타낸 것은 어느 것인가요?","options":[{"t":"4.7, 4.6, 4.7","correct":true},{"t":"4.6, 4.7, 4.7","mis":"M5-2-u1-X08"},{"t":"4.7, 4.6, 4.6","mis":"M5-2-u1-X08"},{"t":"4.67, 4.67, 4.67","mis":"M5-2-u1-X09"}],"explanation":["올림: 소수 첫째 자리 아래 수를 올려 4.7이에요.","버림: 소수 첫째 자리 아래 수를 버려 4.6이에요.","반올림: 바로 아래 숫자 7을 보고 4.7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#5','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C6',1,'mc','auto','5.602, 5.58, 5.061, 5.63, 5.51 중에서 반올림하여 소수 첫째 자리까지 나타내면 5.5가 되는 수는 어느 것인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09','M5-2-u1-X16']::text[],false,'{"seq":5,"concept":"M5-2-u1-C6","difficulty":1,"kind":"mc","stem":"5.602, 5.58, 5.061, 5.63, 5.51 중에서 반올림하여 소수 첫째 자리까지 나타내면 5.5가 되는 수는 어느 것인가요?","options":[{"t":"5.51","correct":true},{"t":"5.58","mis":"M5-2-u1-X08"},{"t":"5.061","mis":"M5-2-u1-X09"},{"t":"5.602","mis":"M5-2-u1-X16"}],"explanation":["소수 둘째 자리 숫자를 보고 버리거나 올려요.","5.51은 소수 둘째 자리 1을 버려 5.5예요.","5.58은 8을 올려 5.6이 되니 5.5가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#6','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',1,'mc','auto','엘리베이터에는 10명까지 탈 수 있어요. 학생 53명이 모두 이동하려면 엘리베이터는 최소 몇 번 운행해야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X16']::text[],false,'{"seq":6,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"엘리베이터에는 10명까지 탈 수 있어요. 학생 53명이 모두 이동하려면 엘리베이터는 최소 몇 번 운행해야 하나요?","options":[{"t":"6번","correct":true},{"t":"5번","mis":"M5-2-u1-X13"},{"t":"53번","mis":"M5-2-u1-X14"},{"t":"10번","mis":"M5-2-u1-X16"}],"explanation":["5번 운행하면 50명이 이동하고 3명이 남아요.","남은 3명도 타야 하니 올림해요.","53을 올림하여 십의 자리까지 60 — 6번 운행해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#7','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',1,'mc','auto','5학년 남학생인 정우의 몸무게가 36 kg이에요. 정우가 속한 체급은 어느 것인가요?',ARRAY['M5-2-u1-X02','M5-2-u1-X16']::text[],false,'{"seq":7,"concept":"M5-2-u1-C3","difficulty":1,"kind":"mc","stem":"5학년 남학생인 정우의 몸무게가 36 kg이에요. 정우가 속한 체급은 어느 것인가요?","options":[{"t":"밴텀급","correct":true},{"t":"페더급","mis":"M5-2-u1-X02"},{"t":"플라이급","mis":"M5-2-u1-X16"},{"t":"핀급","mis":"M5-2-u1-X16"}],"explanation":["36 kg은 34 kg 초과 36 kg 이하에 들어요.","페더급은 36 kg 초과라 36 kg이 들지 않아요.","그래서 밴텀급이에요."],"asset":{"type":"passage","lines":["체급별 몸무게(초등학교 5학년 남학생용)","핀급 — 32 kg 이하","플라이급 — 32 kg 초과 34 kg 이하","밴텀급 — 34 kg 초과 36 kg 이하","페더급 — 36 kg 초과 39 kg 이하"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#8','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',1,'mc','auto','밭에서 캔 감자 658 kg을 한 상자에 10 kg씩 담아 팔려고 해요. 알맞은 어림 방법과 상자에 담아 팔 수 있는 감자의 무게를 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-2-u1-X13','M5-2-u1-X09']::text[],false,'{"seq":8,"concept":"M5-2-u1-C7","difficulty":1,"kind":"mc","stem":"밭에서 캔 감자 658 kg을 한 상자에 10 kg씩 담아 팔려고 해요. 알맞은 어림 방법과 상자에 담아 팔 수 있는 감자의 무게를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"버림, 650 kg","correct":true},{"t":"올림, 660 kg","mis":"M5-2-u1-X13"},{"t":"반올림, 660 kg","mis":"M5-2-u1-X13"},{"t":"버림, 600 kg","mis":"M5-2-u1-X09"}],"explanation":["10 kg이 안 되는 감자는 상자에 담아 팔 수 없어요.","그래서 버림하여 십의 자리까지 나타내요.","658 → 650 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#9','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C2',2,'sa','auto','뾰로롱 방 탈출 — 「3 초과 5 이하인 수 중에서 가장 작은 자연수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M5-2-u1-C2","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「3 초과 5 이하인 수 중에서 가장 작은 자연수」의 답을 숫자로 쓰세요.","answer":["4"],"explanation":["3 초과라 3은 들어가지 않아요.","3 초과 5 이하인 자연수는 4, 5예요.","가장 작은 자연수는 4 — 「쏭」을 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#10','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',2,'sa','auto','뾰로롱 방 탈출 — 「7 초과 9 미만인 자연수」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「7 초과 9 미만인 자연수」의 답을 숫자로 쓰세요.","answer":["8"],"explanation":["7과 9는 들어가지 않아요.","7 초과 9 미만인 자연수는 8 하나예요.","답은 8 — 「루」를 써넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#11','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',2,'sa','auto','뾰로롱 방 탈출 — 「3 이상 5 미만인 자연수의 곱」의 답을 숫자로 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M5-2-u1-C3","difficulty":2,"kind":"sa","stem":"뾰로롱 방 탈출 — 「3 이상 5 미만인 자연수의 곱」의 답을 숫자로 쓰세요.","answer":["12"],"explanation":["3 이상 5 미만인 자연수는 3, 4예요.","3 × 4 = 12예요.","답은 12 — 「뿅」을 써넣으면 주문 「알쏭달쏭떼구루루두둥실뿅」이 완성돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#12','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C4',2,'sa','auto','8001을 올림하여 천의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":12,"concept":"M5-2-u1-C4","difficulty":2,"kind":"sa","stem":"8001을 올림하여 천의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["9000"],"explanation":["올림은 천의 자리 아래 수를 올려서 나타내요.","아래 수가 0이 아니면 천의 자리 숫자를 1 크게 하고 아래는 0으로 해요.","8001 → 9000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#13','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C5',2,'sa','auto','3582를 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M5-2-u1-C5","difficulty":2,"kind":"sa","stem":"3582를 버림하여 십의 자리까지 나타내면 얼마인가요? 숫자로 쓰세요.","answer":["3580"],"explanation":["버림은 십의 자리 아래 수를 어떤 수든 버려요.","버린 자리는 0으로 하거나(자연수) 없애요(소수).","3582 → 3580이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#14','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C6',2,'sa','auto','어제 하루 동안 박물관에 방문한 관람객은 8542명이에요. 반올림하여 천의 자리까지 나타내면 몇 명인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M5-2-u1-C6","difficulty":2,"kind":"sa","stem":"어제 하루 동안 박물관에 방문한 관람객은 8542명이에요. 반올림하여 천의 자리까지 나타내면 몇 명인가요? 숫자로 쓰세요.","answer":["9000"],"explanation":["반올림은 구하려는 자리 바로 아래 한 자리만 봐요.","천의 자리 바로 아래 숫자가 5라 올려요.","8542 → 9000이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#15','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C4',2,'error','auto','두 친구의 말을 읽고 잘못 말한 것을 고르세요.',ARRAY['M5-2-u1-X08','M5-2-u1-X17']::text[],false,'{"seq":15,"concept":"M5-2-u1-C4","difficulty":2,"kind":"error","stem":"두 친구의 말을 읽고 잘못 말한 것을 고르세요.","options":[{"t":"우제 — 「2406을 올림하여 백의 자리까지 나타내면 2400이에요.」","correct":true,"mis_target":"M5-2-u1-X08"},{"t":"현지 — 「7415를 올림하여 천의 자리까지 나타내면 8000이에요.」","mis":"M5-2-u1-X17"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u1-X08"}],"explanation":["2406을 올림하여 백의 자리까지 나타내면 2500이에요.","2400은 버림한 수예요.","7415를 올림하여 천의 자리까지 나타내면 8000 — 현지는 바르게 말했어요."],"asset":{"type":"speech","turns":[{"who":"우제","text":"2406을 올림하여 백의 자리까지 나타내면 2400이에요."},{"who":"현지","text":"7415를 올림하여 천의 자리까지 나타내면 8000이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#16','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C1',2,'mc','auto','기록이 167 cm 이상인 학생과 122 cm 이하인 학생을 바르게 짝지은 것은 어느 것인가요?',ARRAY['M5-2-u1-X01','M5-2-u1-X16','M5-2-u1-X03']::text[],false,'{"seq":16,"concept":"M5-2-u1-C1","difficulty":2,"kind":"mc","stem":"기록이 167 cm 이상인 학생과 122 cm 이하인 학생을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"세진 / 상현, 보겸, 재인","correct":true},{"t":"세진 / 상현, 보겸","mis":"M5-2-u1-X01"},{"t":"지호, 세진 / 상현, 보겸, 재인","mis":"M5-2-u1-X16"},{"t":"지호, 상현, 보겸, 재인 / 세진","mis":"M5-2-u1-X03"}],"explanation":["167 cm 이상은 세진 175 cm뿐이에요.","122 cm 이하는 상현, 보겸, 그리고 딱 122 cm인 재인이에요.","그래서 세진 / 상현, 보겸, 재인이에요."],"asset":{"type":"passage","lines":["지호네 모둠 학생들의 제자리멀리뛰기 기록","지호 141 cm · 상현 105.6 cm · 보겸 99.4 cm","재인 122 cm · 세진 175 cm"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#17','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',3,'sa','auto','86, 87, 88, 89, 90, 91은 「□ 초과 91 이하인 자연수」를 모두 쓴 것이에요. □에 알맞은 자연수를 쓰세요.','{}'::text[],false,'{"seq":17,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"86, 87, 88, 89, 90, 91은 「□ 초과 91 이하인 자연수」를 모두 쓴 것이에요. □에 알맞은 자연수를 쓰세요.","answer":["85"],"explanation":["초과는 경곗값을 포함하지 않아요.","가장 작은 수 86보다 1 작은 수가 경곗값이에요.","□는 85예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#18','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',3,'sa','auto','뾰로롱 방 탈출 — 「12 미만인 수 중에서 가장 큰 자연수」(실)의 답에서 「25 이상 30 이하인 자연수의 개수」(구)의 답을 빼면 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":18,"concept":"M5-2-u1-C3","difficulty":3,"kind":"sa","stem":"뾰로롱 방 탈출 — 「12 미만인 수 중에서 가장 큰 자연수」(실)의 답에서 「25 이상 30 이하인 자연수의 개수」(구)의 답을 빼면 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["12 미만인 수 중 가장 큰 자연수는 11이에요.","25 이상 30 이하인 자연수는 6개예요.","11 − 6 = 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#19','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C4',3,'sa','auto','네 자리 수 2□31을 올림하여 백의 자리까지 나타내면 2700이에요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":19,"concept":"M5-2-u1-C4","difficulty":3,"kind":"sa","stem":"네 자리 수 2□31을 올림하여 백의 자리까지 나타내면 2700이에요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["올림하여 2700이 되는 수는 2601부터 2700까지예요.","2□31의 아래 수 31을 올리면 백의 자리 숫자가 1 커져요.","□ + 1 = 7이니 □는 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#20','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',3,'mc','auto','㉠ 9715를 올림하여 백의 자리까지 나타낸 수와 ㉡ 9769를 반올림하여 십의 자리까지 나타낸 수의 합은 얼마인가요?',ARRAY['M5-2-u1-X08','M5-2-u1-X09']::text[],false,'{"seq":20,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"㉠ 9715를 올림하여 백의 자리까지 나타낸 수와 ㉡ 9769를 반올림하여 십의 자리까지 나타낸 수의 합은 얼마인가요?","options":[{"t":"19570","correct":true},{"t":"19500","mis":"M5-2-u1-X08"},{"t":"19560","mis":"M5-2-u1-X08"},{"t":"19670","mis":"M5-2-u1-X09"}],"explanation":["㉠ 9715 → 9800이에요.","㉡ 9769 → 9770이에요.","9800 + 9770 = 19570이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#21','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C7',3,'mc','auto','1200원짜리 음료수 3개를 사려고 해요. 1000원짜리 지폐로만 내려면 최소 얼마를 내야 하나요?',ARRAY['M5-2-u1-X13','M5-2-u1-X14','M5-2-u1-X09']::text[],false,'{"seq":21,"concept":"M5-2-u1-C7","difficulty":3,"kind":"mc","stem":"1200원짜리 음료수 3개를 사려고 해요. 1000원짜리 지폐로만 내려면 최소 얼마를 내야 하나요?","options":[{"t":"4000원","correct":true},{"t":"3000원","mis":"M5-2-u1-X13"},{"t":"3600원","mis":"M5-2-u1-X14"},{"t":"10000원","mis":"M5-2-u1-X09"}],"explanation":["1200 × 3 = 3600(원)이에요.","모자라면 안 되니 올림하여 천의 자리까지 나타내요.","4000원을 내야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#22','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C4',3,'mc','auto','301, 310, 311, 314, 320, 321, 324 중에서 올림하여 십의 자리까지 나타내면 320이 되는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u1-X07','M5-2-u1-X08','M5-2-u1-X15']::text[],false,'{"seq":22,"concept":"M5-2-u1-C4","difficulty":3,"kind":"mc","stem":"301, 310, 311, 314, 320, 321, 324 중에서 올림하여 십의 자리까지 나타내면 320이 되는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"311, 314, 320","correct":true},{"t":"310, 311, 314, 320","mis":"M5-2-u1-X07"},{"t":"311, 314, 320, 321, 324","mis":"M5-2-u1-X08"},{"t":"311, 314","mis":"M5-2-u1-X15"}],"explanation":["311부터 320까지의 수가 올림하여 320이 돼요.","310은 그대로 310, 321·324는 330이에요.","311, 314, 320이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#23','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',4,'essay','teacher','자연수 부분이 2이고, 소수 첫째 자리 숫자가 5 이상 8 미만인 소수 한 자리 수를 모두 쓰고, 2.5는 넣고 2.8은 넣지 않는 까닭을 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"자연수 부분이 2이고, 소수 첫째 자리 숫자가 5 이상 8 미만인 소수 한 자리 수를 모두 쓰고, 2.5는 넣고 2.8은 넣지 않는 까닭을 설명하세요.","answer_guide":{"answer":"예: 2.5, 2.6, 2.7이다. 소수 첫째 자리 숫자가 5 이상이므로 5는 포함되어 2.5를 넣고, 8 미만이므로 8은 포함되지 않아 2.8은 넣지 않는다.","scoring_points":["2.5, 2.6, 2.7을 모두 썼는가","5 이상이라 5가 포함된다고 썼는가","8 미만이라 8이 포함되지 않는다고 썼는가"]},"explanation":["소수 첫째 자리 숫자는 5, 6, 7이에요.","5 이상은 5를 포함하고, 8 미만은 8을 포함하지 않아요.","그래서 2.5, 2.6, 2.7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#24','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C8',4,'mc','auto','(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 계산기로 탄두리치킨 재료의 실제 구입 비용을 구하면 얼마인가요?',ARRAY['M5-2-u1-X17','M5-2-u1-X16']::text[],false,'{"seq":24,"concept":"M5-2-u1-C8","difficulty":4,"kind":"mc","stem":"(단, 재료는 정해진 단위로 최소한의 양만 구입합니다.) 계산기로 탄두리치킨 재료의 실제 구입 비용을 구하면 얼마인가요?","options":[{"t":"191950원","correct":true},{"t":"196000원","mis":"M5-2-u1-X17"},{"t":"176000원","mis":"M5-2-u1-X16"},{"t":"185500원","mis":"M5-2-u1-X16"}],"explanation":["8800 × 20 = 176000, 1900 × 5 = 9500이에요.","2150 × 3 = 6450이에요.","176000 + 9500 + 6450 = 191950(원)이에요."],"asset":{"type":"passage","lines":["탄두리치킨(인도)에 필요한 재료의 양","닭고기 20마리 · 카레 가루 480 g · 고춧가루 220 g","판매 단위당 가격","닭고기 한 봉지 1마리 8800원","카레 가루 한 봉지 100 g 1900원","고춧가루 한 봉지 100 g 2150원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u1_review_d#25','math',5,2,'u1','','tb_g5_2_math_u1_review_d','unit_review','M5-2-u1-C3',4,'essay','teacher','11세인 은우와 19세인 형이 박물관에 가요. 은우와 형의 나이가 각각 어느 범위에 드는지 설명하고 두 사람의 입장료는 모두 얼마인지 구하세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u1-C3","difficulty":4,"kind":"essay","stem":"11세인 은우와 19세인 형이 박물관에 가요. 은우와 형의 나이가 각각 어느 범위에 드는지 설명하고 두 사람의 입장료는 모두 얼마인지 구하세요.","answer_guide":{"answer":"예: 은우 11세는 13세 미만이라 어린이 1000원이다. 형 19세는 13세 이상 19세 미만에 들지 않고 19세 이상에 들어 어른 2000원이다. 모두 3000원이다.","scoring_points":["은우가 13세 미만(어린이)임을 썼는가","형 19세가 19세 미만이 아니라 19세 이상에 든다고 썼는가","3000원을 구했는가"]},"explanation":["은우 11세는 13세 미만 — 1000원이에요.","19세 미만에는 19세가 들지 않아 형은 19세 이상 — 2000원이에요.","모두 3000원이에요."],"asset":{"type":"passage","lines":["박물관 입장료","어린이(13세 미만) — 1000원","청소년(13세 이상 19세 미만) — 1500원","어른(19세 이상) — 2000원"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
